          // deux, ce test se trouve lui-même.
          const aig=['centralis'+'és sur le compte','paiements sont '+'centralisés',
            'reviennent exclusivement au '+'créateur','vont sur le PayPal de '+'CREATOR_EMAIL'];
          const tout=_prodSrc();
          const fin=tout.length;
