          const src=String(_genAccessCode).replace(/\s+/g,'');
          if(src.indexOf("etat:'envoye'")<0) return _echec('l\'état initial n\'est pas posé');
          for(const c of ['ouvertLe:null','creeLe:null','relanceLe:null'])
            if(src.indexOf(c)<0) return _echec('champ manquant : '+c);
          // Prénom et nom séparés : recomposer un prénom depuis « studentName »
          // se trompe dès qu'un nom en porte deux.
          if(src.indexOf('prenom:')<0||src.indexOf('nom:')<0) return _echec('prénom/nom absents');
