          if(!relancePossible(jamais).ok) return _echec('une invitation jamais relancée est bloquée');
          const t0=Date.now();
          const fraiche=_inv('T2','envoye',{relanceLe:new Date(t0-3600000).toISOString()});
          const r=relancePossible(fraiche,t0);
          if(r.ok) return _echec('relance acceptée une heure après');
          // On DIT le temps qui reste : griser sans expliquer apprend à
