          // fixture n'en portait aucune, et elle tombait donc sur la question
          // de propriete — « sans adresse, sur un appareil a deux comptes, on
          // ne devine pas » — pour un test qui ne cherchait pas a le savoir.
          // C'est ce qui le laissait rouge dans la base sans qu'on comprenne.
          //
          // LE CAS SANS ADRESSE A SA PROPRE ASSERTION, plus bas : « un
          // brouillon sans adresse est propose quand un seul compte est
          // connecte ». Chacune eprouve une chose.
          const plein={bilType:'coaching',bilStep:2,bilData:{poids:'72'},ts:Date.now(),
            email:(currentUser&&currentUser.email)||''};
          poser(plein);
          if(!_bilLoadDraft('coaching')) return _echec('un brouillon valide est rejeté');
          // Un questionnaire de départ abandonné ne doit pas s'inviter dans
          // un bilan de suivi : les questions ne sont pas les mêmes.
          if(_bilLoadDraft('depart')) return _echec('le type n\'est plus vérifié');
          // La péremption est encadrée, jamais testée sur la borne exacte :
          // quelques millisecondes s'écoulent entre l'écriture et la lecture.
          poser({...plein,ts:Date.now()-6.9*24*3600*1000});
          if(!_bilLoadDraft('coaching')) return _echec('6,9 jours est refusé à tort');
          poser({...plein,ts:Date.now()-7.1*24*3600*1000});
          if(_bilLoadDraft('coaching')) return _echec('7,1 jours est encore accepté');
          // Ouvrir puis refermer sans rien saisir ne doit rien proposer.
          if(_bilDraftRempli({bilData:{}})!==0) return _echec('un brouillon vide compte');
          if(_bilDraftRempli({bilData:{a:'',b:null,c:[]}})!==0)
            return _echec('des champs vides comptent comme des réponses');
          if(_bilDraftRempli({bilData:{a:'x',b:['y']}})!==2)
            return _echec('le décompte des réponses est faux');
          // Un contenu illisible ne fait pas tomber l'écran.
          localStorage.setItem(BIL_DRAFT_KEY,'{pas du json');
