          // suffirait a poser une methode depuis un dossier d'athlete.
          currentUser={id:'a',role:'client',email:'a@t'};
          progEx=[{name:'SQUAT',series:4,reps:'10'}]; _progExDirty=false;
          _progExTechnique(0,'rest_in_pause');
