      // ══════ N1.14 ET N1.17 — LE RANGEMENT PAR SUJET ══════
      ok('N1.14 — LE RITE DE CYCLE PRECEDE LES BILANS, dont il est la famille',(()=>{
        const r=document.getElementById('ccd-rite'), b=document.getElementById('ccd-bilans');
        if(!r||!b) return _echec('une des deux sections a disparu');
        const vr=r.closest('.ccd-vue'), vb=b.closest('.ccd-vue');
        if(!vr||vr!==vb) return _echec('elles ne sont pas dans le meme onglet');
        // AVANT les bilans : lui porte une question POSEE, quelqu'un attend au
        // bout. compareDocumentPosition rend FOLLOWING quand b suit r.
        if(!(r.compareDocumentPosition(b)&Node.DOCUMENT_POSITION_FOLLOWING))
          return _echec('le rite est passe SOUS les bilans');
        // ccdAller retrouve encore son onglet : il le deduit du DOM, pas d'une
        // table — c'est ce qui rend le deplacement sans risque.
        return /closest\('\.ccd-vue'\)/.test(String(ccdAller))
          ?true:_echec('ccdAller ne deduit plus l\'onglet du balisage');})());

      ok('N1.17 — LE PANNEAU PAIEMENTS EST RANGE PAR SUJET, rien n\'a disparu',(()=>{
        const p=document.getElementById('ct-monetisation');
        if(!p) return _echec('panneau absent');
        // LES DOUZE BLOCS SONT TOUJOURS LA. Un regroupement qui perd un bloc
        // serait pire que le desordre : loadMonetisationTab remplit par id.
        const ids=['ch-lien-tunnel','coach-abo','pp-total-subs','pp-mrr','pp-cancelled',
          'pp-subs-list','cld-cloud-name','cld-preset','cloud-status','cloud-sw-version',
          'exp-manifeste','cloud-qr-btn','coach-admin-offboard','admin-offboard-select'];
        const perdus=ids.filter(id=>!p.querySelector('#'+id));
        if(perdus.length) return _echec('sorti(s) du panneau : '+perdus.join(', '));
        // L'ORDRE DES QUATRE GROUPES. On le lit sur des ancres reelles, pas sur
        // les titres : un titre se renomme, un identifiant non.
        const rang=id=>Array.prototype.indexOf.call(p.querySelectorAll('*'),p.querySelector('#'+id));
        const suite=[['argent','pp-subs-list'],['technique','cld-cloud-name'],
                     ['compte','exp-manifeste'],['administration','admin-offboard-select']];
        for(let i=1;i<suite.length;i++)
          if(rang(suite[i][1])<rang(suite[i-1][1]))
            return _echec(suite[i][0]+' remonte avant '+suite[i-1][0]);
        // FERMER SON COMPTE N'EST PAS UN PAIEMENT : la zone dangereuse est
        // passee SOUS le groupe du compte, plus au milieu des abonnes.
        // On la repere par son GESTE — la suppression de compte — et non par
        // son texte : le panneau entier contient ce texte, et un find sur le
        // texte remonte au conteneur au lieu du bloc.
        const sup=p.querySelector('[onclick*="requestAccountDeletion"]');
        if(!sup) return _echec('la zone dangereuse a disparu');
        const tous=Array.prototype.slice.call(p.querySelectorAll('*'));
        if(rang('exp-manifeste')>tous.indexOf(sup))
          return _echec('la zone dangereuse precede l\'export RGPD');
        // LES BLOCS DU CREATEUR RESTENT ETEINTS pour les autres comptes : c'est
        // loadCoachDashboard qui les allume, jamais le balisage.
        for(const id of ['ch-lien-tunnel','coach-admin-offboard'])
          if((document.getElementById(id).getAttribute('style')||'').indexOf('display:none')<0)
            return _echec(id+' n\'est plus eteint par defaut');
        return true;})());

      ok('N1.11 — UNE SEULE BARRE D\'ETAT, et chaque nombre ouvre SA liste',(()=>{
        if(typeof renderPortefeuille!=='function') return _echec('aucune barre d\'etat');
        // LES PREDICATS DE COMPTAGE ET DE FILTRAGE SONT LES MEMES, un par un.
        // C'est la seule chose qui rende un compteur cliquable honnete, et le
        // commentaire de renderClientList le disait deja des trois premiers.
        const j=Date.now();
        const mk=(n,o)=>Object.assign({id:'N'+n,email:'n'+n+'@t.fr',role:'athlete',
          fname:'N'+n,lname:'X',coachId:'CX',createdAt:j-40*864e5,
          bilans:[],sessions:[],videos:[]},o||{});
        const l=[mk(1),
          mk(2,{sessions:[{date:j-2*864e5,name:'S'}],bilans:[{type:'suivi',date:j-3*864e5}]}),
          mk(3,{_fromCode:true,email:''}),
          mk(4,{sessions:[{date:j-30*864e5,name:'S'}],bilans:[{type:'suivi',date:j-1*864e5}]})];
        let r;
        try{ r=agregerPortefeuille(l,{now:j}); }catch(e){ return _echec('agregation : '+e.message); }
        const p=r.portefeuille;
        // La table apparie le nombre annonce et le predicat de la liste. Elle
        // reproduit renderClientList : si l'un des deux bouge sans l'autre,
        // cette assertion tombe, ce qui est exactement le but.
        const paires=[
          ['pf-traiter',   r.aTraiter,        c=>urgencyScore(c)>=PIL_SEUIL_TRAITER],
          ['pf-decrochage',r.decrochage,      c=>_pilEligibleSignaux(c)&&signauxEntrainement(c).decrochage],
          ['pf-acces',     r.accesExpirent,   c=>_pilEligibleSignaux(c)&&_pilAccesExpire(c,j)],
          ['traiter',      p.alertes,         c=>needsAlert(c)||hasNewBilan(c)],
          ['pf-jamais',    p.jamaisDemarres,  c=>neverStarted(c)],
          ['attente',      p.enAttente,       c=>c._fromCode||!c.email],
          ['pf-actifs',    p.actifs,          c=>isActive(c)],
          ['tous',         p.total,           ()=>true]];
        const src=String(renderClientList);
        for(const [cle,n,pred] of paires){
          let reel=0;
          for(const c of l){ try{ if(pred(c)) reel++; }catch(e){} }
          if(reel!==n)
            return _echec(cle+' annonce '+n+' et sa liste en montre '+reel);
          // ET LE FILTRE EXISTE VRAIMENT dans renderClientList : un compteur
          // dont la clef n'y est pas rendrait la liste entiere, sans un mot.
          if(cle!=='tous'&&src.indexOf("==='"+cle+"'")<0)
            return _echec('aucun filtre pour la clef '+cle);
        }
        // LES DEUX AUTRES DESCRIPTIONS ONT DISPARU. Le meme portefeuille etait
        // dit trois fois dans le meme panneau : les trois metric-box muets, la
        // bande « Portefeuille » du volet, et les compteurs du volet.
        const pan=document.getElementById('ct-dashboard');
        if(!pan) return _echec('panneau absent');
        for(const id of ['ch-total','ch-active','ch-alerts','ch-filtres'])
          if(pan.querySelector('#'+id)) return _echec(id+' est encore la');
        if(/_tt\('Portefeuille'\)/.test(String(renderPilotage)))
          return _echec('le volet redit le portefeuille');
        if(/_pilCompteur\(/.test(String(renderPilotage)))
          return _echec('les compteurs sont restes dans le volet');
        if(!/_pilCompteur\(/.test(String(renderPortefeuille)))
          return _echec('la barre n\'utilise pas les compteurs existants');
        // ⚠ CETTE REGLE A CHANGE LE 16/09/2026, et l'assertion avec elle.
        // Tant que 'tous' etait l'etat PAR DEFAUT, il etait aussi le retour en
        // arriere, et il ne pouvait donc pas se retirer : s'y re-cliquer
        // l'aurait repose sur place. Depuis que ce qui dort descend en bas de
        // page, la vue par defaut est 'travail' — un etat qui n'a pas de puce,
        // parce que ce n'est pas un filtre qu'on choisit mais l'ecran tel qu'il
        // s'ouvre. « Tous » est redevenu une puce ordinaire : elle s'allume, et
        // se re-toucher la rend.
        //
        // CE QUE CETTE LIGNE PROTEGE N'A PAS CHANGE : re-toucher une puce
        // allumee doit RAMENER quelque part, jamais laisser le coach coince
        // dans un filtre qu'il ne sait plus retirer.
        if(!/'travail'/.test(String(_pilCompteur)))
          return _echec('le retour en arriere ne vise pas la vue de travail');
        return /cible=actif\?'travail':cle/.test(String(_pilCompteur))
          ?true:_echec('une puce allumee ne se retire pas : '+String(_pilCompteur).slice(0,0));})());

      // ⚠ TROIS ASSERTIONS ONT ETE RETIREES ICI (N2.3, N2.7 et N2.21). Elles
      // eprouvaient _htmlAthleteVoit — le bloc « ce que voit ton athlete » de
      // la fiche coach — RETIRE le 08/09/2026 avec ecartAthleteVu : voir la
      // pierre tombale dans index.html, juste avant les tableaux du calcul.
      // Elles ne testaient donc plus rien, elles LEVAIENT ; et la suite etant
      // un seul try, tout ce qui les suivait ne s'executait plus.
      // CE QUI PORTAIT LEUR RAISON D'ETRE NE DISPARAIT PAS AVEC ELLES : le
      // decalage entre la copie enregistree et le calcul vivant est dit par
      // _cplHtmlDesync et par le bouton « Appliquer ces cibles », tous deux
      // couverts ailleurs. Ce qui reste a tenir ici, c'est que le bloc ne
      // revienne pas : il redisait au coach, par un second chemin, les
      // chiffres que l'ecran de l'athlete calcule deja.
      ok('Le bloc « ce que voit ton athlete » reste retire, pas revenu',
         typeof _htmlAthleteVoit==='undefined'&&typeof ecartAthleteVu==='undefined',
         'un second chemin d\'affichage des memes chiffres est de retour');



      ok('N2.6 — UN SEUL POIDS DE REFERENCE, et les trois lectures s\'y ramenent',(()=>{
        if(typeof poidsNutritionnel!=='function') return _echec('aucune source unique');
        const j=Date.now();
        const iso=d=>new Date(d).toISOString().slice(0,10);
        // LE DOSSIER DU DOC : le dernier bilan ne porte PAS de poids, mais le
        // journal de pesees est a jour. Avant, besoinsProposes retombait sur
        // init-weight (80 kg, l'inscription), poidsReference remontait au
        // bilan qui en portait un (74) et le plancher lisait la pesee (71) :
        // trois nombres, trois lignes du meme panneau.
        const u={id:'PN',email:'pn@t.fr',role:'athlete',gender:'H',_evol_gender:'H',
          _evol_height:'178','init-age':32,'init-weight':'80',
          createdAt:j-300*864e5,
          bilans:[{type:'debut',date:j-120*864e5,'deb-weight':'74','deb-height':'178',
                   'deb-age':'32','deb-gender':'Homme'},
                  {type:'suivi',date:j-2*864e5,'bil-mood':'4'}],
          weightLog:[{date:iso(j-30*864e5),kg:73},{date:iso(j-3*864e5),kg:71}],
          sessions:[],videos:[]};
        const r=poidsNutritionnel(u);
        if(r.kg!==71) return _echec('le poids de reference vaut '+r.kg+' et non la derniere pesee (71)');
        if(r.source!=='pesee') return _echec('provenance annoncee : '+r.source);
        // LES TROIS LECTURES RENDENT LE MEME NOMBRE.
        if(poidsReference(u)!==71) return _echec('les g/kg lisent '+poidsReference(u));
        if(_poidsPourPlancher(u)!==71) return _echec('le plancher lit '+_poidsPourPlancher(u));
        const b=besoinsProposes(u);
        if(!b||b.source===null) return _echec('aucune proposition : '+((b&&b.manque)||[]).join(', '));
        // Le metabolisme doit etre celui de 71 kg, pas celui de 80.
        if(b.mb!==mbMifflin(71,178,32,'Homme'))
          return _echec('les grammages sont cales sur un autre poids : mb='+b.mb
            +' contre '+mbMifflin(71,178,32,'Homme')+' a 71 kg');
        // (L'encadré « Poids de référence » qui l'affichait a été retiré de la
        // fiche coach le 22/09/2026, build 1402 : la lecture reste, pas lui.)
        // SANS AUCUNE PESEE NI BILAN CHIFFRE : le poids d'inscription sert de
        // dernier recours, et il est dit comme n'ayant jamais ete mesure.
        const v={id:'PV',email:'pv@t.fr','init-weight':'80',bilans:[],weightLog:[]};
        const rv=poidsNutritionnel(v);
        if(rv.kg!==80||rv.source!=='initial') return _echec('dernier recours : '+JSON.stringify(rv));
        return true;})());

      // BUILD 1402 — Kevin, captures a l'appui : « mets pas de menu déroulant
      // mais plutôt un titre « Calculs alimentaires », et supprime les trucs »
      // (le bandeau « Réglé par l'athlète… » et le « Poids de référence »).
      ok('1402 — « CALCULS ALIMENTAIRES » EST UN TITRE, ET LES DEUX ENCADRÉS SONT PARTIS',(()=>{
        const z=document.getElementById('ccd-nutrition');
        const s=z&&z.closest('.cc-sect');
        if(!s) return _echec('la section des calculs a disparu');
        const t=s.querySelector(':scope>.cc-sect-t');
        const lib=t?t.textContent.trim():'';
        if(lib!=='Calculs alimentaires') return _echec('le titre est « '+lib+' »');
        // 1403 : le second mot en rouge, comme la maquette.
        if(!t.querySelector('em')||t.querySelector('em').textContent!=='alimentaires')
          return _echec('« alimentaires » n’est plus mis en valeur');
        if(!s.classList.contains('cc-sect-fixe')) return _echec('la section n’est pas marquée fixe');
        // MEME RETENUE REPLIEE par un ancien clic, elle s'ouvre, et son titre
        // n'est plus un bouton.
        let sv=null; try{ sv=localStorage.getItem(CCD_REPLI_CLE); }catch(e){}
        try{
          localStorage.setItem(CCD_REPLI_CLE,JSON.stringify({'ccd-nutrition':true}));
          ccdAppliquerReplis();
          if(s.classList.contains('replie')) return _echec('un repli retenu la ferme encore');
          if(t.hasAttribute('role')||t.hasAttribute('tabindex')||t.hasAttribute('aria-expanded'))
            return _echec('le titre se présente encore comme un bouton');
          // UN CLIC SUR LE TITRE NE LA REPLIE PAS.
          _ccdArmerReplis();
          t.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true}));
          if(s.classList.contains('replie')) return _echec('un clic sur le titre la replie');
          // NI CHEVRON NI MAIN.
          if(getComputedStyle(t,'::before').display!=='none') return _echec('le chevron est encore là');
          if(getComputedStyle(t).cursor==='pointer') return _echec('le titre montre encore une main');
          // LES AUTRES SECTIONS SE REPLIENT TOUJOURS.
          const autre=document.getElementById('ccd-journal');
          const sa=autre&&autre.closest('.cc-sect');
          const ta=sa&&sa.querySelector(':scope>.cc-sect-t');
          if(ta&&ta.getAttribute('role')!=='button') return _echec('les autres titres ont perdu leur repli');
        } finally {
          try{ if(sv==null) localStorage.removeItem(CCD_REPLI_CLE);
               else localStorage.setItem(CCD_REPLI_CLE,sv); }catch(e){}
          try{ ccdAppliquerReplis(); }catch(e){}
        }
        // LES DEUX ENCADRES : un athlete qui a regle « Sèche » et +200 kcal, et
        // une pesee — ni le bandeau ni le poids de reference ne sont rendus.
        if(typeof _htmlReglageAthleteCoach!=='undefined'||typeof htmlPoidsReference!=='undefined')
          return _echec('les fonctions des encadrés sont revenues');
        const sauve=currentUser;
        try{
          currentUser={id:'_t1402',email:'t1402@t.fr',role:'coach',fname:'K',seenBilans:{},alertStatus:{}};
          const j=Date.now();
          renderCoachNutriSection({id:'a1402',email:'a1402@t.fr',role:'athlete',gender:'H',_evol_gender:'H',
            _evol_height:'180','init-age':30,'init-weight':'100',createdAt:j-200*864e5,
            bilans:[{type:'debut',date:j-100*864e5,'deb-weight':'102','deb-height':'180',
                     'deb-age':'30','deb-gender':'Homme'}],
            weightLog:[{date:new Date(j-864e5).toISOString().slice(0,10),kg:100.9}],sessions:[],videos:[],
            nutrition:{tableur:{objectifAthlete:'seche',deltaAthlete:200},perso:{objectif:'seche',delta:200}}});
          const h=(z.textContent||'');
          if(/Réglé par l.athlète/.test(h)) return _echec('le bandeau « Réglé par l’athlète » est encore rendu');
          if(/Poids de référence/i.test(h)) return _echec('l’encadré « Poids de référence » est encore rendu');
          if(!z.querySelector('table.tbk')) return _echec('les tableaux de calcul ont disparu avec eux');
        } finally { currentUser=sauve; }
        return true;})());

      ok('N2.8 — LE MESSAGE DE PLANCHER NOMME LA REGLE QUI A GAGNE',(()=>{
        if(typeof direRegplePlancher!=='function') return _echec('la regle n’est pas dite');
        const j=Date.now();
        // DEUX DOSSIERS, comme le demande le doc : l'un avec tours de taille et
        // de cou — la masse maigre est calculable, c'est la regle a 30 kcal/kg
        // de masse maigre qui gagne — l'autre sans, ou c'est le poids total.
        const base=(o)=>Object.assign({id:'PL',email:'pl@t.fr',role:'athlete',
          gender:'H',_evol_gender:'H',_evol_height:'178','init-age':32,
          createdAt:j-300*864e5,weightLog:[{date:new Date(j-2*864e5).toISOString().slice(0,10),kg:80}],
          sessions:[],videos:[]},o||{});
        const sans=base({bilans:[{type:'debut',date:j-100*864e5,'deb-weight':'80',
          'deb-height':'178','deb-age':'32','deb-gender':'Homme'}]});
        const pSans=plancherEffectif(sans);
        const mSans=direRegplePlancher(pSans);
        // LE COACH DOIT POUVOIR REFAIRE LE NOMBRE A LA MAIN : la regle citee et
        // le nombre annonce decrivent la meme grandeur.
        if(pSans.regle==='poids_total'){
          if(mSans.indexOf(KCAL_PLANCHER_PAR_KG+' kcal/kg')<0)
            return _echec('regle poids_total non citee : '+mSans);
          if(mSans.indexOf('masse maigre')>=0)
            return _echec('la masse maigre est citee alors qu’elle n’a pas servi : '+mSans);
        } else if(pSans.regle==='absolu'){
          if(mSans.indexOf('minimum absolu')<0) return _echec('regle absolu non citee : '+mSans);
        }
        // Le second dossier porte les tours : masse maigre calculable.
        const avec=base({bilans:[{type:'debut',date:j-100*864e5,'deb-weight':'80',
          'deb-height':'178','deb-age':'32','deb-gender':'Homme',
          'deb-waist':'88','deb-neck':'39'}]});
        const pAvec=plancherEffectif(avec);
        if(pAvec.regle==='masse_maigre'){
          const m=direRegplePlancher(pAvec);
          if(m.indexOf(KCAL_PLANCHER_PAR_KG_MM+' kcal/kg de masse maigre')<0)
            return _echec('regle masse_maigre non citee : '+m);
          if(m.indexOf(KCAL_PLANCHER_PAR_KG+' kcal/kg pour')>=0)
            return _echec('les 22 kcal/kg sont cites alors qu’ils n’ont pas servi : '+m);
        }
        // LE PLAFONNEMENT SE DIT QUAND IL A JOUE, sinon le coach retrouve a la
        // main un nombre plus grand que celui affiche et croit a une erreur.
        const plafonne={regle:'masse_maigre',masseMaigre:70,poids:80,abs:1500,plafonne:true};
        if(direRegplePlancher(plafonne).indexOf('% de la dépense estimée')<0)
          return _echec('le plafonnement n’est pas dit');
        if(direRegplePlancher(Object.assign({},plafonne,{plafonne:false}))
             .indexOf('dépense estimée')>=0)
          return _echec('un plafonnement inexistant est annonce');
        // ET LE MESSAGE DE controlerMacros PORTE CETTE PHRASE, pas une autre.
        const v=controlerMacros({kcal:900,p:200,l:80},avec);
        const mk=(v.find(x=>x.champ==='kcal')||{}).message||'';
        return mk.indexOf(direRegplePlancher(pAvec))>=0
          ?true:_echec('le message ne porte pas la regle : '+mk);})());

      // ⚠ N2.10 ET N2.11 ONT ETE RETIREES ICI. Elles eprouvaient
