        if(portes.length!==3) return _echec(portes.length+' portes au lieu de 3');
        const t=portes.map(p=>p.querySelector('.wel-p-t').textContent.trim());
        if(t[0]!=='J\'ai un code coach') return _echec('la première porte : '+t[0]);
