    ok('Critère 8 : le tempo est expliqué',(()=>{
      const h=blocTempo({tempo:'3-1-1-0'});
      return /Tempo 3-1-1-0/.test(h)&&/3 s pour descendre/.test(h)&&/1 s en bas/.test(h)
        &&/1 s pour monter/.test(h)&&/0 s en haut/.test(h);})());
