      for(const [m,vue] of [['ABDUCTEURS','face'],['ADDUCTEURS','face'],['LOMBAIRES','dos']])
        if(!corpsTeintes(u,vue,{[m]:12})[m]) return _echec(m+' n’est toujours pas teinté');
      // LA RÈGLE, ELLE, TIENT TOUJOURS, et c'est le garde-fou qui compte : le
