    ok('LE NUMÉRO D\'ATHLÈTE SUIT L\'ORDRE D\'ARRIVÉE',(()=>{
      // Kevin, 20/09/2026 : « mets "athlète n°__ : Kévin Guellec" selon son
      // arrivée ». Le numéro s'affiche en tête de sa fiche.
      const J=864e5, t=Date.parse('2026-09-20T12:00:00Z');
      const A=(id,em,j,o)=>Object.assign({id,email:em,role:'athlete',
        createdAt:t-j*J},o||{});
      const anna=A('A1','a@t.fr',400), bruno=A('A2','b@t.fr',300),
            kev =A('A3','k@t.fr',200);
      // ⚠ LA LISTE EST DANS LE DESORDRE, et c'est le coeur du test : passee
      //   deja triee, elle aurait valide une fonction qui ne trie pas.
      const l=[kev,anna,bruno];
      if(rangArrivee(anna,l)!==1)
        return _echec('le plus ancien n’est pas le n°1 : '+rangArrivee(anna,l));
      if(rangArrivee(bruno,l)!==2) return _echec('Bruno est n°'+rangArrivee(bruno,l));
      if(rangArrivee(kev,l)!==3)   return _echec('Kévin est n°'+rangArrivee(kev,l));
      // `coachSince` PASSE DEVANT `createdAt` — dateRattachement le dit depuis
      // le 15/09, et le rang doit le suivre : un athlète inscrit il y a
      // longtemps mais rattaché la semaine dernière n'est pas arrivé le
      // premier. Le jour où ce champ sera écrit, ce test tiendra déjà.
      const tard=A('A4','z@t.fr',500,{coachSince:t-10*J});
      const l4=[anna,bruno,kev,tard];
      if(rangArrivee(tard,l4)!==4)
        return _echec('coachSince est ignoré : n°'+rangArrivee(tard,l4));
      // UNE INVITATION N'A PAS DE RANG, ET NE DÉCALE PERSONNE. Un code n'est
      // arrivé nulle part ; lui en donner un aurait renuméroté tout le monde
      // le jour où il expire sans avoir servi.
      const code=Object.assign(A('_code_1','',0),{_fromCode:true});
      const lc=[anna,code,bruno,kev];
      if(rangArrivee(code,lc)!==0) return _echec('une invitation reçoit un numéro');
      if(rangArrivee(kev,lc)!==3)
        return _echec('une invitation décale les autres : Kévin est n°'+rangArrivee(kev,lc));
      // ET UN DOSSIER ABSENT DU PORTEFEUILLE N'EN A PAS : mieux vaut aucun
      // numéro qu'un faux.
      if(rangArrivee(A('A9','n@t.fr',50),l)!==0)
        return _echec('un dossier absent du portefeuille reçoit un numéro');
      // L'ÉGALITÉ SE TRANCHE, ET TOUJOURS DE LA MÊME FAÇON. Deux comptes créés
      // dans la même milliseconde — un import, une restauration — auraient
      // sinon échangé leurs numéros d'un rendu à l'autre.
      const x=A('B1','x@t.fr',100), y=A('B2','y@t.fr',100);
      if(rangArrivee(x,[y,x])!==1||rangArrivee(y,[x,y])!==2)
        return _echec('deux arrivées simultanées échangent leurs numéros');
      return true;})());

    ok('La carte ne s’affiche pas quand la liste est vide',(()=>{
      // Une liste de relance qui s'affiche a zero devient du decor, et on
      // cesse de la lire le jour ou elle dit quelque chose.
      if(_htmlJamaisDemarre([],Date.now())!=='') return _echec('un cadre vide est rendu');
      const t=Date.now();
      // JOIGNABLE : depuis le 19/09/2026 la carte mene a deux gestes, et sans
      // adresse ni numero la feuille de relance le dit — ce qui est le bon
      // comportement, mais pas celui qu'on teste ici.
      //
      // ⚠ ALICE EST INSCRITE. C'est la nature meme de cette liste :
      //   `jamaisDemarre` ecarte `_fromCode`, donc elle ne voit QUE des gens
      //   qui ont cree leur compte. C'est ce qui la separe de « En attente »
      //   juste en dessous, ou personne n'a encore de compte.
      const h=_htmlJamaisDemarre([{id:'a1',fname:'Alice',lname:'Martin',
        createdAt:t-12*864e5,sessions:[],email:'alice@t.fr',phone:'+33600000000'}],t);
      if(!h) return _echec('la carte ne sort rien pour un athlete');
      const d=document.createElement('div'); d.innerHTML=h;
      // LE NOMBRE D'ATHLETES CONCERNES, demande explicitement.
      if(d.innerText.indexOf('1')<0) return _echec('le nombre n’est pas affiche');
      if(d.innerText.indexOf('Alice')<0) return _echec('le prenom n’est pas affiche');
      if(!/12 jours|12 jours/.test(d.innerText)) return _echec('les jours ne sont pas affiches : '+d.innerText);
      // ⚠ LA RELANCE NE PASSE PLUS PAR LE CANAL, depuis le 19/09/2026.
      //   Ce test exigeait UN SEUL bouton, menant a relancerJamaisDemarre, qui
      //   ouvrait la fenetre du canal avec un brouillon nominatif — lu par tous
      //   les athletes suivis. Demande de Kevin : une relance s'adresse a une
      //   personne.
      //
      // ⚠ LA FORME A CHANGE DEUX FOIS DE PLUS, le 19/09/2026 au soir. D'abord
      //   des RECTANGLES au lieu de la liste, avec « Code d'accès » et
      //   « Relancer ». Puis, une heure apres : HUIT PAR LIGNE et UN SEUL
      //   bouton, rouge. Le rapprochement qui retrouvait le code d'un inscrit
      //   — `codeDeLAthlete` — est parti avec le bouton qu'il servait : ici
      //   personne n'a plus besoin de son code, il est deja entre. Le code se
      //   copie dans « En attente », juste en dessous, ou il a encore un sens.
      const cmd=[...d.querySelectorAll('button')].map(b=>b.getAttribute('onclick')||'');
      if(cmd.length!==1) return _echec('il faut UN bouton, il y en a '+cmd.length+' : '+cmd.join(' | '));
      if(cmd[0].indexOf('jdRelancer')!==0)
        return _echec('le bouton ne relance pas : '+cmd[0]);
      // IL EST ROUGE, demande explicitement.
      const b=d.querySelector('button');
      if(!/btn-red/.test(b.className)) return _echec('« Relancer » n’est pas rouge : '+b.className);
      if(/btn-blanc|btn-outline/.test(b.className))
        return _echec('« Relancer » porte encore une autre peinture : '+b.className);
      // LA DATE DE CREATION DU COMPTE, demandee explicitement — et c'est bien
      // celle du COMPTE : ces gens se sont inscrits.
      if(d.innerText.indexOf('Compte créé')<0)
        return _echec('la date de creation du compte manque : '+d.innerText);
      // ET AUCUN CHEMIN VERS LE CANAL DE DIFFUSION.
      if(/openMessageCanal|relancerJamaisDemarre/.test(h))
        return _echec('la carte mene encore au canal');
      // ⚠ NI VERS LE TUNNEL COMMERCIAL, ET C'EST LA MEME RIGUEUR. Le tunnel ne
      //   compte que les gens qui n'ont JAMAIS utilise leur acces ; ceux-ci ont
      //   ouvert un compte. Y brancher le bouton aurait ecrit des relances dans
      //   un dossier que `tunnelListe` ne rend jamais, et la quatrieme aurait
      //   desactive le code d'un athlete deja inscrit.
      if(/tunnelRelancer|tunnelOuvrir/.test(h))
        return _echec('la carte mene au tunnel, qui ne connait pas ces gens');
      // ⚠ L'IDENTIFIANT DE L'ATHLETE VOYAGE, PAS SON RANG. Un rang dans la
      //   liste bouge des qu'une personne s'entraine enfin : le bouton d'une
      //   carte rendue il y a dix secondes aurait relance quelqu'un d'autre.
      return /jdRelancer\('[^']+'\)/.test(h)
        ?true:_echec('le bouton ne porte pas d’identifiant d’athlete');})());

    // XSS STOCKE : le prenom est saisi par l'athlete et atterrit dans le
    // tableau de bord de son coach. Le defaut avait deja ete trouve dans
    // renderTodoBlock ; on ne le reintroduit pas par une troisieme liste.
    ok('Un prenom hostile ne s’execute pas dans la carte',(()=>{
      const h=_htmlJamaisDemarre([{id:'h',fname:'<img src=x onerror=alert(1)>',
        createdAt:Date.now()-5*864e5,sessions:[]}],Date.now());
      return /<img/.test(h)?_echec('la balise est passee telle quelle'):true;})());

    ok('Le brouillon est un texte, modifiable, jamais un envoi',(()=>{
      const b=brouillonJamaisDemarre({fname:'Léa'});
      if(b.indexOf('Léa')<0) return _echec('le prenom n’est pas dans le brouillon');
      if(b.indexOf('première séance')<0) return _echec('le brouillon a change de sujet');
      // Sans prenom, la phrase reste lisible plutot que de laisser un trou.
      if(brouillonJamaisDemarre({}).indexOf('Salut toi')<0)
        return _echec('sans prenom, le brouillon laisse un trou');
      // ⚠ ELLE NE PASSE PLUS PAR LE CANAL. `relancerJamaisDemarre` n'existe
      //   plus : le brouillon alimente deux LIENS — WhatsApp et mailto — et
      //   c'est le client de messagerie qui s'ouvre, pre-rempli et modifiable.
      if(typeof relancerJamaisDemarre!=='undefined')
        return _echec('le chemin par le canal existe encore');
      const k=canauxRelanceJamaisDemarre({fname:'Léa',email:'lea@t.fr',phone:'+33600000000'});
      if(k.texte!==b) return _echec('les deux canaux ne portent pas le brouillon');
      if(k.mail.indexOf(encodeURIComponent(b))<0)
        return _echec('le mail ne porte pas le texte');
      if(k.mail.indexOf('subject=')<0) return _echec('le mail n’a pas d’objet');
      // ⚠ AUCUN ENVOI, ET AUCUNE ECRITURE : ce sont des liens. Ni publication
      //   dans le canal, ni ecriture dans le dossier de l'athlete.
      const r=String(canauxRelanceJamaisDemarre)+String(_canauxRelance);
      if(/ecrireMessageCanal|enregistrerMessageCanal|openMessageCanal/.test(r))
        return _echec('la relance touche encore au canal');
      return /saveUser\(|DB\.set\('users'|CLOUD\.push\(/.test(r)
        ?_echec('la relance ecrit dans le dossier de l’athlete'):true;})());

    // LE CANAL EST UNE DIFFUSION, et les regles RTDB le disent : /canaux/
    // {coach}/messages est lisible par TOUT athlete rattache.
    //
    // ⚠ CE TEST EXIGEAIT UN AVERTISSEMENT, ET N'EN VEUT PLUS. Il verifiait que
    //   la fenetre du canal prevenait quand un brouillon NOMMAIT quelqu'un :
    //   « en l'envoyant tel quel, tu apprends a tout le groupe qu'Untel n'a pas
    //   encore commence ». Un seul chemin posait un tel brouillon — la relance
    //   « jamais demarre » — et depuis le 19/09/2026 elle part en WhatsApp ou
    //   en mail, a la demande de Kevin.
    //
    //   LA CAUSE A DISPARU, L'AVERTISSEMENT AVEC ELLE, et c'est mieux qu'un
    //   garde-fou conserve : un avertissement ne repare pas un chemin, il
    //   demande a l'utilisateur de rattraper le produit. Ce qui est tenu
    //   desormais, c'est que PLUS AUCUN brouillon nominatif n'entre ici.
    ok('Aucun brouillon nominatif n’entre dans le canal',(()=>{
      const s=String(openMessageCanal);
      if(/_br\b|brouillon/.test(s))
        return _echec('la fenetre accepte encore un brouillon');
      if(s.indexOf('lu par tous tes athl')>=0)
        return _echec('l’avertissement subsiste alors que sa cause a disparu');
      // ET RIEN NE PEUT LUI EN PASSER : la signature ne declare plus qu'UN
      // parametre — l'identifiant du message qu'on modifie — et la clef qui
      // portait le prenom n'existe plus nulle part dans le produit.
      // ⚠ ON NE COMPTE PAS LES ARGUMENTS DES APPELS : le bouton « modifier »
      //   passe legitimement `openMessageCanal('${escapeHtml(m.id)}')`, et une
      //   sonde qui lit les parentheses prendrait cet identifiant pour un
      //   brouillon. La signature et la clef disent la meme chose, sans faux
      //   positif.
      if(!/^function openMessageCanal\(msgId\)/.test(s))
        return _echec('la signature accepte encore un second argument');
      return _prodSrc().indexOf('nomme:')<0
        ?true:_echec('un appelant passe encore un prenom au canal');})());

    // ⚠ TROIS LISTES, TROIS NATURES, AUCUNE FUSION. L'ecran d'assiduite et le
    // predicat de bilans restent mot pour mot ce qu'ils etaient.
    ok('« A relancer » et la logique d’assiduite sont intacts',(()=>{
      const e=document.getElementById('s-coach-file');
      if(!e) return _echec('l’ecran d’assiduite a disparu');
      const h=e.querySelector('h1');
      if(!h||h.textContent.trim()!=='À relancer')
        return _echec('le titre de l’ecran a change : '+(h&&h.textContent));
      // Sa phrase pose sa nature ; la troisieme liste ne la reprend pas.
      if(e.innerText.indexOf('Assiduité seulement')<0)
        return _echec('l’ecran ne se declare plus « assiduite seulement »');
      // neverStarted compte les BILANS et continue de le faire : c'est un
      // predicat DIFFERENT de jamaisDemarre, et ils restent separes.
      const n=String(neverStarted).replace(/\s+/g,'');
      if(n.indexOf('c.bilans||[]).length')<0)
        return _echec('neverStarted ne compte plus les bilans');
      if(n.indexOf('sessions')>=0)
        return _echec('neverStarted s’est mis a compter les seances : les deux listes fusionnent');
      // Et la ligne « A traiter » qui s'en sert est toujours la.
      return /neverStarted\(c\)/.test(String(renderTodoBlock))
        ?true:_echec('« A traiter » a perdu sa ligne « n’a jamais commence »');})());
    ok('Les quatre compteurs de retention sont declares',(()=>{
      const n=['notif_granted','pwa_installed','retour_j1','jamais_demarre_7j'];
      const abs=n.filter(x=>RCM_EVENEMENTS.indexOf(x)<0);
      if(abs.length) return _echec('absent(s) de RCM_EVENEMENTS : '+abs.join(', '));
      // ⚠ LA LISTE BLANCHE DU SERVEUR EST L'AUTRE MOITIE, et elle n'est pas
      // verifiable d'ici : database.rules.json n'est pas deploye, une sonde
      // par fetch depuis la page rend `true` faute de pouvoir conclure — c'est
      // exactement comme ca que 'logo' est reste casse en etant vert. Cette
      // comparaison-la vit dans scripts/verif/regles.mjs, qui lit les DEUX
      // fichiers sur le disque et bloque le deploiement. Le 15/09/2026 elle a
      // trouve QUINZE compteurs refuses en silence depuis huit jours.
      return true;})());

    ok('Les quatre compteurs sont au tableau de bord, bien places',(()=>{
      const q=c=>RCM_TUNNEL.find(e=>e.cles.indexOf(c)>=0);
      const trois=['notif_granted','pwa_installed','retour_j1'];
      for(const c of trois){
        const e=q(c);
        if(!e) return _echec(c+' n’est pas dans RCM_TUNNEL');
        if(!e.lib||!/[a-zà-ÿ]/.test(e.lib)) return _echec(c+' n’a pas de libelle francais');
        // HORS CHAINE : ces trois-la se produisent a n'importe quel moment de
        // la vie d'un compte. Dans la chaine, elles feraient calculer un taux
        // entre deux volumes qui ne se suivent pas.
        if(!e.horsTunnel) return _echec(c+' casserait le taux de l’etape suivante');
      }
      const j=q('jamais_demarre_7j');
      if(!j) return _echec('jamais_demarre_7j n’est pas dans RCM_TUNNEL');
      if(!j.lib) return _echec('jamais_demarre_7j n’a pas de libelle');
      // CELUI-CI EST DANS LA CHAINE, comme demande. Le test le verrouille pour
      // que le choix reste un choix, et non un oubli.
      return !j.horsTunnel?true:_echec('jamais_demarre_7j a ete sorti de la chaine');})());

    // LA DECISION EST PURE, donc entierement eprouvable ici : ni horloge, ni
    // stockage, ni reseau. Une erreur de retention ne se verrait pas a
    // l'ecran — elle se verrait dans six mois, dans un chiffre faux dont
    // personne ne saurait qu'il l'est.
    ok('etapesRetention : la table de decision',(()=>{
      const J=864e5, auj='2026-09-15', t=Date.parse('2026-09-15T10:00:00Z');
      const f=(u,v)=>etapesRetention(u,v||{},auj,t).join(',');
      const cas=[
        ['compte de 2 h',            {email:'a',role:'athlete',createdAt:t-2*3600e3},{},''],
        ['30 h, jamais compte',      {email:'a',role:'athlete',createdAt:t-30*3600e3},{},'retour_j1'],
        ['30 h, deja compte ce jour',{email:'a',role:'athlete',createdAt:t-30*3600e3},{retour_j1:auj},''],
        ['30 h, compte hier',        {email:'a',role:'athlete',createdAt:t-30*3600e3},{retour_j1:'2026-09-14'},'retour_j1'],
        ['8 j, athlete, 0 seance',   {email:'a',role:'athlete',createdAt:t-8*J},{retour_j1:auj},'jamais_demarre_7j'],
        ['8 j, athlete, 1 seance',   {email:'a',role:'athlete',createdAt:t-8*J,sessions:[{}]},{retour_j1:auj},''],
        ['8 j, COACH, 0 seance',     {email:'c',role:'coach',  createdAt:t-8*J},{retour_j1:auj},''],
        ['6 j, athlete, 0 seance',   {email:'a',role:'athlete',createdAt:t-6*J},{retour_j1:auj},''],
        ['8 j, rien encore compte',  {email:'a',role:'athlete',createdAt:t-8*J},{},'retour_j1,jamais_demarre_7j'],
        // SANS DATE DE CREATION, ON NE SUPPOSE RIEN : compter les comptes
        // d'avant createdAt comme « plus de 24 h » ferait un pic de retour_j1
        // le jour de la mise en ligne, et ce pic se lirait comme un succes.
        ['sans createdAt',           {email:'a',role:'athlete'},{},''],
        ['sans email',               {role:'athlete',createdAt:t-8*J},{},''],
        ['dossier nul',              null,{},'']
      ];
      for(const [lib,u,v,att] of cas){
        const r=f(u,v);
        if(r!==att) return _echec(lib+' rend «'+r+'» au lieu de «'+att+'»');
      }
      return true;})());

    // ⚠ LA CONTRAINTE ABSOLUE : DES ENTIERS, ET RIEN D'AUTRE.
    // Le test lit la source de rcm() plutot que de l'appeler : la suite tourne
    // sur 127.0.0.1, et rcm() s'y tait par conception — la garde de
    // developpement. L'appeler ici ne prouverait donc rien du tout. L'envoi
    // reel a ete inspecte au navigateur le 15/09/2026, sur un hote non local :
    // PUT /metrics/AAAA-MM-JJ/<nom>.json, corps {".sv":{"increment":1}},
    // en-tetes {Content-Type}, aucun jeton, aucun e-mail, aucun cookie.
    ok('Les compteurs de retention n’emportent aucun identifiant',(()=>{
      const s=String(rcm);
      if(!/\{'\.sv':\{'increment':1\}\}|"\.sv"/.test(s.replace(/\s/g,'')))
        return _echec('le corps n’est plus un simple increment');
      if(/auth=|Authorization|idToken|getToken/i.test(s))
        return _echec('rcm joint desormais un jeton : chaque increment serait rattachable');
      // rcmRetention ne passe QUE des noms d'etape a rcm.
      const r=String(rcmRetention);
      if(/rcm\((?!e\)|'[a-z0-9_]+')/.test(r))
        return _echec('rcmRetention passe autre chose qu’un nom d’etape');
      // LA MEMOIRE DU JOUR RESTE SUR L'APPAREIL. Elle est lue et ecrite dans
      // localStorage, et n'apparait nulle part dans ce qui part sur le reseau.
      if(r.indexOf('localStorage')<0)
        return _echec('la cle datee ne passe plus par le stockage local');
      if(/fetch|XMLHttpRequest|sendBeacon/.test(r))
        return _echec('rcmRetention contacte le reseau directement, hors de rcm');
      // ET LE TEXTE DE BAS DE PAGE RESTE VRAI, mot pour mot.
      const p=document.querySelector('#s-metrics p.sub');
      if(!p) return _echec('le texte de bas de page a disparu de l’ecran');
      const txt=p.textContent.replace(/\s+/g,' ');
      for(const m of ['Aucun cookie','aucun identifiant','aucune donnée de santé',
                      'ni de relier deux étapes à une même personne'])
        if(txt.indexOf(m)<0) return _echec('le bas de page ne dit plus : '+m);
      return true;})());

    // LES QUATRE POINTS D'APPEL. N'en instrumenter qu'une partie donnerait un
    // chiffre faux sans que rien ne le signale — la regle que ce fichier pose
    // deja pour le guide iOS, qui s'ouvre par deux chemins.
    ok('Les quatre compteurs sont branches la ou ils se produisent',(()=>{
      const prod=_prodSrc();
      // ⚠ LE NOMBRE EST DERIVE, JAMAIS ECRIT EN DUR. Ce test disait « 2 sur 2 »,
      // et il est tombe le jour ou l'invitation de fin de premiere seance a
      // ajoute un TROISIEME point d'appel — alors que ce troisieme point est
      // exactement ce que la regle demande. La regle n'a jamais ete « il y en a
      // deux » : elle est « CHAQUE demande de permission compte son accord ».
      // On compte donc les demandes, et on exige autant de comptages.
      const dem=[...prod.matchAll(/Notification\.requestPermission\(\)/g)].map(m=>m.index);
      if(dem.length<2) return _echec(dem.length+' appel(s) a requestPermission : lecture cassee');
      const n=(prod.match(/rcm\('notif_granted'\)/g)||[]).length;
      if(n!==dem.length)
        return _echec(n+' comptage(s) pour '+dem.length+' demande(s) de permission');
      for(const i of dem){
        const suite=prod.slice(i,i+420);
        if(suite.indexOf('notif_granted')<0)
          return _echec('un requestPermission ne compte rien');
        if(suite.indexOf('granted')>suite.indexOf('notif_granted'))
          return _echec('un compteur est pose avant le verdict de permission');
      }
      // L'INSTALLATION : dans l'ecouteur de l'evenement du navigateur, a cote
      // de son jumeau install_fait.
      const iF=prod.indexOf("rcm('install_fait')"), iP=prod.indexOf("rcm('pwa_installed')");
      if(iP<0) return _echec('pwa_installed n’est branche nulle part');
      if(!(iF>=0&&Math.abs(iP-iF)<1200))
        return _echec('pwa_installed n’est pas dans l’ecouteur d’installation');
      // LA RETENTION : au demarrage, APRES la fusion session/carte — sans quoi
      // un athlete dont les seances etaient du cote manquant serait compte
      // « jamais demarre ».
      const iR=prod.indexOf('rcmRetention(currentUser)');
      if(iR<0) return _echec('rcmRetention n’est pas appelee au demarrage');
      const iFus=prod.indexOf('currentUser=users[currentUser.email]');
      if(!(iFus>=0&&iFus<iR)) return _echec('rcmRetention est appelee avant la fusion du dossier');
      return true;})());
    ok('Un seul fmtDureeSeance dans toute la source',(()=>{
      const n=(_prodSrc().match(/function fmtDureeSeance\(/g)||[]).length;
      return n===1?true:_echec(n+' declarations du meme nom');})());

    // hh:mm:ss TOUJOURS, heure comprise a zero. Demande de Kevin : trois
    // champs fixes, qui ne changent pas de sens en cours de seance.
    ok('Le chronometre de seance affiche hh:mm:ss',(()=>{
      const cas=[[0,'00:00:00'],[9,'00:00:09'],[62,'00:01:02'],
                 [1832,'00:30:32'],[3725,'01:02:05'],[86399,'23:59:59']];
      for(const [s,att] of cas){
        const v=fmtDureeSeance(s);
        if(v!==att) return _echec(s+' s rend '+JSON.stringify(v)+' au lieu de '+att);
      }
      // LARGEUR STABLE : huit caracteres, quelle que soit la duree. C'est ce
      // qui empeche le titre voisin de sauter a la premiere heure franchie.
      if(new Set(cas.map(c=>fmtDureeSeance(c[0]).length)).size!==1)
        return _echec('la largeur du chronometre varie');
      // ET LE GABARIT PART DE LA MEME FORME, sinon la premiere seconde
      // ecourterait la ligne.
      const el=document.getElementById('wo-timer');
      if(!el) return _echec('le chronometre a disparu de l’ecran de seance');
      return el.textContent.trim()==='00:00:00'
        ?true:_echec('le gabarit part a '+JSON.stringify(el.textContent));})());

    // ET LA LECTURE EN HEURES SURVIT SOUS SON PROPRE NOM : c'est elle que le
    // recapitulatif de fin de seance appelle, et « 205 min » ne se lit pas.
    ok('fmtDureeHeures garde la lecture du recapitulatif',(()=>{
      if(typeof fmtDureeHeures!=='function') return _echec('la fonction n’existe plus');
      const cas=[[45,'45 min'],[120,'2 h'],[205,'3 h 25'],[0,'0 min']];
      for(const [m,att] of cas){
        const v=fmtDureeHeures(m);
        if(v!==att) return _echec(m+' min rend '+JSON.stringify(v)+' au lieu de '+att);
      }
      return /zone\(escapeHtml\(fmtDureeHeures\(mins\)\)/.test(_prodSrc())
        ?true:_echec('le recapitulatif n’appelle plus la lecture en heures');})());

    // ⚠ LE DOSSIER exercices/vignettes/ N'A JAMAIS EXISTE. Le code le visait
    // depuis le 07/09/2026 : chaque ligne de liste demandait un fichier
    // absent, prenait un 404, puis se rabattait sur la fiche par `onerror`.
    // Rien ne doit plus emettre cette URL tant que le dossier n'est pas la.
    ok('Aucune URL ne vise le dossier de vignettes absent',(()=>{
      const prod=_prodSrc();
      // Le commentaire qui RACONTE le retrait a le droit de nommer le dossier ;
      // une URL construite, non. On vise donc la concatenation, pas le mot.
      if(/['"`]vignettes\//.test(prod)) return _echec('une URL de vignette est encore construite');
      if(/EXO_VIGNETTE_DOSSIER\s*\+/.test(prod)) return _echec('la constante sert encore a batir une URL');
      // ET LA LIGNE DE LISTE SERT L'IMAGE QUI EXISTE.
      const h=_bqLigne({slug:'x',nom:'DEVELOPPE COUCHE BARRE',muscles:[],materiel:''});
      const src=(h.match(/src="([^"]+)"/)||[])[1]||'';
      if(!/^exercices\/[a-z0-9-]+\.webp$/.test(src))
        return _echec('la ligne de liste sert : '+JSON.stringify(src));
      // PLUS DE srcset : il departageait deux fichiers, il n'y en a qu'un.
      return /srcset=/.test(h)?_echec('le srcset annonce encore deux tailles'):true;})());

    // ⚠ UN SEUL ECHEC RESEAU ETEIGNAIT TOUTES LES ILLUSTRATIONS, DEFINITIVEMENT.
    // `catch` posait _exoIndex a une Map VIDE, et la premiere ligne de la
    // fonction rend _exoIndex des qu'il est truthy — une Map vide en est une.
    // Un creux de reseau au demarrage et l'athlete n'avait plus aucune image
    // nulle part jusqu'au rechargement, sans que rien ne retente.
    // ⚠ CE TEST LIT LA SOURCE, ET C'EST DELIBERE. La verification honnete —
    // couper window.fetch, appeler, verifier, rebrancher — demande deux await,
    // et `ok` ne fait que !!c : une promesse est truthy, un tel test PASSERAIT
    // toujours, y compris sur le code fautif. Mieux vaut une assertion de forme
    // qui mord qu'une assertion de comportement qui ment. Le comportement, lui,
    // a ete verifie au navigateur le 15/09/2026 : coupure, Map vide, _exoIndex
    // toujours null, puis 436 entrees au retour du reseau.
    ok('Un echec de l’index des illustrations ne se memorise pas',(()=>{
      const s=String(chargerIndexIllustrations);
      const i=s.indexOf('catch');
      if(i<0) return _echec('la fonction ne rattrape plus rien');
      const bloc=s.slice(i);
      // LE DEFAUT EXACT : `catch(e){ _exoIndex=new Map(); }`. La premiere ligne
      // rend _exoIndex des qu'il est truthy, et une Map vide en est une :
      // l'echec devenait DEFINITIF pour toute la duree de la page.
      if(/_exoIndex\s*=\s*new Map\(\)/.test(bloc))
        return _echec('le catch memorise encore l’echec dans _exoIndex');
      if(!/return new Map\(\)/.test(bloc))
        return _echec('le catch ne rend plus de Map vide a l’appelant');
      // ET LA GARDE D'ENTREE RESTE CELLE QUI REND LE RETRY POSSIBLE.
      return /if\(_exoIndex\) return _exoIndex/.test(s)
        ?true:_echec('la garde d’entree a change : le retry n’est plus garanti');})());

    // ET TANT QUE L'INDEX MANQUE, ON NE REND PAS D'URL CASSEE : null, jamais
    // une adresse qui produirait un cadre vide.
    ok('Sans index, aucune illustration n’est inventee',(()=>{
      const sv=_exoIndex;
      try{
        _exoIndex=null;
        if(illustrationDe('ESCALIERS')!==null) return _echec('une URL sort sans index');
        if(_slugIllustre('escaliers')!==null) return _echec('un slug sort sans index');
        return true;
      } finally { _exoIndex=sv; }})());
    // ══ 15/09/2026 — LE CAS NUL DU COMPTEUR DE SERIE ═══════════════════════
    // Un compteur de serie a zero ne motive pas : il n'y a rien a perdre, donc
    // aucune tension. On montre la semaine EN COURS et ce qui la validerait.

    // ⚠ AUCUNE REGLE DE CALCUL NE CHANGE, et ce test l'exige plutot que de
    // l'esperer : streakSemaines, _streakPerime et ecartNormalJours decident
    // comme avant, affichageStreak recoit leur verdict et choisit des mots.
    ok('L’affichage du cas nul ne calcule aucune série',(()=>{
      const a=String(affichageStreak);
      for(const f of ['streakSemaines','_streakPerime','ecartNormalJours',
                      'lastSession','suspensionEtat','Date.now'])
        if(a.indexOf(f)>=0) return _echec('affichageStreak touche a '+f);
      // Et les trois fonctions de calcul ignorent tout de l'affichage.
      for(const [n,f] of [['streakSemaines',streakSemaines],['_streakPerime',_streakPerime],
                          ['ecartNormalJours',ecartNormalJours]]){
        const s=String(f);
        for(const m of ['affichageStreak','SEMAINE 1','sk-reste','_rendreStreak'])
          if(s.indexOf(m)>=0) return _echec(n+' connait desormais '+m);
      }
      // ecartNormalJours reste EXACTEMENT sa formule : 7 / seances + 1.
      return /Math\.ceil\(7\/seancesPrevuesParSemaine\(u\)\)\+1/.test(String(ecartNormalJours))
        ?true:_echec('ecartNormalJours a change de formule');})());

    ok('Le cas nul montre la semaine en cours, jamais une semaine acquise',(()=>{
      const cas=[
        // streak, prevues, faites  →  valeur, libelle, reste
        [0,3,0,null,'SEMAINE 1','Encore 3 séances'],
        [0,3,1,null,'SEMAINE 1','Encore 2 séances'],
        [0,3,2,null,'SEMAINE 1','Encore 1 séance'],
        // ⚠ DEJA TROIS SEANCES MAIS LA SEMAINE N'EST PAS CLOSE : on ne dit pas
        // « 0 seance », qui serait faux et incomprehensible.
        [0,3,3,null,'SEMAINE 1','Encore 1 séance'],
        [0,3,9,null,'SEMAINE 1','Encore 1 séance'],
        [0,1,0,null,'SEMAINE 1','Encore 1 séance'],
        [0,5,0,null,'SEMAINE 1','Encore 5 séances'],
        // DES LA PREMIERE SEMAINE ACQUISE, l'affichage redevient ce qu'il etait.
        [1,3,0,1,'SEMAINES',''],
        [7,3,2,7,'SEMAINES',''],
        [52,3,0,52,'SEMAINES','']
      ];
      for(const [s,p,f,v,l,r] of cas){
        const a=affichageStreak(s,p,f);
        if(a.valeur!==v||a.libelle!==l||a.reste!==r)
          return _echec('streak='+s+' → '+JSON.stringify(a));
      }
      // ⚠ LE COMPTEUR N'ANNONCE JAMAIS UNE SEMAINE QU'IL N'A PAS ACQUISE.
      // `valeur` est null dans le cas nul : le grand chiffre QUITTE la mise en
      // page, il n'est pas remplace par un « 1 » qui se lirait comme un acquis.
      if(affichageStreak(0,3,0).valeur!==null)
        return _echec('le cas nul pose un nombre de semaines');
      return true;})());

    ok('Le cadre bascule d’un état à l’autre, et efface sa mémoire',(()=>{
      const sv=currentUser;
      try{
        const cfg=[{active:true},{active:true},{active:true},
                   {active:false},{active:false},{active:false},{active:false}];
        const el=document.getElementById('clh-streak-val');
        const zone=document.querySelector('#clh-streak .sk-chiffres');
        const lbl=document.querySelector('#clh-streak .sk-lbl');
        const res=document.getElementById('clh-streak-reste');
        if(!el||!zone||!lbl||!res) return _echec('le cadre a change de structure');
        currentUser={id:'x',email:'x@t.fr',role:'athlete',streak:0,sessions:[],sessions_config:cfg};
        _rendreStreak(currentUser,0);
        if(!zone.hasAttribute('data-nul')) return _echec('l’etat nul n’est pas marque');
        if(lbl.textContent!=='SEMAINE 1') return _echec('libelle : '+lbl.textContent);
        if(res.textContent!=='Encore 3 séances') return _echec('reste : '+res.textContent);
        // ⚠ LA MEMOIRE DU COMPTEUR EST EFFACEE. Sans cela, la semaine suivante
        // animerait « 1 » depuis une valeur perimee — un compteur qui compte a
        // rebours depuis un nombre que personne n'a jamais vu.
        if(el.dataset.valeur!==undefined)
          return _echec('data-valeur survit a l’etat nul : '+el.dataset.valeur);
        if(el.textContent!=='') return _echec('le grand chiffre garde un texte : '+el.textContent);
        currentUser.streak=1; currentUser.lastSession=Date.now();
        _rendreStreak(currentUser,1);
        if(zone.hasAttribute('data-nul')) return _echec('l’etat nul survit a la premiere semaine');
        if(lbl.textContent!=='SEMAINES') return _echec('le libelle ne revient pas : '+lbl.textContent);
        if(res.textContent!=='') return _echec('la ligne du dessous survit : '+res.textContent);
        return el.dataset.valeur==='1'?true:_echec('le compteur ne repart pas de 1');
      } finally {
        currentUser=sv;
        try{
          const el=document.getElementById('clh-streak-val');
          el.textContent='0'; delete el.dataset.valeur;
          document.querySelector('#clh-streak .sk-chiffres').removeAttribute('data-nul');
          document.querySelector('#clh-streak .sk-lbl').textContent='SEMAINES';
          document.getElementById('clh-streak-reste').textContent='';
        }catch(e){}
      }})());

    // ⚠ LA LIGNE DU DESSOUS RESPECTE LE PLANCHER DE 11 px. Elle a d'abord ete
    // ecrite a 9,5 px, et « aucun texte de l'accueil athlete ne descend sous le
    // plancher » l'a refusee — comme elle avait refuse la ligne de la pesee.
    // C'est la PHRASE qui a ete raccourcie, pas le corps.
    ok('La ligne du cas nul tient le plancher de l’accueil',(()=>{
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.sk-reste\{([^}]*)\}/);
      if(!m) return _echec('la regle .sk-reste n’existe pas');
      const px=(m[1].match(/font-size:(\d+(?:\.\d+)?)px/)||[])[1];
      if(!px) return _echec('le corps n’est pas ecrit en pixels : '+m[1].slice(0,60));
      if(parseFloat(px)<11) return _echec('la ligne descend a '+px+' px');
      // ELLE S'ENVELOPPE : une phrase qui refuse de se couper pousserait
      // l'avatar ou le prenom hors de l'ecran sur un telephone etroit.
      if(!/max-width:/.test(m[1])) return _echec('rien ne borne sa largeur');
      // ET ELLE NE PARAIT QUE DANS L'ETAT NUL.
      return /\.sk-chiffres:not\(\[data-nul\]\) \.sk-reste\{display:none\}/.test(css)
        ?true:_echec('la ligne du dessous survivrait a l’etat normal');})());
    ok('Le compteur de semaines ne porte plus de tiret',(()=>{
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      if(document.querySelector('.sk-tiret')) return _echec('le tiret est encore dans le document');
      if(/\.sk-tiret\s*\{/.test(css)) return _echec('la regle .sk-tiret est encore ecrite');
      const v=document.getElementById('clh-streak-val');
      if(!v) return _echec('le compteur a disparu');
      const l=document.querySelector('.sk-lbl');
      if(!l) return _echec('le libelle a disparu');
      // SUR LA MEME LIGNE, ET SEPARES PAR UN ESPACE : c'est la demande exacte.
      // ⚠ LA MESURE NE VAUT QUE SI L'ECRAN EST MONTE. Quand l'accueil athlete
      // n'est pas l'ecran actif, les deux rectangles sont nuls et leur ecart
      // vaut 0 — ce test tombait sur une page parfaitement correcte. On lit
      // donc la REGLE, toujours vraie, et on ne mesure que si la mise en page
      // a reellement eu lieu.
      const m=css.match(/\.sk-chiffres\{([^}]*)\}/);
      if(!m) return _echec('la regle .sk-chiffres n\'existe plus');
      if(!/column-gap:[1-9]/.test(m[1]))
        return _echec('aucun espace entre le compte et son libelle : '+m[1].slice(0,70));
      if(!/\.sk-lbl\{grid-column:2;grid-row:1\}/.test(css))
        return _echec('le libelle n\'est plus sur le rang du compte');
      const rv=v.getBoundingClientRect(), rl=l.getBoundingClientRect();
      if(!rv.width||!rl.width) return true;   // ecran non monte : la regle suffit
      if(!(Math.abs(rv.bottom-rl.bottom)<3))
        return _echec('le compte et son libelle ne partagent pas la ligne de base');
      const ecart=rl.left-rv.right;
      return ecart>2&&ecart<14?true:_echec('espace entre les deux : '+Math.round(ecart)+' px');})());

    // ══ 15/09/2026 — LES CINQ BADGES ══════════════════════════════════════
    // « Cinq badges, pas un de plus. RepCore se vend sur le serieux : une
    // collection sans fin transformerait un signal de reconnaissance en bruit. »
    // Ce n'est pas une contrainte technique, donc rien dans le code ne la tient
    // tout seul : il faut une assertion, et la voici. Le SERVEUR la tient aussi
    // — le motif de cle de /users/$emailKey/badges n'accepte que ces cinq
    // identifiants — et scripts/verif/regles.mjs compare les deux listes.
    ok('Cinq badges, pas un de plus',(()=>{
      if(!Array.isArray(BADGES_ACQUIS)) return _echec('BADGES_ACQUIS n’est pas une liste');
      if(BADGES_ACQUIS.length!==5) return _echec(BADGES_ACQUIS.length+' badges au lieu de cinq');
      const ids=BADGES_ACQUIS.map(b=>b.id);
      if(new Set(ids).size!==5) return _echec('deux badges portent le meme identifiant');
      // Chacun dit ce qu'il RECOMPENSE et ce qu'il FAUT FAIRE : la vitrine du
      // profil montre les cinq, obtenus et a obtenir, et sans `attendu` la
      // moitie de la carte serait vide.
      for(const b of BADGES_ACQUIS){
        for(const c of ['id','lib','phrase','attendu'])
          if(!b[c]||typeof b[c]!=='string') return _echec(b.id+' n’a pas de '+c);
        if(!badgeAcquisFichier(b.id)) return _echec(b.id+' n’a pas d’image');
      }
      return true;})());

    // ⚠ AUCUNE IMAGE NOUVELLE. Les quinze medaillons sont decoupes dans
    // app/img/badges/ depuis le 14/09 ; en redecouper cinq pour cette carte
    // aurait mis deux versions du meme hexagone dans le depot. Les cinq
    // permanents EMPRUNTENT donc cinq des quinze, par leur clef de fin de
    // seance — et cette assertion verifie que ces clefs existent vraiment.
    ok('Les badges permanents empruntent les medaillons existants',(()=>{
      for(const b of BADGES_ACQUIS){
        const k=BADGE_ACQUIS_IMG[b.id];
        if(!k) return _echec(b.id+' ne designe aucun medaillon');
        if(!BADGES[k]) return _echec(b.id+' designe '+k+', qui n’est pas un badge de seance');
        const f=badgeAcquisFichier(b.id);
        if(f!==_badgeFichier(k)) return _echec(b.id+' ne passe pas par _badgeFichier : '+f);
        if(!/^img\/badges\//.test(f)) return _echec(b.id+' sort du dossier commun : '+f);
      }
      return true;})());

    // LES CINQ CRITERES, UN PAR UN. « Les badges se calculent a partir des
    // donnees deja enregistrees, sans nouvelle colle » : badgesMerites ne lit
    // que sessions, bilans, sessions_config et streak, par des fonctions qui
    // existaient avant ce lot.
    ok('Les cinq critères se lisent dans le dossier, et nulle part ailleurs',(()=>{
      const J=864e5, now=Date.now();
      // ⚠ LE LUNDI DE LA SEMAINE PRECEDENTE, ET NON DE CELLE-CI. Le decor
      //   posait ses seances a `lundi`, `lundi+1` et `lundi+2` : UN LUNDI, les
      //   deux dernieres tombaient donc DEMAIN et APRES-DEMAIN. Consequence
      //   mesuree le 21/09/2026 : _riteRecords cherche les records entre la
      //   DEUXIEME seance et maintenant — un intervalle inverse quand la
      //   deuxieme est dans l'avenir — et n'en trouvait aucun. Le cas 4
      //   (100 kg puis 110 kg) perdait « premier-record », et la contre-epreuve
      //   finale ne comptait que quatre badges sur cinq.
      //
      //   LE PRODUIT AVAIT RAISON : un record etabli demain n'en est pas un
      //   aujourd'hui. C'est le decor qui datait mal. En reculant d'une
      //   semaine, les sept jours du gabarit sont tous passes et chaque cas
      //   garde exactement le sens qu'il avait.
      const lundi=_lundiDe(now-7*J).getTime();
      const cfg3=[{active:true},{active:true},{active:true},{active:false}];
      const seance=(d,nom,poids,reps)=>({date:d,exercises:[{name:nom,
        sets:[{weight:poids,reps:reps,repsDone:reps,rir:0,done:true}]}]});
      const cas=[
        // Dossier vierge : rien.
        [{sessions:[],bilans:[],sessions_config:cfg3},[]],
        // UNE seance : la premiere, et elle seule. Pas de record — il n'y a
        // rien a battre — et le quota de trois n'est pas atteint.
        [{sessions:[seance(lundi+J,'DEV',100,5)],bilans:[],sessions_config:cfg3},
         ['premiere-seance']],
        // Trois seances dans LA MEME semaine calendaire : le quota est fait.
        [{sessions:[seance(lundi,'DEV',100,5),seance(lundi+J,'DEV',90,5),
                    seance(lundi+2*J,'DEV',90,5)],bilans:[],sessions_config:cfg3},
         ['premiere-seance','semaine-validee']],
        // Trois seances a cheval sur DEUX semaines : aucune n'est validee.
        [{sessions:[seance(lundi-8*J,'DEV',100,5),seance(lundi-7*J,'DEV',90,5),
                    seance(lundi+J,'DEV',90,5)],bilans:[],sessions_config:cfg3},
         ['premiere-seance']],
        // Une charge qui monte apres la premiere seance : c'est un record.
        [{sessions:[seance(lundi-8*J,'DEV',100,5),seance(lundi+J,'DEV',110,5)],
          bilans:[],sessions_config:cfg3},
         ['premiere-seance','premier-record']],
        // La meme charge qui DESCEND : ce n'en est pas un.
        [{sessions:[seance(lundi-8*J,'DEV',100,5),seance(lundi+J,'DEV',90,5)],
          bilans:[],sessions_config:cfg3},
         ['premiere-seance']],
        // Un bilan, quel que soit son type.
        [{sessions:[],bilans:[{date:now,type:'depart'}],sessions_config:cfg3},
         ['premier-bilan']],
        // Quatre semaines de serie, lues par streakSemaines et par personne
        // d'autre : aucune semaine n'est recomptee de ce cote.
        [{sessions:[],bilans:[],sessions_config:cfg3,streak:4,lastSession:now},
         ['quatre-semaines']],
        [{sessions:[],bilans:[],sessions_config:cfg3,streak:3,lastSession:now},
         []]
      ];
      for(let i=0;i<cas.length;i++){
        const [u,attendu]=cas[i];
        const r=badgesMerites(Object.assign({role:'athlete'},u),now);
        if(r.join(',')!==attendu.join(','))
          return _echec('cas '+i+' → ['+r.join(',')+'] au lieu de ['+attendu.join(',')+']');
      }
      // ET L'ORDRE EST CELUI DE BADGES_ACQUIS, toujours : majBadges ne fete que
      // le premier de la liste, et un ordre qui flotterait ferait varier la
      // banniere d'un appareil a l'autre pour le meme evenement.
      const tous=badgesMerites({role:'athlete',sessions:[seance(lundi,'DEV',100,5),
        seance(lundi+J,'DEV',110,5),seance(lundi+2*J,'DEV',120,5)],
        bilans:[{date:now}],sessions_config:cfg3,streak:4,lastSession:now},now);
      const rang=tous.map(id=>BADGES_ACQUIS.findIndex(b=>b.id===id));
      for(let i=1;i<rang.length;i++)
        if(rang[i]<=rang[i-1]) return _echec('l’ordre flotte : '+tous.join(','));
      return tous.length===5?true:_echec('les cinq ne tombent pas ensemble : '+tous.join(','));})());

    // ⚠ LE GARDE EST EN PREMIERE LIGNE, ET IL BLOQUE L'ECRITURE AUTANT QUE LA
    // BANNIERE. « Aucun badge ne doit se declencher pendant une suspension ou
    // un drapeau rouge » — un badge inscrit en silence pour etre fete plus tard
    // serait la meme chose avec un delai. Le critere, lui, ne s'efface pas : il
    // se lit dans les donnees et retombera a la levee.
    ok('Sous drapeau ou suspension, aucun badge ne tombe',(()=>{
      const sv=currentUser;
      try{
        const base=()=>({id:'b1',email:'b@t.fr',role:'athlete',
          sessions:[{date:Date.now()-3600e3,exercises:[]}],bilans:[],
          sessions_config:[{active:true}]});
        // Temoin : sans drapeau, le badge tombe. Sans ce temoin, les deux cas
        // suivants passeraient meme si majBadges ne faisait plus rien du tout.
        currentUser=base();
        if(!majBadges().length) return _echec('le temoin sans drapeau ne gagne rien');
        if(!currentUser.badges||!currentUser.badges['premiere-seance'])
          return _echec('le temoin ne l’inscrit pas au dossier');
        if(!(currentUser.badges['premiere-seance'].at>0))
          return _echec('le badge est inscrit sans date');
        // DRAPEAU ROUGE ARTICULAIRE.
        currentUser=base(); currentUser.drapeauRouge={zone:'epaule',cases:['nuit'],date:Date.now()};
        if(majBadges().length) return _echec('un badge tombe sous drapeau rouge');
        if(currentUser.badges) return _echec('un badge est inscrit en silence sous drapeau');
        // DRAPEAU GENERAL.
        currentUser=base(); currentUser.drapeauGeneral={cases:['thorax'],date:Date.now()};
        if(majBadges().length) return _echec('un badge tombe sous drapeau general');
        if(currentUser.badges) return _echec('un badge est inscrit en silence sous drapeau general');
        // ET LE GARDE PASSE BIEN PAR suspensionEtat, comme la consigne l'exige.
        const src=String(majBadges);
        if(src.indexOf('suspensionEtat')<0) return _echec('majBadges ne consulte plus suspensionEtat');
        if(src.indexOf('drapeauQuelconqueActif')<0) return _echec('majBadges ne consulte plus les drapeaux');
        // A LA LEVEE, le badge retombe — avec la date du jour, qui est la
        // verite de ce qui s'est passe.
        delete currentUser.drapeauGeneral;
        return majBadges().length?true:_echec('rien ne retombe apres la levee');
      } finally { currentUser=sv; }})());

    // Un badge deja inscrit ne retombe jamais : sans quoi la banniere
    // reapparaitrait a chaque fin de seance, et « Premiere seance » serait
    // fetee toutes les semaines.
    ok('Un badge acquis ne se regagne pas',(()=>{
      const sv=currentUser;
      try{
        // TROIS CRENEAUX, ET NON UN. Avec un seul creneau le quota vaut 1,
        // et l'unique seance validait aussi la semaine : l'assertion sur un
        // badge unique tombait sur un code parfaitement correct.
        currentUser={id:'b2',email:'b2@t.fr',role:'athlete',
          sessions:[{date:Date.now()-3600e3,exercises:[]}],bilans:[],
          sessions_config:[{active:true},{active:true},{active:true}]};
        const un=majBadges();
        const quand=currentUser.badges['premiere-seance'].at;
        const deux=majBadges();
        if(deux.length) return _echec('le meme badge retombe : '+deux.join(','));
        if(currentUser.badges['premiere-seance'].at!==quand)
          return _echec('la date d’obtention a ete reecrite');
        // UN DOSSIER DE COACH N'EN GAGNE AUCUN : ces cinq recompenses parlent
        // d'un entrainement, et le coach n'en fait pas dans ce dossier.
        currentUser={id:'c1',email:'c@t.fr',role:'coach',
          sessions:[{date:Date.now(),exercises:[]}],bilans:[{date:Date.now()}],
          sessions_config:[{active:true}]};
        if(majBadges().length) return _echec('un dossier coach gagne des badges');
        return un.length===1?true:_echec('le premier passage a rendu '+un.join(','));
      } finally { currentUser=sv; }})());

    // « A l'obtention, afficher une celebration breve et sobre : une animation
    // courte, le badge, une phrase. PAS DE MODALE BLOQUANTE. » — la banniere
    // ne prend pas le focus, ne couvre aucun bouton, et il n'y a rien a fermer.
    ok('La célébration ne bloque rien',(()=>{
      const z=document.getElementById('bdg-fete');
      if(!z) return _echec('le noeud de celebration n’existe pas');
      // Hors de tout .screen : elle doit survivre au changement d'ecran, comme
      // le toast — majBadges est appelee AVANT go('s-workout-done').
      if(z.closest('.screen')) return _echec('la banniere vit dans un ecran');
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.bdg-fete\{([^}]*)\}/);
      if(!m) return _echec('la regle .bdg-fete n’existe pas');
      if(!/pointer-events:none/.test(m[1]))
        return _echec('la banniere intercepte les clics : '+m[1].slice(0,80));
      if(!/position:fixed/.test(m[1])) return _echec('la banniere n’est pas posee');
      // AUCUN DES GESTES D'UNE MODALE : pas de voile, pas de prise de focus,
      // pas de changement d'ecran, pas de blocage du defilement.
      const src=String(_celebrerBadge);
      for(const g of ['focus(','showModal','go(','overflow','confirm(','alert('])
        if(src.indexOf(g)>=0) return _echec('_celebrerBadge appelle '+g);
      // ELLE S'EN VA SEULE. Un setTimeout qui retire data-vu, et rien qui
      // attende un geste.
      if(!/setTimeout/.test(src)||!/removeAttribute\('data-vu'\)/.test(src))
        return _echec('la banniere ne se retire pas d’elle-meme');
      return true;})());

    // UNE SEULE BANNIERE, meme quand plusieurs badges tombent ensemble — cas
    // reel : la premiere seance d'un programme a une seance par semaine vaut
    // aussi la semaine validee. Trois bannieres a la file seraient la
    // collection sans fin qu'on refuse, en accelere.
    ok('Plusieurs badges d’un coup ne font qu’une seule bannière',(()=>{
      const sv=currentUser, svC=_celebrerBadge;
      const vues=[];
      try{
        _celebrerBadge=(id)=>{ vues.push(id); };
        currentUser={id:'b3',email:'b3@t.fr',role:'athlete',
          sessions:[{date:Date.now()-3600e3,exercises:[]}],
          bilans:[{date:Date.now()}],sessions_config:[{active:true}]};
        const n=majBadges();
        if(n.length<2) return _echec('le cas a plusieurs badges ne se produit pas : '+n.join(','));
        if(vues.length!==1) return _echec(vues.length+' bannieres pour '+n.length+' badges');
        if(vues[0]!==n[0]) return _echec('la banniere ne montre pas le premier : '+vues[0]);
        // LES AUTRES SONT INSCRITS QUAND MEME, et attendent dans le profil.
        for(const id of n) if(!currentUser.badges[id])
          return _echec(id+' n’est pas inscrit au dossier');
        return true;
      } finally { currentUser=sv; _celebrerBadge=svC; }})());

    // LA VITRINE DU PROFIL : les cinq, toujours les cinq. Montrer seulement les
    // acquis repondrait a « qu'ai-je gagne » et jamais a « que reste-t-il »,
    // qui est la question qu'on se pose en ouvrant cette carte.
    ok('« Mes badges » montre les obtenus ET ceux qui restent',(()=>{
      const h=htmlMesBadges({badges:{'premiere-seance':{at:Date.parse('2026-09-01T10:00:00')}}});
      // ⚠ ON COMPTE LES BALISES, PAS LES ATTRIBUTS. `class="bdg-case"` est un
      // PREFIXE de `class="bdg-case" data-attente` : les deux motifs se
      // recouvraient et les quatre cases en attente etaient comptees deux fois.
      const cases=(h.match(/<div class="bdg-case"/g)||[]).length;
      if(cases!==5) return _echec(cases+' cases au lieu de cinq');
      if((h.match(/data-attente/g)||[]).length!==4)
        return _echec('les quatre badges restants ne sont pas marques en attente');
      if(h.indexOf('01/09/26')<0) return _echec('la date d’obtention n’est pas montree');
      if(h.indexOf('1/5')<0) return _echec('le decompte n’est pas montre');
      // Ce qu'il faut faire pour ceux qui restent.
      for(const b of BADGES_ACQUIS.slice(1))
        if(h.indexOf(escapeHtml(b.attendu))<0) return _echec('« '+b.attendu+' » manque');
      // Un dossier vierge ne casse pas la carte.
      const v=htmlMesBadges({});
      if((v.match(/data-attente/g)||[]).length!==5) return _echec('le dossier vierge n’affiche pas les cinq');
      return v.indexOf('0/5')>=0?true:_echec('le dossier vierge ne dit pas 0/5');})());

    // « Sans nouvelle colle » : deux points d'appel, pas un de plus, et tous
    // deux au moment ou la donnee vient d'etre ecrite.
    ok('Les badges n’ont que deux points d’appel',(()=>{
      const s=_prodSrc().replace(/\/\/[^\r\n]*/g,'');
      const n=(s.match(/majBadges\(\)/g)||[]).length;
      // Trois occurrences : la definition, l'appel de fin de seance, l'appel
      // de fin de bilan. Une quatrieme signalerait un rendu qui attribue des
      // badges — un accueil, un onglet — et donc une banniere qui surgit sans
      // que rien ne vienne de se passer.
      if(n!==3) return _echec(n+' occurrences de majBadges() au lieu de trois');
      if(!/if\(\(currentUser\.bilans\|\|\[\]\)\.length===1\) rcm\('first_bilan_completed'\);[\s\S]{0,400}?majBadges\(\)/.test(s))
        return _echec('l’appel apres le bilan a disparu');
      if(!/_rendreInvitationInstall\(\);[\s\S]{0,400}?majBadges\(\)/.test(s))
        return _echec('l’appel apres la seance a disparu');
      // ET AUCUN COMPTEUR PARALLELE : badgesMerites ne tient rien, elle lit.
      const bm=String(badgesMerites);
      if(/saveUser|localStorage|currentUser/.test(bm))
        return _echec('badgesMerites ecrit ou lit hors de son argument');
      for(const f of ['seancesPrevuesParSemaine','_lundiDe','_riteRecords','streakSemaines'])
        if(bm.indexOf(f)<0) return _echec('badgesMerites n’utilise plus '+f);
      return true;})());

    // ══ 15/09/2026 — TON POINT DU JOUR ════════════════════════════════════
    // « UNE question par jour. Jamais deux. Trois questions, c'est un
    // formulaire, et un formulaire quotidien est abandonne en une semaine. »
    // Rien dans le code ne tient cette regle tout seul — une table peut
    // recevoir un tableau de deux entrees sans que rien ne casse — donc elle
    // est tenue ici.
    ok('Une question par jour, jamais deux',(()=>{
      const jours=Object.keys(PDJ_SEMAINE);
      if(jours.length!==5) return _echec(jours.length+' jours portent une question au lieu de cinq');
      for(const j of jours){
        const v=PDJ_SEMAINE[j];
        if(typeof v!=='string') return _echec('le jour '+j+' porte '+JSON.stringify(v)+' et non UN identifiant');
        if(!PDJ_QUESTIONS[v]) return _echec('le jour '+j+' designe « '+v+' », qui n’est pas une question');
      }
      // LE WEEK-END NE PORTE RIEN, et c'est voulu : deux jours sans rien
      // demander font partie du rythme.
      if(PDJ_SEMAINE[0]||PDJ_SEMAINE[6]) return _echec('le week-end porte une question');
      // Chaque question dit son titre et son accuse. Un accuse manquant
      // laisserait la carte se refermer sans rien confirmer.
      for(const k in PDJ_QUESTIONS){
        const q=PDJ_QUESTIONS[k];
        if(!q.titre||!q.accuse) return _echec(k+' n’a pas de titre ou pas d’accuse');
        // Un titre qui poserait deux questions se reconnait a son second « ? ».
        if((String(q.titre).match(/\?/g)||[]).length!==1)
          return _echec(k+' ne pose pas exactement une question : '+q.titre);
      }
      return true;})());

    // LE CALENDRIER COMPLET, les sept jours, et la DATE A LAQUELLE la reponse
    // appartient. Date#getDay rend 0 pour dimanche ; _woReminderDays, lui,
    // compte lundi=0. Les deux conventions coexistent dans ce fichier, et les
    // confondre decalerait la semaine entiere d'un jour — ce test l'attraperait.
    ok('Le tour de la semaine, jour par jour',(()=>{
      // 2026-09-13 est un dimanche. Sept jours a partir de la.
      const attendu=[
        ['2026-09-13',null,        null],          // dimanche
        ['2026-09-14','poids',     '2026-09-14'],  // lundi
        ['2026-09-15','sommeil',   '2026-09-15'],  // mardi
        ['2026-09-16','energie',   '2026-09-16'],  // mercredi
        // ⚠ JEUDI : LES PAS DE LA VEILLE. Personne ne connait son total du
        // jour a huit heures ; la reponse appartient donc au MERCREDI, et
        // l'ecrire au jeudi fausserait les deux journees.
        ['2026-09-17','pas',       '2026-09-16'],  // jeudi
        ['2026-09-18','sommeil',   '2026-09-18'],  // vendredi
        ['2026-09-19',null,        null]           // samedi
      ];
      for(const [iso,q,cible] of attendu){
        const t=Date.parse(iso+'T09:00:00');
        const r=pdjQuestionDuJour(t);
        if(r!==q) return _echec(iso+' → '+r+' au lieu de '+q);
        if(q&&pdjDateCible(q,t)!==cible)
          return _echec(iso+' → la reponse irait au '+pdjDateCible(q,t)+' au lieu du '+cible);
      }
      return true;})());

    // « Si la donnee du jour est deja saisie, la carte n'apparait pas. » — et
    // c'est vrai QUELLE QUE SOIT LA PORTE par laquelle la donnee est entree :
    // l'ecran Lifestyle, l'import par capture, la fin de seance. On interroge
    // la donnee, jamais un temoin de passage.
    ok('Une donnée déjà saisie referme la carte',(()=>{
      const base={role:'athlete',createdAt:Date.parse('2026-01-01'),
        sessions:[{date:Date.parse('2026-09-10'),exercises:[]}],
        weightLog:[],sleepLog:[],stepsLog:[],energieLog:[]};
      const cas=[
        ['2026-09-14','poids',  {weightLog:[{date:'2026-09-14',kg:78}]}],
        ['2026-09-15','sommeil',{sleepLog:[{date:'2026-09-15',duration:7}]}],
        ['2026-09-16','energie',{energieLog:[{date:'2026-09-16',niveau:3}]}],
        ['2026-09-17','pas',    {stepsLog:[{date:'2026-09-16',count:8000}]}]
      ];
      for(const [iso,q,rempli] of cas){
        const t=Date.parse(iso+'T09:00:00');
        const vide=pdjEtat(Object.assign({},base),t);
        if(!vide||vide.question!==q) return _echec(iso+' : la carte ne pose pas '+q);
        if(pdjEtat(Object.assign({},base,rempli),t))
          return _echec(iso+' : la carte reste alors que '+q+' est deja saisi');
      }
      // ⚠ ET LE JEUDI LIT BIEN LA VEILLE : des pas saisis pour AUJOURD'HUI ne
      // referment pas la carte, qui demande ceux d'hier.
      const jeudi=Date.parse('2026-09-17T09:00:00');
      if(!pdjEtat(Object.assign({},base,{stepsLog:[{date:'2026-09-17',count:8000}]}),jeudi))
        return _echec('le jeudi se referme sur les pas d’aujourd’hui au lieu de ceux d’hier');
      // Un poids saisi dans un BILAN du jour compte : c'est la meme donnee.
      if(pdjEtat(Object.assign({},base,{bilans:[{date:'2026-09-14',weight:78}]}),
                 Date.parse('2026-09-14T09:00:00')))
        return _echec('un poids saisi au bilan ne referme pas la carte');
      return true;})());

    // LES GARDES. Aucune n'est nouvelle : celles du poids sont EXACTEMENT
    // celles de la carte de pesee, et le bloc de reprise garde sa promesse
    // d'etre le seul bloc du haut de l'ecran.
    ok('La carte se tait quand elle n’a pas à parler',(()=>{
      const lundi=Date.parse('2026-09-14T09:00:00');
      const base=()=>({role:'athlete',createdAt:Date.parse('2026-01-01'),
        sessions:[{date:Date.parse('2026-09-10'),exercises:[]}],
        weightLog:[],sleepLog:[],stepsLog:[],energieLog:[]});
      if(!pdjEtat(base(),lundi)) return _echec('le temoin ne pose aucune question');
      const cas=[
        ['un coach',              u=>{u.role='coach';}],
        ['poids masque',          u=>{u.masquerPoids=true;}],
        // AUCUNE SEANCE et un compte de plus de 48 h : le bloc de reprise
        // occupe le haut de l'ecran, et une question d'intendance n'a rien a
        // faire a cote de « commencer maintenant ».
        ['bloc de reprise actif', u=>{u.sessions=[];}]
      ];
      for(const [nom,poser] of cas){
        const u=base(); poser(u);
        if(pdjEtat(u,lundi)) return _echec('la carte parle malgre : '+nom);
      }
      // ⚠ LES GARDES DU POIDS SONT CELLES DE LA CARTE DE PESEE, mot pour mot.
      // Si l'une des deux apprend une garde que l'autre ignore, un lundi
      // demanderait son poids a quelqu'un a qui l'accueil refuse de le montrer.
      const gardesPesee=String(renderCartePesee).match(/aTCA\(currentUser\)\|\|currentUser\.masquerPoids/);
      if(!gardesPesee) return _echec('les gardes de la carte de pesee ont change de forme');
      const gp=String(pdjEtat);
      for(const g of ['aTCA','masquerPoids','paliersDeficit'])
        if(gp.indexOf(g)<0) return _echec('pdjEtat ignore la garde '+g);
      return true;})());

    // « Ecris dans les structures existantes : ne cree pas un stockage
    // parallele. » Les trois reponses qui ont deja un tableau passent par la
    // FONCTION D'ECRITURE de ce tableau, celle-la meme qu'emploient les ecrans
    // dedies — pas par une ecriture directe qui divergerait de ses regles
    // (ecrasement par jour, fenetre de retention, fusion des champs).
    ok('Les réponses vont dans les tableaux existants',(()=>{
      const attendu={poids:'_recordWeight',sommeil:'_recordSleep',pas:'_recordSteps'};
      const fns={poids:pdjValiderPoids,sommeil:pdjValiderSommeil,pas:pdjValiderPas};
      for(const k in attendu){
        const src=String(fns[k]);
        // Le poids passe par _enregistrerPesee, qui porte _recordWeight ET la
        // garde d'ecart : c'est la meme porte que savePesee.
        const complet=(k==='poids')?src+String(_enregistrerPesee):src;
        if(complet.indexOf(attendu[k])<0)
          return _echec('la reponse « '+k+' » n’ecrit pas par '+attendu[k]);
        // Et JAMAIS d'ecriture directe dans le tableau.
        if(/currentUser\.(weightLog|sleepLog|stepsLog)\s*(=|\.push|\[)/.test(src))
          return _echec('la reponse « '+k+' » ecrit dans le tableau sans passer par sa fonction');
      }
      // ⚠ LA PESEE S'ENREGISTRE EN UN SEUL ENDROIT. savePesee et le point du
      // jour appellent la meme fonction : sans cela, la GARDE D'ECART —
      // « 784 kg pour 78,4 » — aurait pu ne vivre que dans l'une des deux.
      if(String(savePesee).indexOf('_enregistrerPesee')<0)
        return _echec('savePesee a repris une copie de l’enregistrement');
      if(String(_enregistrerPesee).indexOf('PESEE_ECART_CONFIRM')<0)
        return _echec('la garde d’ecart a quitte l’enregistrement commun');
      // L'energie est la SEULE qui n'avait pas de tableau. Le sien suit le
      // meme patron : une entree par jour, ecrasement et non ajout.
      const sv=currentUser;
      try{
        currentUser={role:'athlete',energieLog:[]};
        if(!_recordEnergie('2026-09-16',4)) return _echec('une energie valide est refusee');
        if(!_recordEnergie('2026-09-16',2)) return _echec('la correction est refusee');
        if(currentUser.energieLog.length!==1)
          return _echec('le meme jour occupe '+currentUser.energieLog.length+' entrees');
        if(currentUser.energieLog[0].niveau!==2) return _echec('la correction n’a pas pris');
        for(const mauvais of [0,6,-1,'x',null,undefined])
          if(_recordEnergie('2026-09-16',mauvais)) return _echec(JSON.stringify(mauvais)+' est accepte comme niveau');
        return true;
      } finally { currentUser=sv; }})());

    // ⚠ LA CONTRAINTE DE PLACE EST UNE CONTRAINTE DE SECURITE, pas de gout.
    // Une question d'intendance ne passe JAMAIS devant une fin d'acces, une
    // contre-indication ou une douleur declaree. Le test lit le DOCUMENT, qui
    // est ce qui decide reellement de l'ordre a l'ecran.
    ok('La carte ne passe jamais devant la douleur ni l’échéance',(()=>{
      const c=document.getElementById('clh-point-jour');
      if(!c) return _echec('le noeud de la carte n’existe pas');
      const P=Node.DOCUMENT_POSITION_PRECEDING, S=Node.DOCUMENT_POSITION_FOLLOWING;
      for(const id of ['clh-echeance','clh-contraintes','clh-douleur']){
        const e=document.getElementById(id);
        if(!e) return _echec(id+' a disparu de l’accueil');
        if(!(e.compareDocumentPosition(c)&S))
          return _echec('la carte passe devant '+id);
      }
      // Et elle reste EN HAUT de tout le reste : une question qu'il faut aller
      // chercher n'est pas posee.
      for(const id of ['clh-stats','clh-hero','clh-pesee','clh-prog-exercises']){
        const e=document.getElementById(id);
        if(e&&!(e.compareDocumentPosition(c)&P))
          return _echec('la carte est passee sous '+id);
      }
      return true;})());

    // LE LUNDI, UN SEUL CHAMP DE PESEE SUR L'ECRAN. Sans la garde de
    // renderCartePesee, l'accueil en affichait DEUX a quinze centimetres l'un
    // de l'autre — la carte « Pesee du jour » et la question du jour.
    ok('Le lundi, l’accueil ne demande le poids qu’une fois',(()=>{
      const sv=currentUser, svQ=pdjQuestionDuJour;
      try{
        pdjQuestionDuJour=()=>'poids';
        currentUser={id:'q',email:'q@t.fr',role:'athlete',fname:'K',
          createdAt:Date.parse('2026-01-01'),
          sessions:[{date:Date.now()-3*864e5,exercises:[]}],
          bilans:[],sessions_config:[{active:true}],
          weightLog:[],sleepLog:[],stepsLog:[],energieLog:[]};
        _rendrePointDuJour();
        renderCartePesee();
        const zone=document.getElementById('s-client-home');
        const champs=zone.querySelectorAll('#pdj-poids,#pesee-input').length;
        if(champs!==1) return _echec(champs+' champs de pesee sur l’ecran');
        if(!document.getElementById('pdj-poids')) return _echec('c’est l’ancienne carte qui a gagne');
        // ET LA CARTE DE PESEE REVIENT des que la question est repondue :
        // c'est ce qui rend la moyenne sur sept jours a l'athlete.
        currentUser.weightLog=[{date:pdjDateCible('poids',Date.now()),kg:78}];
        _rendrePointDuJour();
        renderCartePesee();
        if(document.getElementById('pdj-poids')) return _echec('la question survit a sa reponse');
        return document.getElementById('pesee-input')
          ?true:_echec('la carte de pesee ne revient pas apres la reponse');
      } finally {
        currentUser=sv; pdjQuestionDuJour=svQ;
        try{ document.getElementById('clh-point-jour').innerHTML=''; }catch(e){}
        try{ document.getElementById('clh-pesee').innerHTML=''; }catch(e){}
      }})());

    // UN SEUL CONTROLE PAR CARTE. Le gabarit peut poser un champ OU des
    // pastilles, jamais les deux : deux controles, c'est deja un formulaire.
    ok('Le gabarit ne pose qu’un seul contrôle',(()=>{
      for(const q in PDJ_QUESTIONS){
        const h=_htmlPointDuJour({question:q,date:'2026-09-15',titre:PDJ_QUESTIONS[q].titre});
        const d=document.createElement('div'); d.innerHTML=h;
        const champs=d.querySelectorAll('input').length;
        const groupes=d.querySelectorAll('.pdj-choix').length;
        if(champs+groupes!==1)
          return _echec(q+' pose '+champs+' champ(s) et '+groupes+' groupe(s) de pastilles');
        if(d.querySelectorAll('.pdj-q').length!==1) return _echec(q+' pose plusieurs questions');
        // Chaque pastille est une cible tactile : une rangee qui deborde
        // vaut une rangee qu'on ne peut pas viser.
        if(groupes&&!d.querySelectorAll('.pdj-past').length)
          return _echec(q+' annonce des pastilles et n’en pose aucune');
      }
      // La carte vide ne rend RIEN — pas un cadre vide.
      return _htmlPointDuJour(null)===''?true:_echec('l’etat vide rend quelque chose');})());

    // ══ 15/09/2026 — L'INSCRIPTION ALLEGEE, ET LE VERROU DE L'ARTICLE 9 ═══
    //
    // ⚠ CES ASSERTIONS SONT LES SEULES DU DEPOT DONT UN ECHEC EST UNE FAUTE
    // AU SENS DU RGPD, et non un defaut de produit. Le deplacement de six
    // champs hors de l'inscription n'est legal QUE si aucune donnee de sante
    // ne peut etre ecrite avant le consentement. C'est ce qu'elles verifient.

    // LES DEUX CONSENTEMENTS RESTENT DEUX. Article 6 et article 9 sont deux
    // regimes : ni fusionnes, ni pre-coches, ni deduits l'un de l'autre.
    ok('Les deux consentements restent strictement séparés',(()=>{
      const src=_prodSrc();
      // Le formulaire d'inscription ne porte plus QUE la case des conditions.
      if(!/id="r-cgu"/.test(src)) return _echec('la case des conditions a disparu de l’inscription');
      if(/id="r-health"/.test(src)) return _echec('la case santé est revenue dans le formulaire d’inscription');
      // L'ecran dedie la porte, et il la porte SEULE.
      if(!/id="cs-health"/.test(src)) return _echec('l’écran de consentement santé n’a pas sa case');
      const ecran=src.slice(src.indexOf('id="s-consent-sante"'),src.indexOf('id="s-register"'));
      if(/id="cs-cgu"/.test(ecran)) return _echec('l’écran santé porte aussi les conditions : les deux sont fusionnés');
      // AUCUNE DES DEUX N'EST PRE-COCHEE — article 9.2.a : un consentement
      // explicite est un GESTE, pas une case trouvée déjà faite.
      for(const id of ['r-cgu','cs-health']){
        const i=src.indexOf('id="'+id+'"');
        const bal=src.slice(src.lastIndexOf('<input',i),src.indexOf('>',i));
        if(/\bchecked\b/.test(bal)) return _echec(id+' est pré-cochée');
      }
      // ET LE CODE NE DEDUIT JAMAIS L'UN DE L'AUTRE : accepter les conditions
      // n'ecrit rien sur `health`, accepter la sante n'ecrit rien sur `cgu`.
      // ⚠ COMMENTAIRES RETIRES AVANT LECTURE. Les deux fonctions EXPLIQUENT
      // en commentaire qu'elles ne reposent pas l'autre consentement, et la
      // sonde se reconnaissait dans ces phrases : elle accusait le code de
      // faire exactement ce qu'il dit ne pas faire. Sixieme fois que ce depot
      // apprend qu'une sonde peut matcher son propre sujet.
      const _sansCom=f=>String(f).replace(/\/\/[^\r\n]*/g,'');
      if(/health\s*:\s*true/.test(_sansCom(_validerReconsentement)))
        return _echec('la re-acceptation des conditions repose le consentement santé');
      if(/cgu\s*:\s*true/.test(_sansCom(accepterConsentementSante)))
        return _echec('l’acceptation santé repose le consentement aux conditions');
      // Un compte neuf part avec health:false, jamais true.
      const dr=src.slice(src.indexOf('async function doRegister'));
      const cons=dr.slice(dr.indexOf('consent:{'),dr.indexOf('consent:{')+120);
      if(!/health:false/.test(cons)) return _echec('un compte neuf ne part pas avec health:false : '+cons.slice(0,80));
      return true;})());

    // L'INSCRIPTION NE DEMANDE PLUS QUE QUATRE CHOSES ET UNE CASE — et les six
    // autres sont DEPLACEES, pas supprimees : chacune a son ecran et sa porte.
    ok('L’inscription est allégée par déplacement, jamais par suppression',(()=>{
      const src=_prodSrc();
      // ⚠ BORNES DANS L'ORDRE DU DOCUMENT. s-login PRECEDE s-register :
      // la tranche partait a l'envers et ne contenait rien, si bien que le
      // test annoncait « r-email a quitte l'inscription » sur un formulaire
      // parfaitement intact.
      const _d=src.indexOf('id="s-register"');
      const _f=src.indexOf('<div id="s-',_d+10);
      const form=src.slice(_d,_f>_d?_f:_d+40000);
      for(const id of ['r-email','r-pwd','r-pwd2','r-cgu'])
        if(form.indexOf('id="'+id+'"')<0) return _echec(id+' a quitté l’inscription');
      for(const id of ['r-fname','r-lname','r-birthdate','r-gender','r-health'])
        if(form.indexOf('id="'+id+'"')>=0) return _echec(id+' est encore demandé à l’inscription');
      // ⚠ CHAQUE CHAMP DEPLACE A BIEN UN AILLEURS. Sans cette moitie-ci,
      // « allege » voudrait dire « supprime ».
      const ailleurs={'r-fname':'id-fname','r-lname':'id-lname',
                      'r-birthdate':'nai-birthdate','r-gender':'nai-gender',
                      'r-health':'cs-health'};
      for(const k in ailleurs)
        if(src.indexOf('id="'+ailleurs[k]+'"')<0)
          return _echec(k+' a été supprimé au lieu d’être déplacé : '+ailleurs[k]+' n’existe pas');
      // Et chacun de ces ecrans porte la PHRASE qui dit pourquoi on demande la.
      for(const z of ['id-motif','nai-motif','cs-motif'])
        if(src.indexOf('id="'+z+'"')<0) return _echec(z+' : l’écran ne dit pas pourquoi il demande');
      for(const t of [IDENTITE_MOTIFS,NAISSANCE_MOTIFS,SANTE_MOTIFS])
        for(const k in t)
          if(!t[k]||String(t[k]).length<20) return _echec('un motif est vide ou trop court : '+k);
      return true;})());

    // ⚠ LE CONTROLE DES 16 ANS SUIT SA DONNEE. Il ne pouvait plus vivre a
    // l'inscription, ou il n'y a plus de date a verifier ; il devait donc se
    // retrouver INTACT la ou la date est desormais demandee.
    ok('Le contrôle des 16 ans révolus s’applique où la date est demandée',(()=>{
      const f=String(validerNaissanceGenre);
      if(f.indexOf('AGE_MINIMUM')<0) return _echec('validerNaissanceGenre ne contrôle plus l’âge');
      if(f.indexOf('_ageRevolu')<0) return _echec('l’âge n’est plus calculé depuis la date');
      if(!/age<AGE_MINIMUM/.test(f.replace(/\s/g,''))) return _echec('le seuil n’est plus comparé');
      if(AGE_MINIMUM!==16) return _echec('AGE_MINIMUM vaut '+AGE_MINIMUM+' au lieu de 16');
      // Les bornes d'absurdite restent, elles aussi.
      if(!/age>120/.test(f.replace(/\s/g,''))) return _echec('la borne haute a disparu');
      // Et doRegister ne le contrôle plus, faute de date — mais il ne doit pas
      // pour autant avoir perdu le rôle et les conditions.
      const dr=String(doRegister);
      if(dr.indexOf('r-birthdate')>=0) return _echec('doRegister lit encore une date qui n’existe plus');
      if(dr.indexOf('selRole')<0) return _echec('doRegister ne contrôle plus le rôle');
      if(dr.indexOf('r-cgu')<0) return _echec('doRegister ne contrôle plus les conditions');
      return true;})());

    // ⚠ LA CLASSIFICATION NE DOIT PAS POUVOIR DERIVER.
    //
    // Le verrou coupe ce qui est dans CHAMPS_SANTE. Un champ ajoute demain et
    // oublie dans les deux listes passerait donc au travers, en silence, et
    // personne ne le verrait avant la fuite. Ce test balaye le SOURCE, releve
    // tout champ affecte sur un dossier, et tombe tant qu'il n'est pas classe.
    // C'est ce qui rend la garantie durable plutot que ponctuelle.
    ok('Chaque champ du dossier est classé santé ou non-santé',(()=>{
      const src=_prodSrc();
      const vus=new Set();
      const re=/(?:currentUser|user|athlete|safe|u)\.([a-zA-Z_][a-zA-Z0-9_]*)\s*=[^=]/g;
      let m; while((m=re.exec(src))) vus.add(m[1]);
      const classes=new Set(CHAMPS_SANTE.concat(CHAMPS_NON_SANTE));
      const orphelins=[...vus].filter(k=>!classes.has(k));
      if(orphelins.length)
        return _echec('champ(s) non classé(s), donc non protégé(s) : '+orphelins.join(', '));
      // ET AUCUN CHAMP DANS LES DEUX LISTES : il serait coupé ou gardé selon
      // l'ordre de lecture, ce qui est le pire des deux mondes.
      const double=CHAMPS_SANTE.filter(k=>CHAMPS_NON_SANTE.indexOf(k)>=0);
      if(double.length) return _echec('champ(s) dans les deux listes : '+double.join(', '));
      // Les dix familles nommees par le texte de la case ont chacune au moins
      // un champ du cote santé. C'est le lien entre le code et le document.
      const attendus=['weightLog','bilans','photosProgression','cycle','sleepLog',
                      'nutrition','stepsLog','age','birthdate','pes'];
      for(const k of attendus)
        if(CHAMPS_SANTE.indexOf(k)<0) return _echec(k+' n’est pas classé en donnée de santé');
      return true;})());

    // ⚠ LE VERROU. « AUCUNE donnée de santé ne doit pouvoir être écrite, ni
    // localement ni à distance, avant que le consentement ait été recueilli. »
    ok('Sans consentement santé, rien de santé ne s’écrit',(()=>{
      const sansAccord={email:'x@t.fr',role:'athlete',fname:'K',lname:'G',
        consent:{cgu:true,health:false,policyVersion:POLICY_VERSION},
        weightLog:[{date:'2026-09-14',kg:78}],sleepLog:[{date:'2026-09-14',duration:7}],
        stepsLog:[{date:'2026-09-14',count:9000}],cycle:{regles:['2026-09-01']},
        bilans:[{date:1,taille:180}],nutrition:{caffeine:{}},birthdate:'1990-01-01',
        age:36,gender:'H',grossesse:{etat:'x'},pes:true,
        sessions:[{date:1,exercises:[],metrics:{fatigue:7,energie:4}}]};
      const coupe=_sansSante(sansAccord);
      for(const k of ['weightLog','sleepLog','stepsLog','cycle','bilans','nutrition',
                      'birthdate','age','gender','grossesse','pes'])
        if(k in coupe) return _echec(k+' survit à l’absence de consentement');
      // Ce qui n'est PAS de la santé traverse : sans cela, personne ne
      // pourrait s'inscrire, se rattacher, ni recevoir de programme.
      for(const k of ['email','role','fname','lname','consent'])
        if(!(k in coupe)) return _echec(k+' est coupé alors qu’il n’est pas une donnée de santé');
      // S'ENTRAINER N'EST PAS UNE DONNEE DE SANTE — les seances restent — MAIS
      // LEURS RESSENTIS EN SONT : le §2 nomme fatigue, sensations, motivation.
      if(!Array.isArray(coupe.sessions)||coupe.sessions.length!==1)
        return _echec('les séances sont perdues : on ne peut plus s’entraîner sans consentement santé');
      if(coupe.sessions[0].metrics) return _echec('les ressentis de séance survivent');
      // ⚠ ET LE DOSSIER QUI A CONSENTI N'EST PAS TOUCHE — meme objet, aucune
      // copie. Un verrou qui recopierait tout a chaque sauvegarde serait
      // abandonne au premier ralentissement.
      const avecAccord={email:'y@t.fr',consent:{cgu:true,health:true,policyVersion:POLICY_VERSION},
        weightLog:[{date:'2026-09-14',kg:78}]};
      if(_sansSante(avecAccord)!==avecAccord) return _echec('le dossier consentant est recopié');
      // ⚠ ET CELUI DONT L'ACCORD EST PERIME GARDE SES DONNEES. Il a consenti
      // sous un texte anterieur : ses donnees sont legitimes, c'est la
      // PROCHAINE ecriture qui redemande. Un verrou qui lirait la version les
      // effacerait toutes a la prochaine sauvegarde.
      const perime={email:'z@t.fr',consent:{cgu:true,health:true,policyVersion:'2020-01'},
        weightLog:[{date:'2026-09-14',kg:78}]};
      if(_sansSante(perime)!==perime) return _echec('un accord périmé fait perdre les données déjà recueillies');
      if(aConsentiSante(perime)) return _echec('un accord périmé passe pour à jour');
      if(santeJamaisConsentie(perime)) return _echec('un accord périmé passe pour inexistant');
      return true;})());

    // LE VERROU EST SUR LE CHEMIN, ET SUR LE SEUL QUI COMPTE. saveUser est le
    // point par lequel un dossier devient durable — stockage local ET poussee
    // distante partent de la. Un verrou pose ailleurs laisserait un chemin.
    ok('Le verrou est posé sur l’unique chemin d’écriture',(()=>{
      const f=String(saveUser);
      if(f.indexOf('_sansSante')<0) return _echec('saveUser n’appelle plus le verrou');
      // Ce qui est range dans `users` — donc pousse — est l'objet COUPE, et non
      // currentUser : sans cela le local serait protege et le distant non.
      if(!/users\[currentUser\.email\]\s*=\s*aEcrire/.test(f))
        return _echec('c’est currentUser qui part vers la base, pas la version coupée');
      if(!/DB\.set\('session',aEcrire\)/.test(f))
        return _echec('la session locale garde la version non coupée');
      // ET LA PORTE EST DANS LES PRIMITIVES, pas sur leurs appelants.
      // ⚠ LA PORTE EST SUR LE GESTE, PAS DANS LA PRIMITIVE — et ce n'est pas
      // un detail de gout. _recordWeight et ses surs sont aussi appelees par
      // l'import par capture d'ecran et par la fusion de synchronisation, ou
      // il n'y a personne pour repondre a une question : leur donner un effet
      // de bord d'interface les rendait inutilisables la-bas. Le VERROU de
      // saveUser garantit ; la porte, elle, demande au bon moment.
      const gestes=[['_enregistrerPesee',_enregistrerPesee],['saveSleep',saveSleep],
        ['saveSteps',saveSteps],['sanEnregistrer',sanEnregistrer],
        ['pdjValiderPas',pdjValiderPas],['pdjValiderSommeil',pdjValiderSommeil],
        ['pdjValiderEnergie',pdjValiderEnergie],['setCyclePhase',setCyclePhase]];
      for(const [n,f2] of gestes)
        if(String(f2).indexOf('demanderConsentementSante')<0)
          return _echec(n+' écrit une donnée de santé sans passer par la porte');
      // Et les primitives restent PURES : aucun effet de bord d'interface.
      for(const [n,f2] of [['_recordWeight',_recordWeight],['_recordSleep',_recordSleep],
                           ['_recordSteps',_recordSteps],['_recordEnergie',_recordEnergie]])
        if(String(f2).indexOf('demanderConsentementSante')>=0)
          return _echec(n+' porte une question : elle est aussi appelée par l’import');
      return true;})());

    // LA PORTE BLOQUANTE NE PORTE PLUS QUE LES CGU. Y laisser la santé
    // rendrait le consentement de fait obligatoire pour ouvrir l'app — ce que
    // le déplacement supprime — puisque sa seule autre issue est la
    // déconnexion.
    ok('La modale bloquante ne réclame plus le consentement santé',(()=>{
      const f=String(_consentementAJour);
      if(f.indexOf('c.health')>=0) return _echec('la porte bloquante exige encore la santé');
      if(f.indexOf('c.cgu')<0) return _echec('la porte bloquante n’exige plus les conditions');
      if(f.indexOf('POLICY_VERSION')<0) return _echec('la version du texte n’est plus vérifiée');
      // Un compte neuf, qui n'a consenti qu'aux conditions, n'est pas bloqué.
      const neuf={consent:{cgu:true,health:false,policyVersion:POLICY_VERSION}};
      if(!_consentementAJour(neuf)) return _echec('un compte neuf est bloqué par la modale');
      if(aConsentiSante(neuf)) return _echec('un compte neuf passe pour avoir consenti à la santé');
      // Mais un compte sans CGU, ou sur un texte périmé, l'est toujours.
      if(_consentementAJour({consent:{cgu:false,policyVersion:POLICY_VERSION}}))
        return _echec('un compte sans conditions passe');
      if(_consentementAJour({consent:{cgu:true,policyVersion:'2020-01'}}))
        return _echec('un compte sur un texte périmé passe');
      return true;})());

    // ══ 15/09/2026 — L'ESSAI ATHLETE ══════════════════════════════════════
    //
    // ⚠ TROIS SEANCES SONT DEVENUES UN MOIS (lot 6, 23/09/2026), ET CE BLOC A
    //   CHANGE DE CONTRAT, PAS D'EXIGENCE.
    //
    //   Ce qu'il tenait : la phrase dit EXACTEMENT ce que l'essai fait, le
    //   compteur ne peut pas diverger de ce qui est annonce, l'essai ne se
    //   rouvre jamais, et le paywall se decide en un seul endroit. Tout cela
    //   tient encore, mot pour mot.
    //
    //   Ce qui a change : l'unite. Les seances comptaient parce que le JOUR ne
    //   se tenait nulle part — l'horloge d'un telephone se change en trois
    //   secondes. Le lot 0 a pose l'echeance dans droits/, ou personne n'ecrit
    //   sauf le serveur : le mois devient tenable, et c'est le modele que
    //   Kevin vend (« un mois d'essai complet, sans carte bancaire »).
    //
    //   L'ANCIENNE ASSERTION « la phrase ne promet ni duree » EST DONC
    //   INVERSEE, et c'est voulu : elle promet un mois, et le produit doit
    //   accorder un mois. ESSAI_JOURS et la phrase sont verifies ensemble.
    ok('La phrase dit exactement ce que l’essai fait',(()=>{
      if(typeof PROMESSE_ATHLETE!=='string'||!PROMESSE_ATHLETE)
        return _echec('la phrase n’existe pas');
      // LA DUREE ANNONCEE EST CELLE QU'ON ACCORDE. La phrase dit « un mois » ;
      // le jour où ESSAI_JOURS ne vaudra plus trente, cette assertion tombe et
      // oblige à réécrire la phrase plutôt qu'à mentir.
      if(ESSAI_JOURS!==30)
        return _echec('ESSAI_JOURS vaut '+ESSAI_JOURS+' : la phrase promet toujours un mois');
      if(!/mois/i.test(PROMESSE_ATHLETE))
        return _echec('la phrase ne dit pas la durée accordée');
      if(!/carte bancaire/i.test(PROMESSE_ATHLETE))
        return _echec('la phrase ne dit pas qu’aucune carte n’est demandée');
      // ET ELLE DIT QUE ÇA S'ARRÊTE : une phrase qui ne nommerait que ce qui
      // est libre serait la moitié de la vérité.
      if(!/ensuite|après|apres/i.test(PROMESSE_ATHLETE))
        return _echec('la phrase ne dit pas ce qui vient après');
      // AUCUN AU-DELA PROMIS.
      for(const mot of ['illimit','toujours','à vie','gratuit à vie'])
        if(new RegExp(mot,'i').test(PROMESSE_ATHLETE))
          return _echec('la phrase promet un au-delà : « '+mot+' »');
      return true;})());

    // ÉCRITE UNE FOIS, POSÉE PARTOUT — même mécanique que prixAutonomie, et
    // pour la même raison : trois textes en dur annonceraient trois essais
    // différents le jour où la phrase change.
    ok('La phrase d’essai n’est écrite qu’une fois',(()=>{
      const src=_prodSrc();
      const n=(src.match(/data-promesse-athlete/g)||[]).length;
      if(n<3) return _echec('moins de deux emplacements portent la phrase ('+n+' occurrences)');
      const bout='Ton premier mois est complet';
      const m=(src.split(bout).length-1);
      if(m!==1) return _echec(m+' copies du texte en production au lieu d’une');
      if(String(_poserPromesseAthlete).indexOf('PROMESSE_ATHLETE')<0)
        return _echec('le poseur n’utilise pas la constante');
      return true;})());

    // LE MOIS, JOUR PAR JOUR. L'échéance est lue dans le dossier tant que le
    // serveur n'a rien dit, et dans droits/ dès qu'il parle.
    ok('L’essai dure un mois, s’arrête net, et ne se rouvre jamais',(()=>{
      const u={id:'e',email:'e@t',role:'athlete',status:'FREE',sessions:[]};
      if(essaiJoursRestants(u)!==null) return _echec('un dossier sans essai en annonce un');
      if(texteEssaiRestant(u)!=='') return _echec('un dossier sans essai affiche une ligne');
      if(checkAccess(u)) return _echec('un dossier sans essai a l’accès');
      if(!essaiOuvrir(u)) return _echec('l’essai ne s’ouvre pas');
      if(essaiOuvrir(u)) return _echec('l’essai se rouvre : il serait infini');
      // LA FIN EST POSEE A L'OUVERTURE, et elle vaut un mois.
      const attendu=ESSAI_JOURS*86400000;
      const ecart=Math.abs((u.essai.finit-u.essai.ouvertLe)-attendu);
      if(ecart>60000) return _echec('la fin posée n’est pas à un mois : '+ecart+' ms d’écart');
      if(essaiJoursRestants(u)!==ESSAI_JOURS) return _echec('jour 1 : '+essaiJoursRestants(u)+' jours restants');
      if(essaiJour(u)!==1) return _echec('jour 1 annoncé comme le jour '+essaiJour(u));
      if(!essaiActif(u)||essaiFini(u)) return _echec('l’essai n’est pas actif le premier jour');
      // LE MOIS S'ECOULE : on déplace l'ouverture, ce qui revient au même que
      // de déplacer l'horloge, sans toucher à l'horloge du banc.
      const dans=n=>{ const t0=Date.now()-n*86400000;
        return {id:'e',email:'e@t',role:'athlete',status:'FREE',sessions:[],
          essai:{ouvertLe:t0,finit:t0+attendu}}; };
      for(const [n,reste] of [[0,30],[9,21],[21,9],[27,3],[29,1]]){
        const v=dans(n);
        if(essaiJoursRestants(v)!==reste) return _echec('jour '+(n+1)+' : '+essaiJoursRestants(v)+' restants au lieu de '+reste);
        if(!essaiActif(v)) return _echec('jour '+(n+1)+' : l’essai est déjà fini');
        if(!checkAccess(v)) return _echec('jour '+(n+1)+' : l’accès est coupé');
      }
      const fini=dans(30);
      if(essaiActif(fini)) return _echec('au trente-et-unième jour l’essai court encore');
      if(!essaiFini(fini)) return _echec('l’essai fini n’est pas reconnu comme fini');
      if(checkAccess(fini)) return _echec('l’accès reste ouvert après le mois');
      if(texteEssaiRestant(fini)!=='') return _echec('la ligne parle encore après la fin');
      // UN DOSSIER DEJA GARNI N'ENTAME PAS SON MOIS : la fin se compte en
      // jours, plus en séances déjà faites.
      const v={id:'v',email:'v@t',role:'athlete',status:'FREE',
        sessions:Array.from({length:10},(_,i)=>({date:i+1}))};
      essaiOuvrir(v);
      return essaiJoursRestants(v)===ESSAI_JOURS
        ?true:_echec('un dossier déjà garni ouvre un essai entamé : '+essaiJoursRestants(v));})());

    // ⚠ UNE SEULE QUESTION « FAUT-IL MONTRER LE PAYWALL », et six appels.
    ok('Le paywall se décide en un seul endroit',(()=>{
      const src=_prodSrc().replace(/\/\/[^\r\n]*/g,'');
      const maison=(src.match(/role!=='coach'&&\(\w+\.status\|\|'FREE'\)==='FREE'/g)||[]).length;
      if(maison) return _echec(maison+' copie(s) de la question subsistent');
      const n=(src.match(/doitVoirLePaywall\(/g)||[]).length;
      if(n<7) return _echec('seulement '+n+' mention(s) du prédicat : des chemins n’y passent pas');
      const t0=Date.now();
      const enCours={role:'athlete',status:'FREE',sessions:[],
        essai:{ouvertLe:t0,finit:t0+ESSAI_JOURS*86400000}};
      if(doitVoirLePaywall(enCours)) return _echec('un athlète en essai est renvoyé au paywall');
      const fini={role:'athlete',status:'FREE',sessions:[],
        essai:{ouvertLe:t0-40*86400000,finit:t0-10*86400000}};
      if(!doitVoirLePaywall(fini)) return _echec('un essai fini échappe au paywall');
      if(!doitVoirLePaywall({role:'athlete',status:'FREE',sessions:[]}))
        return _echec('un compte FREE sans essai échappe au paywall');
      if(doitVoirLePaywall({role:'coach',status:'FREE'}))
        return _echec('un coach est renvoyé au paywall');
      if(doitVoirLePaywall({role:'athlete',status:'COACHING_SUIVI'}))
        return _echec('un athlète à code est renvoyé au paywall');
      // ET LES DEUX SORTIES NE SONT PAS LA MEME (lot 6) : celui qui a vécu le
      // mois voit son bilan, celui qui n'a jamais eu d'essai voit le code.
      if(ecranApresEssai(fini)!=='s-essai-bilan') return _echec('l’essai fini ne mène pas au bilan');
      if(ecranApresEssai({role:'athlete',status:'FREE'})!=='s-client-code')
        return _echec('un compte sans essai ne mène plus à l’écran de code');
      return true;})());

    // L'ESSAI S'OUVRE POUR UN ATHLÈTE SANS CODE, ET POUR LUI SEUL.
    ok('L’essai s’ouvre à l’inscription sans code, jamais ailleurs',(()=>{
      const src=_prodSrc().replace(/\/\/[^\r\n]*/g,'');
      const n=(src.match(/essaiOuvrir\(/g)||[]).length;
      if(n!==2) return _echec(n+' mentions de essaiOuvrir au lieu de deux');
      if(!/_appliquerCodeApresInscription\(\)\)\s*return;[\s\S]{0,600}?essaiOuvrir\(currentUser\)/.test(src))
        return _echec('l’essai ne s’ouvre pas dans la branche sans code');
      const c={role:'coach',sessions:[]};
      if(essaiOuvrir(c)) return _echec('un coach reçoit un essai athlète');
      return true;})());

    // LA MENTION RESTE DISCRÈTE, ET LA SÉQUENCE NE HARCÈLE PAS.
    ok('La mention d’essai suit la séquence, et se tait entre-temps',(()=>{
      const z=document.getElementById('clh-essai');
      if(!z) return _echec('le nud de la mention n’existe pas');
      const S=Node.DOCUMENT_POSITION_FOLLOWING;
      for(const id of ['clh-echeance','clh-contraintes','clh-douleur']){
        const e=document.getElementById(id);
        if(e&&!(e.compareDocumentPosition(z)&S))
          return _echec('la mention passe devant '+id);
      }
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.ess-ligne\{([^}]*)\}/);
      if(!m) return _echec('la règle .ess-ligne n’existe pas');
      // DISCRÈTE : ni rouge de relance, ni animation, ni pastille.
      if(/var\(--red\)|background:var\(--red/.test(m[1]))
        return _echec('la mention crie : '+m[1].slice(0,70));
      if(/animation:/.test(m[1])) return _echec('la mention bouge');
      // LA SEQUENCE, JOUR PAR JOUR : on accueille, on se tait, on rappelle,
      // puis on chiffre. C'est celle que Kevin a écrite.
      const dans=n=>{ const t0=Date.now()-n*86400000;
        return {role:'athlete',status:'FREE',email:'seq@t.fr',
          sessions_config:[{day:'Lundi',active:true,exercises:[{name:'SQUAT'},{name:'TRACTIONS'}]}],
          sessions:[],essai:{ouvertLe:t0,finit:t0+ESSAI_JOURS*86400000}}; };
      const j1=texteEssaiRestant(dans(0));
      if(!/un mois/i.test(j1)||!/première séance/i.test(j1))
        return _echec('le premier jour n’accueille pas : « '+j1+' »');
      for(const n of [1,5,10,19]){
        if(texteEssaiRestant(dans(n))!=='')
          return _echec('la mention parle au jour '+(n+1)+' : « '+texteEssaiRestant(dans(n))+' »');
      }
      const j21=texteEssaiRestant(dans(20));
      if(!/Il te reste 9 jours d’accès complet/.test(j21))
        return _echec('le vingt-et-unième jour ne rappelle rien : « '+j21+' »');
      const j27=texteEssaiRestant(dans(26));
      if(!/Plus que 3 jours/.test(j27)) return _echec('le vingt-septième jour ne chiffre pas : « '+j27+' »');
      if(j27.indexOf(prixOffre('ultime'))<0||j27.indexOf(prixMoisAnnuel('ultime'))<0)
        return _echec('la relance finale ne dit pas le prix d’Ultime');
      // ET ELLE PARLE DE SON PROGRAMME A LUI : deux exercices posés, donc deux
      // exercices annoncés.
      if(!/séance/i.test(j27)) return _echec('la relance ne parle pas de ce qu’il a construit');
      return true;})());

    // LE BOUT DU MOIS : ce qu'on montre, c'est SON programme.
    ok('LOT 6 — L’ÉCRAN DE FIN MONTRE SON PROGRAMME, ET DIT QUE RIEN N’EST EFFACÉ',(()=>{
      const sv=currentUser;
      try{
        const t0=Date.now()-40*86400000;
        currentUser={id:'fin',email:'fin@t.fr',role:'athlete',status:'FREE',
          essai:{ouvertLe:t0,finit:t0+ESSAI_JOURS*86400000},
          sessions:[{date:1},{date:2},{date:3},{date:4}],
          sessions_config:[
            {day:'Lundi',active:true,exercises:[{name:'DEVELOPPE COUCHE BARRE'},{name:'DIPS'}]},
            {day:'Mardi',active:false,exercises:[]},
            {day:'Mercredi',active:true,exercises:[{name:'TRACTIONS'}]}]};
        if(!rendreEssaiBilan(currentUser)) return _echec('l’écran ne se dessine pas');
        const z=document.getElementById('eb-corps');
        const txt=z.textContent.replace(/\s+/g,' ');
        if(txt.indexOf('Rien n’est effacé')<0) return _echec('l’écran ne dit pas que rien n’est effacé');
        if(!/2 séances/.test(txt)) return _echec('les séances de son programme ne sont pas comptées : « '+txt.slice(0,160)+' »');
        if(!/4 séances? terminées?/.test(txt)) return _echec('les séances faites ne sont pas dites');
        // LES DEUX FORMULES, AVEC LEURS PRIX, ET AUCUN AUTRE PRIX EN DUR.
        // ⚠ LE TEXTE LU EST NORMALISE (\s avale l'espace insecable des prix) :
        //   on normalise donc aussi le prix attendu, sans quoi « 24,90 € »
        //   cherche un caractere que la lecture vient de remplacer.
        const _nb=String.fromCharCode(160);
        for(const p of [prixOffre('ultime'),prixMoisAnnuel('ultime'),prixOffre('essentielle'),prixMoisAnnuel('essentielle')])
          if(txt.indexOf(p.split(_nb).join(' '))<0) return _echec('le prix '+p+' ne se lit pas');
        // ET DES PORTES, PAS UN MUR : Ultime, Essentielle, le coaching, le code.
        const b=[...z.querySelectorAll('button,a')];
        if(b.length<4) return _echec(b.length+' portes seulement');
        if(!b.some(x=>/beacons\.ai\/kevin\.gllc/.test(x.getAttribute('href')||'')))
          return _echec('aucune porte ne mène au coaching');
        if(!b.some(x=>/s-client-code/.test(x.getAttribute('onclick')||'')))
          return _echec('aucune porte ne mène au code coach');
        // NI TIRET CADRATIN, NI VOCABULAIRE TECHNIQUE.
        if(txt.indexOf(String.fromCharCode(8212))>=0||txt.indexOf(String.fromCharCode(8211))>=0)
          return _echec('un tiret cadratin traîne sur l’écran de fin');
        for(const mot of ['palier','quota','capacité','synchronisation'])
          if(new RegExp(mot,'i').test(txt)) return _echec('mot technique visible : '+mot);
        return true;
      } finally { currentUser=sv; }})());

    // ⚠ LE FLUX PAYPAL ET LA RENONCIATION NE SONT PAS TOUCHÉS. La case reste
    // obligatoire et décochée par défaut au moment du paiement réel : c'est
    // une contrainte explicite du lot, et elle se vérifie plutôt qu'elle ne
    // se suppose.
    ok('La renonciation au droit de rétractation est intacte',(()=>{
      const src=_prodSrc();
      const i=src.indexOf('id="sub-renonciation"');
      if(i<0) return _echec('la case de renonciation a disparu');
      const bal=src.slice(src.lastIndexOf('<input',i),src.indexOf('>',i));
      // ⚠ L'ATTRIBUT, PAS LE MOT. La balise porte
      // onchange="_majRenonciation(this.checked)" : un \bchecked\b y trouvait
      // « this.checked » et accusait de pré-cochage une case parfaitement
      // décochée. On cherche l'attribut autonome.
      if(/(^|\s)checked(\s|=|$)/.test(bal.replace(/this\.checked/g,'')))
        return _echec('la case de renonciation est pré-cochée');
      // Et rien du lot d'essai ne s'est branché sur le flux de paiement.
      for(const f of [_poserPromesseAthlete,_rendreEssai,ouvrirAbonnementDepuisEssai])
        if(/sub-waiver|paypal|PAYPAL/i.test(String(f)))
          return _echec('le lot d’essai touche au flux de paiement');
      return true;})());

    // ══ 15/09/2026 — LES TROIS CASES RESTENT SUR UNE LIGNE ═══════════════
    //
    // ⚠ `style.display=''` NE REMET PAS PAR DEFAUT : elle SUPPRIME la
    // declaration en ligne. #clh-stats porte `display:flex` dans son attribut
    // style — c'est lui qui met les trois cases cote a cote. _rendreReprise la
    // vidait pour « rendre » le bloc, et les faisait retomber en `block`, donc
    // EN COLONNE, pour tout le monde et a chaque rendu de l'accueil.
    //
    // C'est le MEME piege que showErr avec la couleur de #r-err, documente
    // dans ce fichier depuis des mois. Il a ete refait.
    ok('Les trois cases de l’accueil restent sur une ligne',(()=>{
      const z=document.getElementById('clh-stats');
      if(!z) return _echec('le bloc des trois cases n’existe plus');
      // ⚠ LA MISE EN PAGE EST DANS LA FEUILLE, PAS EN LIGNE. C'est TOUT le
      // correctif : un `display` en ligne sur un element qu'on masque est
      // efface par le premier `style.display=''` venu.
      if(/display\s*:/.test(z.getAttribute('style')||''))
        return _echec('#clh-stats a de nouveau un display en ligne : il sera effacé au premier masquage');
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      if(!/#clh-stats\{[^}]*display:flex/.test(css))
        return _echec('la regle #clh-stats{display:flex} n’existe pas dans la feuille');
      // ⚠ ET ON REJOUE LE MASQUAGE : masquer puis rendre doit retrouver flex.
      // Sans le correctif, ce retour donnait 'block'.
      const sv=z.style.display;
      try{
        z.style.display='none';
        if(getComputedStyle(z).display!=='none') return _echec('le masquage ne masque pas');
        z.style.display='';
        if(getComputedStyle(z).display!=='flex')
          return _echec('rendu apres masquage : '+getComputedStyle(z).display+' au lieu de flex');
      } finally { z.style.display=sv; }
      // Les trois cases sont TROIS, et chacune prend sa part.
      const b=z.querySelectorAll('.metric-box');
      if(b.length!==3) return _echec(b.length+' cases au lieu de trois');
      const m=css.match(/\.metric-box\{([\s\S]*?)\}/);
      if(!m||!/flex:1/.test(m[1]))
        return _echec('.metric-box ne partage plus la largeur');
      return true;})());

    // ══ 15/09/2026 — L'HISTORIQUE DES SEANCES ════════════════════════════
    ok('La carte d’entraînement porte ses trois actions',(()=>{
      const h=document.getElementById('clh-hero');
      if(!h) return _echec('la carte d’entraînement a disparu');
      const rouge=h.querySelector('.btn-red');
      if(!rouge) return _echec('le bouton principal a disparu');
      // ⚠ ON COMPARE LE TEXTE, PAS SA MISE EN LIGNES. Les trois libelles
      // portent une coupure ECRITE — un <br> — pour que les deux lignes
      // tombent au meme endroit a toutes les largeurs : textContent rend donc
      // « DÉMARRER MA SÉANCEDU JOUR », sans espace. On normalise plutot que
      // d'ecrire le <br> dans l'assertion, qui deviendrait un test de balisage.
      const _lib=e=>e.textContent.replace(/\s+/g,' ').trim();
      // LA COUPURE EST VOULUE, et sur les trois boutons.
      for(const b of [rouge,...h.querySelectorAll('.hero-duo .btn')]){
        if(b.innerHTML.indexOf('<br>')<0)
          return _echec('« '+_lib(b)+' » n’a plus sa coupure écrite');
        if(!b.classList.contains('btn-2l'))
          return _echec('« '+_lib(b)+' » n’a pas l’interligne des deux lignes');
      }
      const duo=h.querySelectorAll('.hero-duo .btn');
      if(duo.length!==2) return _echec(duo.length+' boutons secondaires au lieu de deux');
      // ⚠ ON LIT LES DEUX LIGNES, SEPAREMENT. Coller textContent donne
      // « GÉRER MESSÉANCES » — le <br> ne produit aucun caractere — et une
      // normalisation qui ecrase les espaces effaçait aussi celui de
      // « GÉRER MES ». Decouper sur le <br> dit ce qu'on veut vraiment :
      // deux lignes, et lesquelles.
      const _lignes=b=>b.innerHTML.split(/<br\s*\/?>/i)
        .map(x=>x.replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim());
      const t=[...duo].map(_lignes);
      if(t[0].join('|')!=='Gérer mes|séances')
        return _echec('premier bouton : '+t[0].join(' | '));
      if(t[1].join('|')!=='Historique des|séances')
        return _echec('second bouton : '+t[1].join(' | '));
      if(_lignes(rouge).join('|')!=='Démarrer ma séance|du jour')
        return _echec('bouton principal : '+_lignes(rouge).join(' | '));
      // ⚠ 11 px EST LE PLANCHER DE L'ACCUEIL, tenu par l'assertion « Aucun
      // texte de l'accueil athlete ne descend sous le plancher ». « Plus
      // petit » se gagne sur l'interlettrage, pas sur le corps.
      for(const b of duo){
        const cs=getComputedStyle(b);
        if(parseFloat(cs.fontSize)<11)
          return _echec('un bouton passe sous le plancher : '+cs.fontSize);
        if(/nowrap/.test(cs.whiteSpace))
          return _echec('white-space:nowrap écraserait la coupure écrite');
      }
      // ⚠ SUR UNE LIGNE, et c'est la demande. La regle suffit quand l'ecran
      // n'est pas monte ; quand il l'est, on mesure.
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.hero-duo\{([^}]*)\}/);
      if(!m||!/display:flex/.test(m[1])) return _echec('.hero-duo n’est pas une rangée');
      // flex:1 1 0 AVEC min-width:0 : sans le min-width, un libellé qui ne se
      // coupe pas impose sa largeur et déborde la carte.
      const mb=css.match(/\.hero-duo \.btn\{([^}]*)\}/);
      if(!mb||!/min-width:0/.test(mb[1]))
        return _echec('les boutons peuvent déborder : min-width:0 manque');
      if(/white-space:nowrap/.test(mb[1]))
        return _echec('nowrap est revenu : il pousserait les deux lignes sur une seule');
      const r=[...duo].map(b=>b.getBoundingClientRect());
      if(r[0].width&&r[1].width&&window.innerWidth>=390
         &&Math.abs(r[0].top-r[1].top)>2)
        return _echec('les deux boutons ne partagent pas la ligne');
      return true;})());

    // LA LISTE. Une ligne par séance, triée de la plus récente à la plus
    // ancienne, et RIEN n'y est recalculé : une séance porte déjà son nom, sa
    // date, sa durée et son volume. Un historique qui recalculerait finirait
    // par afficher d'autres chiffres que ceux montrés à la fin de la séance.
    ok('L’historique liste les séances, de la plus récente à la plus ancienne',(()=>{
      const u={sessions:[
        {id:'a',date:3000,name:'A',duration:40,volume:1000},
        {id:'b',date:1000,name:'B',duration:50,volume:2000},
        {id:'c',date:2000,name:'C',duration:60,volume:3000},
        {date:0},                       // sans date : écartée
        null]};
      const l=listeHistoriqueSeances(u);
      if(l.map(x=>x.id).join(',')!=='a,c,b')
        return _echec('ordre : '+l.map(x=>x.id).join(','));
      if(listeHistoriqueSeances({}).length) return _echec('un dossier vide rend des séances');
      // La ligne porte le nom, la date, et les deux chiffres qu'on cherche.
      const h=_htmlLigneHistorique({id:'a',date:Date.parse('2026-09-14T18:00:00'),
        name:'PUSH HAUT',duration:61,volume:4800,complete:true},Date.parse('2026-09-15T09:00:00'));
      // ⚠ LES ESPACES DES NOMBRES NE SONT PAS DES ESPACES. toLocaleString('fr-FR')
      // groupe les milliers avec une espace fine insécable (U+202F) — ou
      // insécable (U+00A0) selon la version d'ICU. Comparer à une espace
      // ordinaire faisait tomber ce test sur un affichage parfaitement correct.
      const _norm=x=>String(x).replace(/[\u202f\u00a0\s]+/g,' ');
      for(const bout of ['PUSH HAUT','Lundi 14 septembre','61 min','4 800 kg'])
        if(_norm(h).indexOf(bout)<0) return _echec('la ligne ne porte pas « '+bout+' »');
      if(h.indexOf('data-seance="a"')<0) return _echec('la ligne ne porte pas son identifiant');
      // ⚠ L'IDENTIFIANT PASSE PAR data-, JAMAIS PAR UN onclick CONSTRUIT. Un
      // nom de séance porte des apostrophes, et les concaténer dans du
      // JavaScript en ligne est la porte d'entrée qu'on ne veut pas.
      const x=_htmlLigneHistorique({id:"a'b",date:Date.now(),
        name:'<img src=x onerror=alert(1)>',duration:1,volume:1},Date.now());
      // ⚠ ON CHERCHE LA BALISE, PAS SON CONTENU. escapeHtml neutralise les
      // chevrons : « onerror=alert(1) » survit comme TEXTE, parfaitement
      // inoffensif, et un motif qui le cherche accuse un échappement correct.
      // Ce qui compte est qu'aucune balise ne s'ouvre.
      if(/<img/i.test(x)) return _echec('le nom n’est pas échappé : une balise s’ouvre');
      if(x.indexOf('&lt;img')<0) return _echec('le nom n’est pas passé par escapeHtml');
      if(/onclick="ouvrirSeanceHistorique\('/.test(x))
        return _echec('l’identifiant est concaténé dans un onclick');
      // UNE SÉANCE PARTIELLE SE SIGNALE, sans être punie : elle a eu lieu.
      if(_htmlLigneHistorique({id:'p',date:Date.now(),name:'P',complete:false},Date.now())
         .indexOf('partielle')<0) return _echec('une séance partielle ne se signale pas');
      // L'ANNÉE N'APPARAÎT QUE SI CE N'EST PAS L'ANNÉE EN COURS.
      const auj=Date.parse('2026-09-15T09:00:00');
      if(/2026/.test(_dateHistorique(Date.parse('2026-03-02T10:00:00'),auj)))
        return _echec('l’année en cours est affichée pour rien');
      if(!/2025/.test(_dateHistorique(Date.parse('2025-03-02T10:00:00'),auj)))
        return _echec('une séance d’une autre année ne porte pas son année');
      return true;})());

    // LES RECORDS D'UNE SÉANCE RELUE, calculés contre tout ce qui la précède.
    ok('Une séance relue retrouve ses records',(()=>{
      const st=(kg,n)=>({sets:Array.from({length:n},()=>({done:true,weight:kg,reps:8}))});
      const ant=[{date:1,data:{'DC':st(80,3)}},{date:2,data:{'DC':st(85,3)}}];
      const sc={date:3,data:{'DC':st(90,3),'DIPS':st(0,3)}};
      const r=recordsDeSeance(sc,ant);
      if(r.length!==1) return _echec(r.length+' records au lieu d’un');
      if(r[0].nm!=='DC'||r[0].histMax!==85||r[0].curMax!==90||r[0].gain!==5)
        return _echec(JSON.stringify(r[0]));
      // ⚠ UN EXERCICE JAMAIS FAIT AVANT N'EST PAS UN RECORD. C'est une
      // première, et l'annoncer comme un record les dévaluerait tous.
      if(recordsDeSeance({date:3,data:{'NOUVEAU':st(60,3)}},ant).length)
        return _echec('un premier passage compte comme un record');
      // Une charge égale n'en est pas un non plus.
      if(recordsDeSeance({date:3,data:{'DC':st(85,3)}},ant).length)
        return _echec('une charge égale compte comme un record');
      // Les séries non validées ne comptent pas.
      if(recordsDeSeance({date:3,data:{'DC':{sets:[{done:false,weight:200}]}}},ant).length)
        return _echec('une série non validée compte');
      return true;})());

    // ⚠ L'ÉCRAN DE RELECTURE NE DEMANDE RIEN. C'est le point délicat du lot :
    // rouvrir s-workout-done aurait rouvert ses curseurs de ressenti, son
    // sRPE, sa relance de bilan et son invitation aux notifications — donc
    // redemandé un ressenti déjà donné, et risqué de l'écrire sur la DERNIÈRE
    // séance.
    ok('La séance relue se lit, elle ne se ressaisit pas',(()=>{
      const d=document.getElementById('s-seance-detail');
      if(!d) return _echec('l’écran de relecture n’existe pas');
      if(d===document.getElementById('s-workout-done'))
        return _echec('la relecture réutilise l’écran de fin de séance');
      // AUCUN CHAMP DE SAISIE dans le gabarit de relecture.
      const champs=d.querySelectorAll('input,textarea,select');
      if(champs.length) return _echec(champs.length+' champ(s) de saisie sur un écran de relecture');
      // Et rien n'y écrit : ni saveUser, ni rcm, ni les fonctions de ressenti.
      for(const [n,f] of [['ouvrirSeanceHistorique',ouvrirSeanceHistorique],
                          ['_htmlRessentiRelu',_htmlRessentiRelu],
                          ['_htmlExercicesRelus',_htmlExercicesRelus],
                          ['loadHistoriqueSeances',loadHistoriqueSeances]])
        if(/saveUser\(|savePostSession|rcfReinitRessenti|rcfPoserRessenti/.test(String(f)))
          return _echec(n+' écrit ou réarme une saisie');
      // LE RESSENTI EST RELU, PAS REDEMANDÉ : des valeurs, et les libellés de
      // RCF_QUESTIONS — la même table que l'écran de fin.
      const h=_htmlRessentiRelu({metrics:{fatigue:7,sensation:8}});
      if(h.indexOf('/ 10')<0) return _echec('le ressenti relu n’est pas une valeur');
      if(/<input/.test(h)) return _echec('le ressenti relu pose un champ');
      const lib=(RCF_QUESTIONS.find(q=>q.id==='fatigue')||{}).lib;
      if(lib&&h.indexOf(escapeHtml(lib))<0)
        return _echec('les libellés ne viennent plus de RCF_QUESTIONS');
      // Une séance sans ressenti n'affiche pas un bloc vide.
      if(_htmlRessentiRelu({})!=='') return _echec('une séance sans ressenti rend un bloc');
      return true;})());

    // ⚠ LE VISUEL TÉLÉCHARGÉ EST CELUI DE LA SÉANCE OUVERTE, pas de la
    // dernière. Sans cela, relire une séance d'il y a trois semaines et
    // toucher « Télécharger » aurait rendu le visuel d'hier.
    ok('Le visuel téléchargé est celui de la séance relue',(()=>{
      const src=_prodSrc().replace(/\/\/[^\r\n]*/g,'');
      // La cible est un PARAMÈTRE, et le cas par défaut reste la dernière
      // séance : l'écran de fin ne change pas de comportement.
      if(!/function telechargerBilanSeance\(sc\)/.test(src))
        return _echec('telechargerBilanSeance ne prend pas la séance en paramètre');
      if(!/function partagerBilanSeance\(sc\)/.test(src))
        return _echec('partagerBilanSeance ne prend pas la séance en paramètre');
      if(String(_bilanDonneesDe).indexOf('_bilanSeanceCourante')<0)
        return _echec('sans argument, le comportement d’origine est perdu');
      // ET LES RECORDS SONT RECOMPTÉS pour cette séance-là : _bilanRecords est
      // le compte de la DERNIÈRE séance, et l'appliquer à une séance ancienne
      // lui prêterait des records qu'elle n'a pas faits.
      if(String(_bilanDonneesDe).indexOf('recordsDeSeance')<0)
        return _echec('les records du visuel ne sont pas recomptés pour la séance relue');
      if(String(telechargerSeanceRelue).indexOf('_seanceRelue')<0)
        return _echec('le téléchargement ne vise pas la séance ouverte');
      // Et le MÊME dessin que l'écran de fin : une seconde mise en page
      // aurait divergé au premier ajustement.
      if(String(_rendrePartageSeanceRelue).indexOf('_bilanDonneesDe')<0)
        return _echec('l’aperçu de relecture ne passe pas par la même source');
      return true;})());

    // ══ 16/09/2026 — L'ACHAT, ET LE NETTOYAGE DES FONDATIONS POSEES ═════
    //
    // ⚠ CE QUE LE PLAN SPARK NE PERMET PAS, et qu'il faut savoir avant que de
    // l'argent circule : sans fonction serveur, RIEN NE VERIFIE UN ACHAT COTE
    // SERVEUR. `programmesAchetes` est un champ du dossier, et les règles RTDB
    // accordent au titulaire l'écriture sans restriction de champ. C'est le
    // MÊME arbitrage, déjà assumé, que pour `status` côté abonnement — voir le
    // « point dur » du §4 de la note de décision économique. Ces assertions
    // vérifient donc ce qui EST vérifiable : que les verrous d'interface
    // tiennent, et qu'aucun chemin ne les contourne.

    const _achFix=(u,f)=>{
      const _cu=currentUser,_db=DB.get('users');
      try{ currentUser=u; DB.set('users',{[u.email]:u}); return f(); }
      finally{ currentUser=_cu; if(_db) DB.set('users',_db);
        try{ fermerAchatProgramme(true); }catch(e){} }
    };
    const _achU=o=>Object.assign({email:'ach@t.fr',id:'h1',role:'athlete',
      fname:'H',gender:'H',bilans:[]},o||{});

    ok('Un programme payant n\'est acquis qu\'une fois payé',(()=>_achFix(_achU(),()=>{
      const u=currentUser;
      if(RC_BOUTIQUE_GRATUITE) return _echec('la boutique est encore en accès libre');
      if(programmeAcquis(u,'fondations')) return _echec('acquis sans achat');
      // ⚠ PAS D'HERITAGE D'Object.prototype : la clé vient d'une donnée.
      u.programmesAchetes={};
      if(programmeAcquis(u,'toString')) return _echec('une clé héritée vaut achat');
      // Un programme à zéro euro est libre, et c'est voulu : Kevin pourra en
      // publier un gratuit sans inventer un second mécanisme.
      if(!programmeAcquis(u,'__zero')&&programmeDuCatalogue('__zero'))
        return _echec('un programme gratuit devrait être libre');
      u.programmesAchetes={fondations:{le:Date.now(),prixCts:1490,ordre:'X'}};
      if(!programmeAcquis(u,'fondations')) return _echec('l’achat n’est pas reconnu');
      // Un achat « faux » (valeur tombée à false) ne vaut pas acquis.
      u.programmesAchetes={fondations:false};
      return !programmeAcquis(u,'fondations')?true:_echec('un achat vide vaut acquis');})));

    // ⚠ LE DERNIER VERROU EST DANS appliquerProgramme, PAS DANS LE BOUTON. La
    // carte n'affiche « Appliquer » que sur un programme acquis, mais un appel
    // direct contournerait l'affichage — même discipline que la case de
    // renonciation, verrouillée deux fois elle aussi.
    ok('Appliquer un programme non payé n\'écrit rien et propose de l\'acheter',(()=>
      _achFix(_achU({sessions_config:_seancesViergesSemaine()}),()=>{
        appliquerProgramme('fondations');
        const sc=currentUser.sessions_config||[];
        if(sc.some(x=>x.active)) return _echec('des séances ont été écrites sans achat');
        const z=document.getElementById('rc-achat');
        if(!z||z.style.display!=='flex') return _echec('la feuille d’achat ne s’ouvre pas');
        // Et le verrou est bien dans la fonction, pas seulement dans la carte.
        if(String(appliquerProgramme).indexOf('programmeAcquis')<0)
          return _echec('appliquerProgramme ne vérifie pas l’acquisition');
        return true;})));

    // LA RENONCIATION AU DROIT DE RETRACTATION. Elle porte sur CE contenu-là :
    // une case cochée lors d'un achat précédent ne vaut pas pour celui-ci.
    ok('La case de renonciation est décochée à chaque ouverture, et verrouille deux fois',(()=>
      _achFix(_achU(),()=>{
        const c=document.getElementById('ach-cgv'), b=document.getElementById('ach-paypal');
        if(!c||!b) return _echec('la feuille d’achat n’existe pas');
        c.checked=true;                       // reste d'un achat précédent
        ouvrirAchatProgramme('fondations');
        if(c.checked) return _echec('la case survit d’un achat à l’autre');
        if(b.style.display!=='none') return _echec('PayPal s’affiche sans la case');
        c.checked=true; _majBoutonAchat();
        if(b.style.display==='none') return _echec('PayPal reste caché une fois coché');
        // ⚠ DEUXIEME VERROU : masquer ne suffit pas, un clic programmatique
        // contournerait l'affichage. createOrder refuse aussi.
        const f=String(_rendreBoutonAchat);
        if(f.indexOf('ach-cgv')<0||f.indexOf('c.checked')<0)
          return _echec('createOrder ne vérifie pas la case');
        // Et le texte dit ce qu'il doit dire.
        const t=document.querySelector('label[for="ach-cgv"]').textContent;
        for(const mot of ['rétractation','14 jours','conditions générales'])
          if(t.indexOf(mot)<0) return _echec('la mention ne dit pas « '+mot+' »');
        return true;})));

    // ⚠ LES DEUX SDK PAYPAL NE PEUVENT PAS PARTAGER LE MEME NOM. L'abonnement
    // charge `vault=true&intent=subscription`, l'achat `intent=capture` :
    // charger le second par-dessus écraserait l'un des deux selon l'ordre
    // d'arrivée, et le défaut ne se verrait que sur l'écran non testé.
    ok('L\'achat charge son propre SDK PayPal, sous son propre nom',(()=>{
      const f=String(_chargerPaypalAchat);
      if(f.indexOf('paypal-sdk-achat')<0) return _echec('le script n’a pas son propre identifiant');
      if(f.indexOf('data-namespace')<0||f.indexOf('paypalAchat')<0)
        return _echec('le SDK d’achat écraserait celui de l’abonnement');
      if(f.indexOf('intent=capture')<0) return _echec('l’achat n’est pas un paiement unique');
      if(/vault=true|intent=subscription/.test(f)) return _echec('l’achat charge un SDK d’abonnement');
      // Le SDK de l'abonnement, lui, n'a pas bougé.
      const a=String(initPaypalSubscription);
      if(a.indexOf('intent=subscription')<0) return _echec('le flux d’abonnement a été touché');
      // ⚠ LE MONTANT SE CONSTRUIT DEPUIS LES CENTIMES. Passer un flottant est
      // le chemin le plus court vers un ordre à 14.899999999999999.
      const r=String(_rendreBoutonAchat);
      if(r.indexOf('prixCts/100).toFixed(2)')<0)
        return _echec('le montant n’est pas construit depuis les centimes');
      return true;})());

    ok('Le coach seul peut appliquer un programme sans payer',(()=>{
      const h=_achFix(_achU(),()=>_htmlActionProgramme(programmeDuCatalogue('fondations')));
      if(/offrirProgramme/.test(h)) return _echec('un athlète voit le bouton du coach');
      if(h.indexOf('ouvrirAchatProgramme')<0) return _echec('un athlète ne peut pas acheter');
      const hk=_achFix(_achU({email:CREATOR_EMAIL,role:'coach'}),
        ()=>_htmlActionProgramme(programmeDuCatalogue('fondations')));
      if(!/offrirProgramme/.test(hk)) return _echec('le coach ne peut pas offrir son programme');
      // ⚠ ET LE GARDE EST DANS LA FONCTION, pas seulement dans l'affichage.
      const f=String(offrirProgramme);
      if(f.indexOf('CREATOR_EMAIL')<0) return _echec('offrirProgramme ne vérifie pas qui appelle');
      return true;})());

    // ══ LE NETTOYAGE DES FONDATIONS POSEES D'OFFICE ═════════════════════
    //
    // « Tous les gens connectés actuellement avec le programme débutant, clean
    // le programme et laisse le modèle vide. » — Kevin, 16/09/2026.
    //
    // ⚠ ON NE NETTOIE QUE CE QUE PERSONNE N'A TOUCHE. Effacer par erreur des
    // semaines de travail est le défaut que ce fichier documente à cinq
    // endroits. Les quatre cas de protection sont éprouvés un par un.
    ok('Le nettoyage efface une Fondation intacte, et RIEN d\'autre',(()=>{
      const _cu=currentUser,_db=DB.get('users');
      try{
        const poser=F=>F.map(x=>({...x,exercises:x.exercises.map(e=>({...e})),_essai:true}));
        const mettre=sc=>{ currentUser={email:'n@t.fr',id:'n1',role:'athlete',
          gender:'H',sessions_config:sc}; DB.set('users',{'n@t.fr':currentUser}); };
        // 1. LE CAS VISE : une Fondation posée d'office, jamais touchée.
        mettre(poser(FONDATION_H));
        if(!_nettoyerFondationPosee()) return _echec('une Fondation intacte n’est pas nettoyée');
        if(currentUser.sessions_config.some(x=>x.active))
          return _echec('des séances actives survivent au nettoyage');
        if(currentUser.sessions_config.length!==7)
          return _echec('la grille ne fait plus sept jours');
        // IDEMPOTENTE : la grille vidée, il n'y a plus rien à faire.
        if(_nettoyerFondationPosee()) return _echec('le nettoyage se rejoue sur une grille vide');
        // La version Femme aussi.
        mettre(poser(FONDATION_F));
        if(!_nettoyerFondationPosee()) return _echec('la Fondation Femme n’est pas nettoyée');
        // 2. MODIFIEE : un seul exercice renommé suffit à la protéger.
        const mod=poser(FONDATION_H); mod[0].exercises[0].name='MON EXERCICE À MOI';
        mettre(mod);
        if(_nettoyerFondationPosee()) return _echec('une Fondation modifiée a été effacée');
        // 3. UN PROGRAMME PERSO marqué _essai par accident reste intouché : le
        //    marqueur ne suffit pas, le CONTENU doit être celui d'une Fondation.
        const perso=_seancesViergesSemaine();
        perso[0]={...perso[0],active:true,name:'MON PROGRAMME',_essai:true,
          exercises:[{name:'SOULEVÉ DE TERRE',series:5,reps:'5'}]};
        mettre(perso);
        if(_nettoyerFondationPosee()) return _echec('un programme personnel a été effacé');
        // 4. SANS MARQUEUR : une Fondation publiée par un coach est protégée,
        //    parce que _marquerCommePublie retire _foundation à la publication.
        const pub=FONDATION_F.map(x=>({...x,exercises:x.exercises.map(e=>({...e}))}));
        pub.forEach(x=>{ delete x._foundation; delete x._essai; });
        mettre(pub);
        if(_nettoyerFondationPosee()) return _echec('une Fondation publiée a été effacée');
        // 5. Les entrées absurdes ne lèvent pas.
        for(const v of [null,undefined,[],'x',42])
          if(_estFondationPosee(v)) return _echec('une grille absurde est prise pour une Fondation');
        return true;
      } finally { currentUser=_cu; if(_db) DB.set('users',_db); }})());

    // ⚠ ET LE GESTE EST REVERSIBLE. Un nettoyage qu'on ne peut pas défaire
    // serait exactement la perte silencieuse que ce fichier combat.
    ok('Le nettoyage laisse la grille d\'avant dans l\'historique',(()=>{
      const f=String(_nettoyerFondationPosee);
      if(f.indexOf('_pushSessionsHistory')<0)
        return _echec('rien ne permet de revenir en arrière');
      // Et la fonction de pose automatique a bien DISPARU : c'était le
      // troisième chemin, et il avait survécu au lot qui a fermé les deux
      // autres parce qu'il ne cite pas FONDATION — il appelait
      // initSessionsConfig.
      const src=_prodSrc();
      if(src.indexOf('_migrateFoundationIfNeeded(')>=0)
        return _echec('l’ancienne pose automatique est encore appelée');
      if(f.indexOf('initSessionsConfig')>=0)
        return _echec('le nettoyage repasse par la fabrique de grilles');
      return true;})());

    // ══ 16/09/2026 — METTRE SES PROGRAMMES EN VENTE, ET FIXER LES PRIX ══
    //
    // ⚠ LE PRIX NE PEUT PAS VIVRE DANS LE CODE. L'athlète doit voir celui que
    // le coach a posé, et un prix dans le code demanderait un déploiement pour
    // changer. D'où un nœud PUBLIC : tout compte connecté le lit, le créateur
    // seul l'écrit — et c'est la règle RTDB qui le tient, pas l'interface.

    ok('Le prix se saisit en euros et se range en centimes, ou se refuse',(()=>{
      const cas=[['14,90',1490],['14.90',1490],['9',900],['0',0],['  12,5 ',1250],
        ['4999,99',499999],
        // ⚠ LE SIGNE SE REFUSE AVANT LE NETTOYAGE, PAS APRES. « tout ce qui
        // n'est pas un chiffre » transformait « -3 » en « 3 » : un prix négatif
        // devenait positif, en silence. Trouvé par cette assertion.
        ['-3',null],['- 12',null],
        ['',null],['abc',null],['9999',null],[null,null],[undefined,null],
        ['12,3,4',null]];
      for(const [t,att] of cas){
        const v=prixEnCentimes(t);
        if(v!==att) return _echec(JSON.stringify(t)+' → '+v+' au lieu de '+att);
      }
      // ⚠ TOUJOURS UN ENTIER : la regle RTDB refuse un flottant, et 12,345 €
      // n'existe pas.
      for(const t of ['12,345','0,019','1,005']){
        const v=prixEnCentimes(t);
        if(v!==null&&!Number.isInteger(v)) return _echec(t+' → '+v+' n’est pas un entier');
      }
      return true;})());

    ok('L\'identifiant d\'un programme est stable et sans accent',(()=>{
      // Une clef de base ne se renomme pas : elle doit survivre aux accents,
      // aux espaces et a la ponctuation du nom qui l'a produite.
      const cas=[['Prise de Masse — Élite #2','prise-de-masse-elite-2'],
        ['Fondations','fondations'],['   ---  ',''],['Été 2026','ete-2026']];
      for(const [n,att] of cas){
        const v=_slugProgramme(n);
        if(v!==att) return _echec(JSON.stringify(n)+' → « '+v+' » au lieu de « '+att+' »');
      }
      if(_slugProgramme('a'.repeat(200)).length>50) return _echec('l’identifiant n’est pas borné');
      return true;})());

    // ⚠ LE PUBLIE RECOUVRE LE CODE CHAMP PAR CHAMP, ET JAMAIS EN BLOC. Un
    // Object.assign écraserait `seances` — une FONCTION dans le catalogue, une
    // chaîne JSON dans la base — et le programme livré avec l'application
    // cesserait d'avoir des séances au premier changement de prix.
    ok('Changer un prix ne fait pas perdre le reste du programme',(()=>{
      const _av=_boutiqueLocale();
      try{
        _poserBoutiqueLocale({});
        const base=programmeDuCatalogue('fondations');
        if(!base) return _echec('le programme livré a disparu');
        const nH=(base.seances('H')||[]).length;
        if(nH!==7) return _echec('le programme livré n’a pas ses séances : '+nH);
        // On ne publie QU'UN PRIX.
        _poserBoutiqueLocale({fondations:{prixCts:2490,maj:Date.now()}});
        const maj=programmeDuCatalogue('fondations');
        if(maj.prixCts!==2490) return _echec('le prix publié n’est pas repris : '+maj.prixCts);
        if(prixProgramme(maj)!=='24,90 €') return _echec('affichage : '+prixProgramme(maj));
        if(maj.nom!==base.nom) return _echec('le nom a été perdu : « '+maj.nom+' »');
        if(maj.description!==base.description) return _echec('la description a été perdue');
        if((maj.seances('H')||[]).length!==7)
          return _echec('LES SÉANCES ONT ÉTÉ PERDUES : '+(maj.seances('H')||[]).length);
        if((maj.seances('F')||[]).length!==7) return _echec('la version Femme a été perdue');
        return true;
      } finally { _poserBoutiqueLocale(_av); }})());

    ok('Un programme publié s\'ajoute à la boutique, et se retire sans disparaître',(()=>{
      const _av=_boutiqueLocale();
      try{
        _poserBoutiqueLocale({'mon-prog':{nom:'Mon prog',prixCts:1990,description:'D',
          seances:JSON.stringify({H:[{day:'Lundi',name:'A',active:true,
            exercises:[{name:'SQUAT',series:3,reps:'10'}]}],F:[]}),maj:1}});
        const p=programmeDuCatalogue('mon-prog');
        if(!p) return _echec('le programme publié est introuvable');
        if(p.prixCts!==1990) return _echec('prix : '+p.prixCts);
        const H=p.seances('H')||[];
        if(H.length!==1||(H[0].exercises||[])[0].name!=='SQUAT')
          return _echec('les séances publiées ne sont pas relues');
        // Sans jeu Femme publié, on retombe sur celui qui existe : mieux vaut
        // le programme de l'autre genre que pas de programme du tout.
        if(!(p.seances('F')||[]).length) return _echec('aucune séance pour la version Femme');
        if(!programmesBoutique().some(x=>x.id==='mon-prog'))
          return _echec('le programme publié n’apparaît pas dans la liste');
        // ⚠ RETIRE DE LA VENTE N'EST PAS SUPPRIME. Un programme deja achete
        // doit rester lisible par ceux qui l'ont paye.
        _poserBoutiqueLocale({'mon-prog':{nom:'Mon prog',prixCts:1990,masque:true,maj:1}});
        if(programmesBoutique().some(x=>x.id==='mon-prog'))
          return _echec('un programme retiré reste en vitrine');
        if(!programmeDuCatalogue('mon-prog'))
          return _echec('un programme retiré devient illisible pour qui l’a acheté');
        // Un programme publié sans nom n'entre pas en vitrine : une carte sans
        // titre ne se vend pas, elle inquiète.
        _poserBoutiqueLocale({'x':{prixCts:100,maj:1}});
        if(programmesBoutique().some(x=>x.id==='x'))
          return _echec('un programme sans nom entre en vitrine');
        // Et le prototype ne devient pas un programme.
        _poserBoutiqueLocale({});
        if(programmeDuCatalogue('toString')) return _echec('une clé héritée rend un programme');
        return true;
      } finally { _poserBoutiqueLocale(_av); }})());

    // ⚠⚠ L'ADRESSE DU VENDEUR EST ECRITE DEUX FOIS — dans app/index.html et
    // dans database.rules.json — ET LA VERIFICATION N'EST PAS ICI.
    //
    // Elle y a ete ecrite, en `async`, et c'est le piege que ce fichier
    // documente depuis des mois : `ok` ne regarde que la veracite de son
    // second argument, et UNE PROMESSE EST TOUJOURS VRAIE. L'assertion serait
    // passee au vert quoi qu'il arrive.
    //
    // Et meme synchrone elle ne vaudrait rien : database.rules.json n'est PAS
    // deploye — voir l'assemblage de _site — donc un fetch depuis la page ne
    // trouve rien et conclut « tout va bien ». C'est exactement ainsi qu'un
    // champ 'logo' est reste casse pendant que la suite etait verte.
    //
    // Le controle vit donc dans scripts/verif/regles.mjs, qui lit LES DEUX
    // FICHIERS SUR LE DISQUE. Il n'y a rien a servir, et rien qui puisse etre
    // muet.
    ok('Seul le créateur voit — et tient — la mise en vente',(()=>{
      const _cu=currentUser;
      try{
        currentUser={email:'x@t.fr',id:'x1',role:'coach',fname:'X'};
        if(estVendeur()) return _echec('un autre coach est vendeur');
        _rendreEntreeVente();
        if(/ouvrirMesProgrammes/.test(document.getElementById('bq-vendeur').innerHTML))
          return _echec('un autre coach voit l’entrée de mise en vente');
        // ⚠ ET LE GARDE EST DANS LES FONCTIONS, pas seulement dans l'affichage.
        for(const f of [ouvrirMesProgrammes,ouvrirFicheVente])
          if(String(f).indexOf('estVendeur')<0)
            return _echec('une porte de mise en vente ne vérifie pas qui appelle');
        if(String(enregistrerFicheVente).indexOf('estVendeur')<0)
          return _echec('la publication ne vérifie pas qui appelle');
        if(ouvrirMesProgrammes()!==false) return _echec('un autre coach ouvre l’écran');
        currentUser={email:CREATOR_EMAIL,id:'k1',role:'coach',fname:'K'};
        if(!estVendeur()) return _echec('le créateur n’est pas vendeur');
        _rendreEntreeVente();
        return /ouvrirMesProgrammes/.test(document.getElementById('bq-vendeur').innerHTML)
          ?true:_echec('le créateur ne voit pas l’entrée');
      } finally { currentUser=_cu;
        try{ _rendreEntreeVente(); }catch(e){} }})());

    // L'IMAGE PART DANS UN NŒUD PUBLIC que chaque athlète relit à chaque
    // ouverture de la boutique. Non réduite, elle y coûterait des mégaoctets
    // par lecture — et le plan Spark compte les octets descendus.
    ok('La devanture est réduite avant d\'être publiée, et bornée',(()=>{
      const f=String(_venteChoisirImage);
      if(f.indexOf('_resizeImage')<0) return _echec('l’image n’est pas redimensionnée');
      const g=String(enregistrerFicheVente);
      if(g.indexOf('420000')<0) return _echec('aucune borne sur le poids de l’image');
      if(g.indexOf('240000')<0) return _echec('aucune borne sur le poids du programme');
      // Les mêmes bornes que la règle de la base : une borne côté client qui
      // laisserait passer ce que le serveur refuse donnerait un échec muet.
      return true;})());

    // ══ 16/09/2026 — LA BOUTIQUE DE PROGRAMMES ══════════════════════════
    //
    // Les séances naissent vierges ; il faut donc une porte pour ceux qui ne
    // savent pas par où commencer. La Fondation cesse d'être un défaut imposé
    // et devient un programme qu'on CHOISIT.
    //
    // ⚠ UN SEUL VENDEUR, ET CE N'EST PAS UNE LIMITATION D'INTERFACE. Encaisser
    // l'argent d'un client pour le reverser à un autre coach ferait de RepCore
    // un intermédiaire de paiement au sens de la DSP2 — agrément obligatoire,
    // et c'est la troisième voie explicitement écartée au §2 de la note de
    // décision économique. Ici l'argent encaissé appartient déjà à celui qui
    // encaisse. Arbitré par Kevin le 16/09/2026.

    ok('Le catalogue de la boutique est gelé, et chaque programme est complet',(()=>{
      if(!Array.isArray(RC_PROGRAMMES)) return _echec('RC_PROGRAMMES n’est pas une liste');
      if(!Object.isFrozen(RC_PROGRAMMES)) return _echec('le catalogue n’est pas gelé');
      if(!RC_PROGRAMMES.length) return _echec('le catalogue est vide');
      const vus=new Set();
      for(const p of RC_PROGRAMMES){
        if(!Object.isFrozen(p)) return _echec(p.id+' : l’entrée n’est pas gelée');
        if(vus.has(p.id)) return _echec('deux programmes portent l’id « '+p.id+' »');
        vus.add(p.id);
        // ⚠ LES EMPLACEMENTS A COMPLETER (lot 8) SONT DES ENTREES VIDES, ET
        //   C'EST LEUR RAISON D'ETRE : quatre programmes attendent leur
        //   contenu de la main de Kevin. Ce qui doit tenir, c'est qu'AUCUN
        //   d'eux ne se vende tant qu'il est vide — le reste des exigences
        //   ci-dessous ne s'applique qu'a ce qui est en rayon.
        if(p.aCompleter){
          if(!p.id||!p.nom) return _echec('un emplacement sans id ni nom');
          if(programmeVendable(p)) return _echec(p.id+' : un emplacement vide est vendable');
          if(programmesBoutique().some(x=>x.id===p.id))
            return _echec(p.id+' : un emplacement vide est en boutique');
          continue;
        }
        for(const k of ['id','nom','description']) if(!p[k]) return _echec('un programme sans '+k);
        // ⚠ LE PRIX EST EN CENTIMES, ENTIER. Aucun flottant ne touche à de
        // l'argent : 0,1 + 0,2 ne vaut pas 0,3 en binaire, et un prix qui
        // dérive d'un centime est un prix faux.
        if(!Number.isInteger(p.prixCts)||p.prixCts<0)
          return _echec(p.id+' : prix « '+p.prixCts+' » — il se compte en centimes entiers');
        if(typeof p.seances!=='function') return _echec(p.id+' : pas de séances');
        for(const g of ['H','F']){
          const l=p.seances(g);
          if(!Array.isArray(l)||l.length!==7)
            return _echec(p.id+'/'+g+' : '+(l&&l.length)+' jours au lieu de 7');
          if(!l.some(x=>x&&x.active&&(x.exercises||[]).length))
            return _echec(p.id+'/'+g+' : aucune séance garnie');
        }
      }
      // Le prix de Fondations, tel qu'arbitré.
      const f=programmeDuCatalogue('fondations');
      if(!f) return _echec('« fondations » a disparu du catalogue');
      if(f.prixCts!==1490) return _echec('prix de Fondations : '+f.prixCts+' centimes');
      // ⚠ L'ESPACE AVANT L'EURO EST INSECABLE (U+00A0), comme partout dans le
      // fichier : « 14,90 » et « € » ne se séparent pas en fin de ligne.
      const aff=prixProgramme(f);
      if(aff!=='14,90 €') return _echec('affichage : '+JSON.stringify(aff));
      if(aff.indexOf(' ')>=0) return _echec('l’espace avant l’euro est sécable');
      // Une clé inconnue, ou héritée, ne rend rien.
      for(const k of ['nope','toString','',null,undefined])
        if(programmeDuCatalogue(k)!==null) return _echec('clé '+JSON.stringify(k)+' rend un programme');
      return true;})());

    // ⚠ LES SEANCES SONT LUES, PAS RECOPIEES. Deux jeux de sept jours copiés
    // dans le catalogue auraient divergé de FONDATION_H/F au premier
    // ajustement, et c'est la version non relue qui serait restée fausse.
    ok('Le catalogue lit les Fondations, il n\'en garde pas une copie',(()=>{
      const f=programmeDuCatalogue('fondations');
      if(f.seances('H')!==FONDATION_H) return _echec('la version Homme est une copie');
      if(f.seances('F')!==FONDATION_F) return _echec('la version Femme est une copie');
      // Tout ce qui n'est pas 'F' est Homme : le champ genre a des conventions
      // historiques, et c'est _genreProgramme qui les absorbe en amont.
      if(f.seances('H')!==f.seances('')) return _echec('un genre vide ne retombe pas sur Homme');
      return true;})());

    // ⚠ CETTE ASSERTION LAISSAIT LA FEUILLE D'ACHAT OUVERTE, et c'est une
    // assertion VOISINE qui est tombée : celle d'Échap sur le lexique. Depuis
    // que appliquerProgramme propose l'achat au lieu d'appliquer, l'appel
    // ouvrait « rc-achat » et personne ne le refermait — Échap fermait donc la
    // feuille d'achat restée là, et le lexique ne bougeait pas.
    // UN TEST QUI OUVRE UN CALQUE LE REFERME. Toujours, et dans un finally.
    ok('Appliquer un programme le COPIE, et ne touche jamais au catalogue',(()=>{
      const _u=currentUser,_db=DB.get('users');
      try{
        currentUser={email:'bq@t.fr',id:'b1',role:'athlete',fname:'B',gender:'H',
          sessions_config:_seancesViergesSemaine(),
          // Acquis : sinon on mesure le verrou d'achat, pas la copie.
          programmesAchetes:{fondations:{le:Date.now(),prixCts:1490,ordre:'T'}}};
        DB.set('users',{'bq@t.fr':currentUser});
        const pr=appliquerProgramme('fondations');
        if(!pr||typeof pr.then!=='function') return _echec('appliquerProgramme ne rend pas de promesse');
        // L'écriture est SYNCHRONE quand la grille est vide : aucune question
        // n'est posée, donc rien n'attend.
        const sc=currentUser.sessions_config||[];
        if(!sc.some(x=>x.active&&(x.exercises||[]).length))
          return _echec('le programme n’a pas été appliqué');
        // ⚠ COPIE PROFONDE. Le fichier a déjà eu ce bug deux fois : sans
        // clone, le premier exercice modifié par l'athlète modifie le
        // catalogue pour tout le monde jusqu'au rechargement.
        const av=FONDATION_H[0].exercises[0].name;
        if(!av) return _echec('la Fondation Homme est vide : le test ne prouve rien');
        sc.filter(x=>x.active)[0].exercises[0].name='ÉCRASÉ PAR LE TEST';
        if(FONDATION_H[0].exercises[0].name!==av)
          return _echec('la constante a été modifiée : la copie est de surface');
        // Les marqueurs d'exemple tombent : quelqu'un l'a choisi.
        if(sc.some(x=>x._essai||x._foundation))
          return _echec('le programme appliqué est encore marqué « exemple »');
        return true;
      } finally { currentUser=_u; if(_db) DB.set('users',_db);
        try{ fermerAchatProgramme(true); }catch(e){} }})());

    // LE LIEN DE CONTACT. wa.me attend le numéro au format international SANS
    // le « + » ; un « + » ou un espace casse le lien silencieusement — il
    // s'ouvre, et WhatsApp affiche « numéro invalide ».
    ok('Le lien WhatsApp est valide, et disparaît sans numéro',(()=>{
      const l=lienWhatsApp('coucou');
      if(RC_WHATSAPP){
        if(!/^https:\/\/wa\.me\/\d{8,15}\?text=/.test(l))
          return _echec('lien : '+l);
        if(/[+\s]/.test(RC_WHATSAPP))
          return _echec('le numéro porte un + ou un espace : wa.me le refusera');
        // Le texte est ENCODE : un message avec une esperluette couperait
        // l'URL en deux paramètres.
        if(lienWhatsApp('a&b=c').indexOf('a%26b%3Dc')<0)
          return _echec('le message n’est pas encodé');
      }
      // ⚠ PAS DE NUMERO, PAS DE LIEN — et pas de bouton non plus. Un bouton de
      // contact qui n'ouvre rien fait croire qu'on a écrit.
      const src=_prodSrc();
      if(src.indexOf('function lienWhatsApp')<0) return _echec('lienWhatsApp a disparu');
      const i=src.indexOf('function _rendreBoutique');
      // ⚠ ON COMPARE SANS LES ESPACES. Le ternaire est écrit sur trois lignes
      // — `c.innerHTML=lien` puis `?'<div...'` puis `:'';` — et chercher
      // « lien? » d'un bloc échouait sur un code parfaitement correct.
      const corps=(i<0?'':src.slice(i,i+1800)).replace(/\s+/g,'');
      if(corps.indexOf('lienWhatsApp(')<0)
        return _echec('_rendreBoutique ne construit aucun lien');
      if(corps.indexOf("c.innerHTML=lien?")<0||corps.indexOf(":'';")<0)
        return _echec('le bouton de contact ne dépend pas de la présence du lien');
      return true;})());

    ok('La boutique rend une carte par programme, et rien d\'inventé',(()=>{
      const h=_htmlCarteProgramme(programmeDuCatalogue('fondations'));
      if(!h) return _echec('aucune carte rendue');
      for(const t of ['bq-carte','bq-dev','bq-prix'])
        if(h.indexOf(t)<0) return _echec('la carte ne porte pas « '+t+' »');
      // ⚠ LE BOUTON DEPEND DESORMAIS DE L'ACQUISITION : « Acheter » tant que
      // le programme n'est pas paye, « Appliquer » ensuite. L'assertion
      // mesurait le contrat d'avant le paiement ; elle exige maintenant qu'il
      // y ait UNE action, et une seule.
      const act=(h.indexOf('ouvrirAchatProgramme')>=0?1:0)
        +(h.indexOf('appliquerProgramme')>=0?1:0);
      if(act!==1) return _echec(act+' action(s) sur la carte : '
        +(h.match(/onclick="[^"]*"/g)||[]).join(' | '));
      // ⚠ LA DEVANTURE SE RETIRE ELLE-MEME SI LE FICHIER MANQUE. L'affiche de
      // Fondations est dans le dépôt, mais elle manque hors ligne avant toute
      // première vue, et un programme publié peut pointer vers une image
      // morte. Une devanture cassée abîme plus la page que son absence, et le
      // dessin CSS est DESSOUS, prêt à apparaître.
      if(h.indexOf('onerror="this.remove()"')<0)
        return _echec('une image de devanture absente laisserait un cadre cassé');
      if(h.indexOf('bq-dev-fond')<0) return _echec('pas de devanture de repli');
      // Un programme sans image ne rend pas de balise <img> vide.
      const sans=_htmlCarteProgramme({id:'x',nom:'X',description:'d',prixCts:100});
      if(/<img/.test(sans)) return _echec('un programme sans image rend une <img>');
      // ⚠ TANT QUE LE PAIEMENT N'EST PAS BRANCHE, LA CARTE LE DIT. Afficher
      // « 14,90 € » au-dessus d'un bouton qui donne le programme serait
      // mensonger — et ce n'est pas une question d'interface, c'est une
      // annonce de prix à un consommateur.
      if(RC_BOUTIQUE_GRATUITE){
        if(h.indexOf('bq-note')<0)
          return _echec('le prix est affiché sans dire que rien n’est facturé');
        if(!/libre d.acc/.test(h)) return _echec('la note ne dit pas ce qu’il en est');
      }
      // Rien n'est rendu pour rien.
      if(_htmlCarteProgramme(null)!==''||_htmlCarteProgramme(undefined)!=='')
        return _echec('une entrée nulle rend du balisage');
      // ⚠ TOUT PASSE PAR escapeHtml : un jour un programme viendra d'ailleurs
      // que d'une constante gelée — Kevin veut mettre les siens en vente.
      // ⚠ L'ECHAPPEMENT DE L'IDENTIFIANT A DEMENAGE avec le bouton : il vit
      // dans _htmlActionProgramme, qui construit l'action. On vérifie donc
      // chaque champ LA OU IL EST ECRIT — une assertion qui suit la structure
      // plutôt qu'une fonction nommée survit au prochain découpage.
      const f=String(_htmlCarteProgramme);
      for(const ch of ['p.accroche','p.description','p.nom'])
        if(f.indexOf('escapeHtml('+ch+')')<0&&f.indexOf('escapeHtml(p.nom||\'\')')<0)
          return _echec(ch+' n’est pas échappé dans la carte');
      const g=String(_htmlActionProgramme);
      if(g.indexOf('escapeHtml(p.id)')<0) return _echec('p.id n’est pas échappé dans l’action');
      // Et l'identifiant est bien celui qui part dans le onclick.
      if(h.indexOf("('fondations')")<0) return _echec('l’action ne porte pas l’identifiant');
      return true;})());

    // L'AFFICHE DE FONDATIONS, ENTIERE. Elle est au format A4 et porte son
    // texte jusqu'aux bords : le cadre 3/4 plafonné à 360 px coupait le bandeau
    // du haut et la signature du bas. On la charge pour de vrai, dans une carte
    // à la largeur d'un téléphone, et on mesure.
    okA('L’affiche de Fondations est livrée, légère, et la carte la montre entière',async()=>{
      const p=RC_PROGRAMMES.find(x=>x.id==='fondations');
      if(!p||p.image!=='./img/programmes/fondations.jpg') return _echec('chemin : '+(p&&p.image));
      const r=await fetch(p.image,{cache:'no-store'});
      if(!r.ok) return _echec('le fichier n’est pas servi ('+r.status+')');
      const octets=(await r.arrayBuffer()).byteLength;
      if(octets>300000) return _echec(Math.round(octets/1000)+' ko : l’affiche n’a pas été réduite');
      const hote=document.createElement('div');
      hote.style.cssText='position:fixed;left:-10000px;top:0;width:333px';
      try{
        document.body.appendChild(hote);
        // Sans image : le cadre dessiné garde son 3/4 plafonné.
        hote.innerHTML=_htmlCarteProgramme({id:'x',nom:'X',description:'d',prixCts:100});
        const nu=hote.querySelector('.bq-dev');
        const plafond=parseFloat(getComputedStyle(nu).maxHeight);
        const cadre=Math.min(Math.round(nu.clientWidth*4/3),plafond);
        if(!(plafond>0)||Math.abs(nu.clientHeight-cadre)>1) return _echec('cadre sans image : '+nu.clientWidth+'×'+nu.clientHeight+', plafond '+plafond);
        // Avec l'affiche : c'est elle qui donne la hauteur.
        hote.innerHTML=_htmlCarteProgramme(p);
        const dev=hote.querySelector('.bq-dev'), img=hote.querySelector('.bq-dev-img');
        if(!img) return _echec('la carte ne rend pas l’affiche');
        img.loading='eager';
        await new Promise(ok=>{ if(img.complete&&img.naturalWidth) ok();
          else{ img.addEventListener('load',ok); img.addEventListener('error',ok); setTimeout(ok,4000); } });
        if(!img.isConnected||!img.naturalWidth) return _echec('l’affiche ne se charge pas');
        if(img.naturalWidth<900) return _echec(img.naturalWidth+' px de large : floue sur un écran dense');
        // La LARGEUR RÉELLE du cadre, pas celle de l'hôte : la bordure de la
        // carte en retire deux pixels.
        const b=dev.getBoundingClientRect(), bi=img.getBoundingClientRect();
        const attendu=b.width*img.naturalHeight/img.naturalWidth;
        if(Math.abs(b.height-attendu)>1) return _echec('cadre de '+b.height.toFixed(1)+' px pour une affiche de '+attendu.toFixed(1)+' px : elle est recadrée');
        if(Math.abs(bi.height-b.height)>1||Math.abs(bi.width-b.width)>1) return _echec('l’image ne remplit pas le cadre ('+bi.width.toFixed(1)+'×'+bi.height.toFixed(1)+' / '+b.width.toFixed(1)+'×'+b.height.toFixed(1)+')');
        return true;
      } finally { hote.remove(); }
    });

    // LA PORTE. Une boutique qu'on n'atteint pas ne vend rien — et elle est
    // posée là où la question se pose : devant sept jours vides.
    ok('La boutique s\'ouvre depuis l\'écran des séances',(()=>{
      const src=_prodSrc();
      if(src.indexOf('onclick="ouvrirBoutique()"')<0)
        return _echec('aucun bouton n’ouvre la boutique');
      if(!document.getElementById('s-boutique')) return _echec('l’écran n’existe pas');
      // R13 — btq-liste : bq-liste appartient à la banque d'exercices du coach.
      if(!document.getElementById('btq-liste')) return _echec('la liste n’existe pas');
      const i=src.indexOf('id="s-session-manager"');
      const j=src.indexOf('onclick="ouvrirBoutique()"');
      if(i<0||j<0||Math.abs(j-i)>2000)
        return _echec('le bouton n’est pas sur l’écran des séances');
      return true;})());

    // ══ 16/09/2026 — TOUT NAIT VIERGE ═══════════════════════════════════
    //
    // « Il faut que toutes les séances soient vierges, que ce soit pour
    // l'athlète ou pour le coach. Comme si je voulais installer une nouvelle
    // séance. Donc tu mets cinq exos à chaque fois [...] Tu laisses juste
    // rempli deux minutes de repos [...] tu peux pré-remplir en mettant trois
    // séries. » — Kevin, 16/09/2026.
    //
    // ⚠ LA DISTINCTION QUI PORTE TOUT LE LOT : on pré-remplit de la FORME, pas
    // du CONTENU. Cinq emplacements, trois séries, deux minutes — des réglages
    // qu'on ajuste. Aucun nom d'exercice, aucune consigne — un programme, ça,
    // se désapprouve.

    ok('Un emplacement d\'exercice naît vide, à trois séries et deux minutes',(()=>{
      const e=_exoVierge();
      if(e.name!=='') return _echec('l’emplacement porte un nom : « '+e.name+' »');
      if(e.series!==3) return _echec('séries : '+e.series);
      if(e.repos!==REPOS_DEFAUT) return _echec('repos : '+e.repos);
      if(REPOS_DEFAUT!=='2 min') return _echec('le repos par défaut a changé : '+REPOS_DEFAUT);
      // Rien d'autre n'est décidé à sa place.
      for(const k of ['description','videoUrl','methodeSeries','rir'])
        if(e[k]!=='') return _echec(k+' est pré-rempli : « '+e[k]+' »');
      // ⚠ EXACTEMENT LA FORME QUE POUSSE addExercise. Deux définitions
      // auraient divergé au premier champ ajouté à l'une des deux, et
      // l'éditeur aurait lu un champ absent sur les exercices créés par
      // l'autre chemin.
      const f=String(addExercise);
      for(const k of Object.keys(e))
        if(f.indexOf(k+':')<0) return _echec('addExercise ne pose pas '+k);
      // Et chaque appel rend un objet NEUF : un littéral partagé ferait que
      // modifier la 3e série d'un exercice les modifierait tous les cinq.
      const a=_exoVierge(), b=_exoVierge();
      if(a===b) return _echec('le même objet est rendu deux fois');
      a.series=4;
      return b.series===3?true:_echec('les emplacements partagent leur état');})());

    ok('Allumer un jour crée cinq emplacements, et jamais plus',(()=>{
      const s0={day:'Lundi',name:'',exercises:[],active:false};
      _garnirSeanceVierge(s0);
      if(s0.exercises.length!==SEANCE_EXOS_DEFAUT)
        return _echec(s0.exercises.length+' emplacements au lieu de '+SEANCE_EXOS_DEFAUT);
      if(SEANCE_EXOS_DEFAUT!==5) return _echec('le défaut n’est plus cinq : '+SEANCE_EXOS_DEFAUT);
      if(s0.exercises.some(e=>e.name!==''||e.series!==3||e.repos!==REPOS_DEFAUT))
        return _echec('un emplacement n’est pas vierge');
      // ⚠ ON NE GARNIT QUE CE QUI EST VIDE. Éteindre puis rallumer un jour par
      // erreur ajouterait cinq emplacements par-dessus le travail existant —
      // et ce serait la perte silencieuse que ce fichier documente partout.
      _garnirSeanceVierge(s0);
      if(s0.exercises.length!==5) return _echec('rallumer a ajouté : '+s0.exercises.length);
      const travail={day:'Mardi',exercises:[{name:'SQUAT',series:4,reps:'8'}],active:false};
      _garnirSeanceVierge(travail);
      if(travail.exercises.length!==1||travail.exercises[0].name!=='SQUAT')
        return _echec('le travail existant a été garni par-dessus');
      // Et les cinq emplacements sont indépendants.
      const s1={exercises:[]}; _garnirSeanceVierge(s1);
      s1.exercises[0].series=5;
      if(s1.exercises[1].series!==3) return _echec('les cinq emplacements sont le même objet');
      // Les entrées absurdes ne lèvent pas.
      for(const v of [null,undefined,'x',42]) _garnirSeanceVierge(v);
      return true;})());

    // LES TROIS INTERRUPTEURS DE JOUR passent par la MÊME fonction. Trois
    // recopies auraient divergé, et c'est le genre de divergence qu'on ne voit
    // qu'en production, sur un seul des trois écrans.
    ok('Les trois écrans qui allument un jour le garnissent de la même façon',(()=>{
      const src=_prodSrc();
      // ⚠ ON DECOUPE A L'INDEX, ON NE CONSTRUIT PAS DE RegExp. Le motif
      // traverse deux littéraux imbriqués, et chaque couche mange une moitié
      // des contre-obliques : la recherche échouait sur une fonction
      // parfaitement présente.
      const corpsDe=(nom,n)=>{ const i=src.indexOf('function '+nom+'(');
        return i<0?null:src.slice(i,i+n); };
      for(const f of ['toggleDayActive','coachToggleDay','cptToggleDay']){
        const c=corpsDe(f,700);
        if(!c) return _echec(f+' est introuvable');
        if(c.indexOf('_garnirSeanceVierge')<0)
          return _echec(f+' n’appelle pas _garnirSeanceVierge');
      }
      return true;})());

    // ⚠ PLUS AUCUN PROGRAMME POSE D'OFFICE, ET ON LE CONSTATE SUR LA SOURCE :
    // les trois chemins qui le faisaient sont nommés, et aucun ne doit plus
    // citer FONDATION ni defEx.
    ok('Aucun chemin de création ne pose plus de programme d\'office',(()=>{
      const src=_prodSrc();
      // Même précaution, et on retire les commentaires : sinon la sonde
      // trouve « FONDATION » dans la phrase qui explique qu'on n'en pose
      // plus. Ce fichier a déjà payé ce piège sept fois.
      const corps=nom=>{ const i=src.indexOf('function '+nom+'(');
        return i<0?null:src.slice(i,i+4000).replace(/\/\/[^\r\n]*/g,' '); };
      for(const f of ['initSessionsConfig','getProgram']){
        const c=corps(f);
        if(!c) return _echec(f+' est introuvable');
        if(/FONDATION_[HF]/.test(c)) return _echec(f+' pose encore une Fondation');
        if(/\bdefEx\b/.test(c)) return _echec(f+' pose encore defEx');
      }
      // getProgram rendait un programme entier à qui n'en avait aucun : il
      // pouvait se dérouler comme si c'était le sien.
      const _u=currentUser, _db=DB.get('users');
      try{
        currentUser={email:'vide@t.fr',id:'v1',role:'athlete'};
        DB.set('users',{'vide@t.fr':{email:'vide@t.fr',id:'v1',role:'athlete'}});
        const g=getProgram();
        if((g.exercises||[]).length) return _echec('getProgram rend '+g.exercises.length+' exercices');
        if(g.name) return _echec('getProgram nomme un programme : « '+g.name+' »');
        // Le drapeau reste : c'est lui que les appelants lisent pour savoir
        // qu'il n'y a rien.
        if(g._isDefault!==true) return _echec('_isDefault a disparu : les appelants ne sauront plus');
      } finally { currentUser=_u; if(_db) DB.set('users',_db); }
      return true;})());

    // LA FONDATION N'EST PAS SUPPRIMEE, elle change de statut : elle cesse
    // d'être un défaut imposé pour devenir un programme qu'on choisit. Les
    // deux jeux doivent donc rester intacts et complets — la boutique les
    // vendra, et un programme amputé se vendrait tout aussi bien.
    ok('Les deux Fondations restent entières, prêtes à être proposées',(()=>{
      for(const [nom,F] of [['Homme',FONDATION_H],['Femme',FONDATION_F]]){
        if(!Array.isArray(F)||!F.length) return _echec('Fondation '+nom+' vide');
        const actives=F.filter(s2=>s2.active);
        if(actives.length!==3) return _echec('Fondation '+nom+' : '+actives.length+' séances actives');
        for(const s2 of actives){
          if(!String(s2.name||'').trim()) return _echec('Fondation '+nom+' : une séance sans nom');
          if(!(s2.exercises||[]).length) return _echec('Fondation '+nom+' : « '+s2.name+' » est vide');
          for(const e of s2.exercises){
            if(!e.name) return _echec('Fondation '+nom+' : un exercice sans nom');
            if(!e.series||!e.reps||!e.repos)
              return _echec('Fondation '+nom+' : « '+e.name+' » est incomplet');
          }
        }
      }
      return true;})());

    // ══ 17/09/2026 — R13 : AUCUN ÉCRAN MORT ══════════════════════════════
    //
    // Un état vide dit ce qui manque et propose le geste qui le remplit —
    // sauf quand l'utilisateur ne peut rien y faire (attente de quelqu'un
    // d'autre, état de succès) ou quand le geste est déjà un bouton du même
    // bloc. Chaque bouton est vérifié jusqu'au bout : un bouton qui aboutit à
    // un toast « rien à faire » serait un cul-de-sac de plus.

    // ⚠ UN COMPTE NEUF PORTE SON ESSAI, et ce decor l'ecrit depuis le lot 4.
    //   L'inscription sans code coach appelle essaiOuvrir (une seule branche
    //   dans tout le fichier) : un dossier neuf SANS essai n'existe pas dans
    //   la vraie vie. Tant que les ecrans ne demandaient rien, l'oubli ne se
    //   voyait pas ; depuis que l'essai vaut Ultime, il decidait de ce que
    //   Nina voit — et ces tests-la parlent d'etats vides, pas de verrous.
    const _r13Neuf=()=>({id:'r13',email:'r13@t.fr',fname:'Nina',lname:'Neuve',role:'athlete',exAlias:{},exMuscles:{},
      sessions:[],bilans:[],videos:[],programs:{},contraintesSante:[],nutrition:{},
      essai:{ouvertLe:Date.now(),seancesAuDebut:0},
      consent:{health:true,policyVersion:POLICY_VERSION}});
    const _r13Lire=z=>{
      const e=z&&z.querySelector('.empty-state'); if(!e) return null;
      const b=e.querySelector('button');
      return {msg:e.textContent.replace(b?b.textContent:'','').replace(/\s+/g,' ').trim(),
        cta:b?b.textContent.trim():null, fn:b?b.getAttribute('onclick'):null, b};
    };

    ok('R13 — le bouton d’état vide est secondaire, et n’existe qu’avec son libellé ET son geste',(()=>{
      const d=document.createElement('div');
      d.innerHTML=emptyState('clipboard','X','Faire','faire()');
      const b=d.querySelector('button');
      if(!b) return _echec('pas de bouton avec libellé et geste');
      for(const cl of ['btn','btn-outline','btn-sm'])
        if(!b.classList.contains(cl)) return _echec('classe « '+cl+' » absente : '+b.className);
      if(b.classList.contains('btn-red')) return _echec('le bouton est rouge plein');
      if(b.getAttribute('onclick')!=='faire()') return _echec('onclick : '+b.getAttribute('onclick'));
      d.innerHTML=emptyState('clipboard','X','Faire',null)+emptyState('clipboard','X',null,'faire()');
      return d.querySelector('button')?_echec('un bouton sans libellé ou sans geste est rendu'):true;})());

