        if(!(Math.abs(eo1[0]+250)<=3&&Math.abs(eo1[1]+114)<=3)) return 'l’étiquette ne suit pas la souris : '+eo1.join();
        pe('pointerdown',x-100,y-80,1); pe('pointerup',x-100,y-80,0);
