    const _r20Garde=async f=>{
      const sU=currentUser, sv=[...document.querySelectorAll('.screen.active')], svSave=window.saveUser;
      const c=document.getElementById('progress-content'), svC=c.innerHTML;
      let n=0; window.saveUser=()=>{ n++; return true; };
      try{ return await f(()=>n); }
      finally{
        window.saveUser=svSave; currentUser=sU; c.innerHTML=svC;
        document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
        sv.forEach(s=>s.classList.add('active'));
      }
    };

    okA('R20 — le changement d’onglet est mémorisé, et saveUser n’est appelé que s’il change',()=>_r20Garde(n=>{
      currentUser=_r20Plein();
      if('uiProgressTab' in currentUser) return _echec('le décor porte déjà le champ');
      showProgressTab('mensus',_progBoutonOnglet('mensus'));
      if(currentUser.uiProgressTab!=='mensus'||n()!==1) return _echec('mensus : '+currentUser.uiProgressTab+', '+n()+' écriture(s)');
      // LE MÊME ONGLET, REPEINT : aucune écriture.
      showProgressTab('mensus',_progBoutonOnglet('mensus'));
      showProgressTab('mensus',null);
      if(n()!==1) return _echec('un repeint du même onglet a écrit ('+n()+')');
      showProgressTab('perf',_progBoutonOnglet('perf'));
      if(currentUser.uiProgressTab!=='perf'||n()!==2) return _echec('perf : '+currentUser.uiProgressTab+', '+n());
      // Le rendu sans mémorisation, et un nom inconnu, n'écrivent rien.
      showProgressTab('notes',null,true);
      try{ showProgressTab('bidule',null); }catch(e){}
      if(currentUser.uiProgressTab!=='perf'||n()!==2) return _echec('écrit à tort : '+currentUser.uiProgressTab+', '+n());
      // Le champ est classé : il passe le verrou de l'article 9.
      if(CHAMPS_NON_SANTE.indexOf('uiProgressTab')<0) return _echec('uiProgressTab n’est pas classé');
      return true;}));

    okA('R20 — loadProgress rouvre l’onglet mémorisé, sur SON bouton, et se replie sans réécrire',()=>_r20Garde(n=>{
      if(PROG_ONGLETS.join()!=='poids,mensus,masseGrasse,perf,volume,photos,notes') return _echec('liste : '+PROG_ONGLETS.join());
      // Chaque onglet a son bouton.
      for(const t of PROG_ONGLETS) if(!_progBoutonOnglet(t)) return _echec('pas de bouton pour '+t);
      // 1. L'onglet mémorisé, avec des données.
      currentUser=_r20Plein({uiProgressTab:'mensus'});
      loadProgress();
      let r=_r20Rouges();
      if(r.length!==1||r[0]!==_progBoutonOnglet('mensus')) return _echec('mensus : bouton allumé « '+r.map(b=>b.textContent.trim()).join(',')+' »');
      if(document.querySelector('#progress-content .empty-state')) return _echec('mensus s’ouvre vide sur un dossier qui a des bilans');
      if(n()) return _echec('la restauration a écrit ('+n()+')');
      // 2. Un nom inconnu : Poids, premier bouton.
      currentUser=_r20Plein({uiProgressTab:'bidule'});
      loadProgress();
      r=_r20Rouges();
      if(r.length!==1||r[0]!==_progBoutonOnglet('poids')) return _echec('nom inconnu : « '+r.map(b=>b.textContent.trim()).join(',')+' »');
      if(currentUser.uiProgressTab!=='bidule'||n()) return _echec('le nom inconnu a été réécrit');
      // 3. « Perfs » sans aucune séance : l'affichage se replie sur Poids…
      currentUser=_r20Plein({uiProgressTab:'perf',sessions:[]});
      loadProgress();
      r=_r20Rouges();
      if(r.length!==1||r[0]!==_progBoutonOnglet('poids')) return _echec('repli : « '+r.map(b=>b.textContent.trim()).join(',')+' »');
      // … mais le choix reste mémorisé, et rien n'est poussé.
      if(currentUser.uiProgressTab!=='perf') return _echec('le repli a réécrit le choix : '+currentUser.uiProgressTab);
      if(n()) return _echec('le repli a appelé saveUser ('+n()+')');
      // 4. Sans champ : Poids, comme avant.
      currentUser=_r20Plein();
      loadProgress();
      r=_r20Rouges();
      if(r.length!==1||r[0]!==_progBoutonOnglet('poids')) return _echec('sans champ : « '+r.map(b=>b.textContent.trim()).join(',')+' »');
      if('uiProgressTab' in currentUser||n()) return _echec('l’ouverture sans choix a créé le champ');
      return true;}));

    // ⚠ LE REPLI LIT LES MÊMES CONDITIONS QUE LE RENDU. _progOngletVide les
    // recopie branche par branche : on rend chaque onglet et on compare.
    okA('R20 — _progOngletVide dit vide exactement quand l’onglet s’ouvre vide',()=>_r20Garde(()=>{
      const c=document.getElementById('progress-content');
      const rendVide=t=>!!c.querySelector('.empty-state')
        ||(t==='volume'&&/Fais ta première séance|Aucune séance cette semaine-là/.test(c.textContent));
      const trop=[];
      // Un bilan avec une réponse écrite : « Notes » a un état vide de plus.
      const _q=BILAN_QUESTIONS.suivi[0];
      const _ecrit=_r20Plein(); _ecrit.bilans[1][_q.k]='Bonne semaine, dos un peu raide.';
      for(const [nom,u] of [['compte neuf',_r13Neuf()],['dossier rempli',_r20Plein()],['réponse écrite',_ecrit],
          ['bilans sans mesure',Object.assign(_r13Neuf(),{bilans:[{type:'coaching',date:Date.now()-864e5}]})],
          ['pesées sans bilan',Object.assign(_r13Neuf(),{weightLog:[{date:localISODate(new Date()),kg:80}]})]]){
        for(const t of PROG_ONGLETS){
          currentUser=JSON.parse(JSON.stringify(u));
          try{ showProgressTab(t,null,true); }catch(e){ trop.push(nom+' · '+t+' : exception '+e.message); continue; }
          const p=_progOngletVide(t,currentUser), v=rendVide(t);
          if(p!==v) trop.push(nom+' · '+t+' : prédit '+(p?'vide':'plein')+', rendu '+(v?'vide':'plein'));
        }
      }
      // Le décor doit prouver quelque chose : au moins un onglet plein.
      currentUser=_r20Plein();
      if(PROG_ONGLETS.every(t=>_progOngletVide(t,currentUser))) trop.push('le dossier rempli est vide partout');
      return trop.length?_echec(trop.join(' | ')):true;}));

    // ══ 17/09/2026 — R15 : LE NORDIC CURL, ET LA CONSIGNE QUI DISPARAISSAIT ══

    ok('R15 — le nordic curl est un exercice d’ischios, et un ancien classement automatique en biceps est corrigé',(()=>{
      const sU=currentUser;
      try{
        currentUser={email:'r15@t.fr',exAlias:{},exMuscles:{
          'NORDIC CURL':{p:['BICEPS'],s:['AVANT_BRAS'],src:'auto'},
          'NORDIC HAMSTRING CURL':{p:['BICEPS'],s:[],src:'manuel'}}};
        for(const n of ['NORDIC CURL','Nordic curl inversé','NORDIC CURL AVEC ELASTIQUE']){
          const r=resoudreMuscles(n,{reps:'6'});
          if(!r||r.p[0]!=='ISCHIOS') return _echec(n+' : '+JSON.stringify(r));
        }
        // CE QUI ÉTAIT FAUX EST RÉÉCRIT, pour de bon.
        if(currentUser.exMuscles['NORDIC CURL'].p[0]!=='ISCHIOS') return _echec('le classement enregistré n’a pas été corrigé');
        // UN CHOIX FAIT À LA MAIN N'EST JAMAIS REPRIS, même faux.
        if(resoudreMuscles('NORDIC HAMSTRING CURL',{reps:'6'}).p[0]!=='BICEPS') return _echec('un choix manuel a été écrasé');
        // Le curl reste un curl.
        if(resoudreMuscles('CURL BARRE',{reps:'10'}).p[0]!=='BICEPS') return _echec('CURL BARRE n’est plus biceps');
        if(resoudreMuscles('CURL MARTEAU DE MON COACH',{reps:'10'}).p[0]!=='BICEPS') return _echec('un curl hors guide n’est plus biceps');
        // LA LECTURE D'UN AUTRE DOSSIER corrige ce qu'elle rend, SANS écrire.
        const autre={exAlias:{},exMuscles:{'NORDIC CURL':{p:['BICEPS'],s:[],src:'auto'}}};
        const l=resoudreMusclesLecture('NORDIC CURL',null,autre);
        if(!l||l.p[0]!=='ISCHIOS') return _echec('lecture : '+JSON.stringify(l));
        if(autre.exMuscles['NORDIC CURL'].p[0]!=='BICEPS') return _echec('la lecture a écrit dans le dossier');
        return true;
      } finally { currentUser=sU; }})());

    // ⚠ DANS UNE VRAIE SÉANCE, ET SANS INDEX. C'est l'état d'une séance
    // reprise après une mise à jour : l'apercu, qui chargeait l'index, n'a pas
    // été ouvert.
    okA('R15 — une séance ouverte sans l’index des illustrations retrouve son image, et la vidéo du guide s’affiche',async()=>{
      const sU=currentUser, sW=woState, sSnap=localStorage.getItem('rc_wo_state'), sIdx=_exoIndex;
      try{
        currentUser={id:'r15',email:'r15@t.fr',fname:'A',lname:'B',role:'athlete',exAlias:{},exMuscles:{},
          sessions:[],bilans:[],videos:[],programs:{},contraintesSante:[],
          sessions_config:[{active:true,name:'Jambes',exercises:[{name:'LEG CURL ASSIS',series:3,reps:'12',repos:'2 min',description:'',videoUrl:''}]}]};
        _exoIndex=null;
        launchWorkout(currentUser.sessions_config[0],0);
        const z=document.getElementById('wo-consigne-0');
        if(!z) return _echec('pas de zone de consigne dans la séance');
        if(z.querySelector('img')) return _echec('le décor ne prouve rien : l’image est déjà là');
        await chargerIndexIllustrations();
        await new Promise(r=>setTimeout(r,0));
        const img=document.getElementById('wo-consigne-0').querySelector('img');
        if(!img||!/leg-curl-assis\.webp$/.test(img.getAttribute('src')||'')) return _echec('l’image ne revient pas');
        if(!/CONSIGNE/.test(document.getElementById('wo-consigne-0').textContent)) return _echec('le bloc CONSIGNE ne revient pas');
        // LA VIDÉO DU GUIDE, quand le programme n'en porte pas.
        const att=videosPour('LEG CURL ASSIS')[0];
        if(!att) return _echec('le guide n’a plus de vidéo pour LEG CURL ASSIS');
        const a=[...document.getElementById('wo-content').querySelectorAll('a')].find(x=>/VIDÉO TECHNIQUE/.test(x.textContent));
        if(!a||a.getAttribute('href')!==safeUrl(normaliserUrlVideo(att.url))) return _echec('vidéo : '+(a?a.getAttribute('href'):'aucune'));
        // ET CELLE DU COACH PASSE DEVANT.
        woState.exercises[0].videoUrl='https://youtu.be/dQw4w9WgXcQ';
        renderWoEx();
        const a2=[...document.getElementById('wo-content').querySelectorAll('a')].find(x=>/VIDÉO TECHNIQUE/.test(x.textContent));
        if(!a2||a2.getAttribute('href')!==safeUrl(normaliserUrlVideo('https://youtu.be/dQw4w9WgXcQ'))) return _echec('la vidéo du coach ne passe pas devant');
        return true;
      } finally {
        try{ clearInterval(woState.timerInterval); }catch(e){}
        localStorage.removeItem('rc_wo_state');
        if(sSnap) localStorage.setItem('rc_wo_state',sSnap);
        if(!_exoIndex&&sIdx) _exoIndex=sIdx;
        currentUser=sU; woState=sW;
      }
    });

    // ══ 16/09/2026 — R07 : LA COLONNE D'INTENSITE PARLE AU DOIGT ═════════
    //
    // Deux éléments portaient leur sens dans un attribut title= : la mention
    // « cible N » et la pastille « @N ». UN title N'EXISTE PAS AU DOIGT — sur
    // téléphone, les deux étaient muets. C'est tout l'objet du lot.

    // Un décor qui reproduit le gabarit étroit de _blocExo, aux mêmes classes :
    // c'est la mise en page réelle qui contraint la place, pas une approximation.
    // R08 — LA BANDE EST CELLE DE LA PRODUCTION, et le décor passe EN TÊTE de
    // page : getElementById rend le PREMIER nœud du document, et un décor
    // ajouté en fin laissait renderSets écrire dans le tableau d'une séance
    // rendue par un test précédent.
    const _r07Fix=f=>{
      const d=document.createElement('div');
      d.style.cssText='position:fixed;left:0;top:0;width:359px;background:#000;z-index:-1';
      d.innerHTML='<div id="wo-sets-scroll-0" style="overflow-x:auto">'
        +'<table class="series-table series-table-wo" style="width:100%;min-width:260px">'
        +'<thead><tr id="r07-tr" style="background:var(--red)">'+_enteteSeries(false,false)
        +'</tr></thead><tbody id="sets-body-0"></tbody></table></div>';
      document.body.insertBefore(d,document.body.firstChild);
      try{ return f(d); } finally { d.remove(); }
    };
    // R08 — L'EN-TÊTE SUIT LES SÉRIES : la bande est repeinte comme _blocExo
    // la peint, et la zone d'intensité se lit par sa classe, qui est la même
    // en colonnes (R14) et en cartes (dégressive).
    const _r07Cell=(ex,sets)=>{
      const tr=document.getElementById('r07-tr');
      if(tr) tr.innerHTML=_enteteSeries(_seriesEnCartes({sets:sets}),false);
      renderSets(ex,{sets:sets},0);
      return document.querySelector('#sets-body-0 tr .wo-intensite'); };
    const _r07Th=()=>[...document.querySelectorAll('#r07-tr th')].find(t=>/RIR/.test(t.textContent));

    ok('La consigne du coach se lit « visé », et son title reste',(()=>
      _r07Fix(()=>{
        const c=_r07Cell({name:'DEVELOPPE COUCHE',series:3,reps:'10',rirCible:'2'},
          [{weight:60,reps:10,rir:'',pain:''}]);
        if(!c) return _echec('la cellule d’intensité a disparu');
        const sp=[...c.querySelectorAll('span')].find(x=>/visé/.test(x.textContent));
        if(!sp) return _echec('la mention « visé » est absente : « '+c.textContent.trim()+' »');
        if(/cible/.test(c.textContent)) return _echec('« cible » est encore là');
        if(sp.textContent.replace(/\s+/g,' ').trim()!=='visé : 2')
          return _echec('mention : « '+sp.textContent.trim()+' »');
        // ⚠ LE title= RESTE. Il ne sert à rien au doigt, mais il sert au
        // survol sur bureau, et le lot demande de le conserver.
        if(sp.getAttribute('title')!=='Intensité demandée par ton coach')
          return _echec('title : « '+sp.getAttribute('title')+' »');
        return true;})));

    // ⚠ LA LOGIQUE D'ECART NE BOUGE PAS : seuil à plus d'un cran, orange
    // au-delà, gris en deçà, et RIEN tant que rien n'est saisi. Un rappel
    // n'est pas un jugement — c'est écrit dans le code, et c'est mesuré ici.
    ok('L\'écart de consigne garde son seuil, ses couleurs, et son silence',(()=>
      _r07Fix(()=>{
        const ex={name:'DEVELOPPE COUCHE',series:3,reps:'10',rirCible:'2'};
        const coul=rir=>{
          const c=_r07Cell(ex,[{weight:60,reps:10,rir:rir,pain:''}]);
          const sp=[...c.querySelectorAll('span')].find(x=>/visé/.test(x.textContent));
          return sp?getComputedStyle(sp).color:null;
        };
        const ORANGE='rgb(249, 115, 22)', GRIS='rgb(130, 130, 130)';
        // Rien de saisi : rien à comparer, donc gris.
        if(coul('')!==GRIS) return _echec('sans saisie : '+coul(''));
        // Un cran d'écart : ce n'est pas « loin ».
        if(coul('3')!==GRIS) return _echec('un cran d’écart : '+coul('3'));
        if(coul('1')!==GRIS) return _echec('un cran d’écart sous la cible : '+coul('1'));
        // Deux crans : orange.
        if(coul('4')!==ORANGE) return _echec('deux crans : '+coul('4'));
        // L'échec vaut zéro, donc deux crans sous une cible de 2.
        if(coul('echec')!==ORANGE) return _echec('échec : '+coul('echec'));
        return true;})));

    ok('La pastille verrouillée dit ce qu\'elle est, et reste inmodifiable',(()=>
      _r07Fix(()=>{
        const c=_r07Cell({name:'DEVELOPPE COUCHE',series:3,reps:'10'},
          [{weight:60,reps:10,rpeCible:8,pain:''}]);
        if(!c) return _echec('la cellule a disparu');
        const p=c.querySelector('[role="img"]');
        if(!p) return _echec('la pastille a perdu son role');
        // ⚠ CE N'EST TOUJOURS PAS UN <select>. Décision produit documentée
        // dans le code : le coach a fixé le RPE, l'athlète ne le règle pas.
        if(c.querySelector('select')) return _echec('la colonne est redevenue modifiable');
        const txt=p.textContent.replace(/\s+/g,' ').trim();
        if(txt!=='RPE 8') return _echec('texte : « '+txt+' »');
        if(/@/.test(txt)) return _echec('« @N » est encore là');
        // Le cadenas dit qu'on ne la règle pas, sans un mot de plus.
        if(!p.querySelector('svg')) return _echec('le cadenas est absent');
        // L'aria-label d'origine, mot pour mot.
        if(p.getAttribute('aria-label')!=='RPE demandé par ton coach : 8 sur 10')
          return _echec('aria-label : « '+p.getAttribute('aria-label')+' »');
        if(!p.getAttribute('title')) return _echec('le title a été retiré');
        // ⚠ ET LE ⓘ EST DEHORS, PAS DEDANS. L'élément porte role="img" : tout
        // ce qu'il contient disparaît pour un lecteur d'écran, remplacé par
        // son aria-label. Un bouton posé à l'intérieur aurait été visible pour
        // l'œil et absent pour la voix.
        if(p.querySelector('.rc-i')) return _echec('le ⓘ est enfermé dans le role="img" : il est inatteignable');
        const b=c.querySelector('.rc-i');
        if(!b) return _echec('la pastille du lexique est absente de la cellule');
        if((b.getAttribute('onclick')||'').indexOf('rcInfoOuvrir(\'rpe\')')<0)
          return _echec('le ⓘ n’ouvre pas « rpe » : '+b.getAttribute('onclick'));
        // Et il est bien À DROITE de la pastille.
        if(!(b.compareDocumentPosition(p)&Node.DOCUMENT_POSITION_PRECEDING))
          return _echec('le ⓘ n’est pas à droite de la pastille');
        return true;})));

    ok('L\'en-tête de la colonne RIR porte son explication',(()=>
      _r07Fix(()=>{
        const src=_prodSrc();
        if(src.indexOf('RIR${rcInfo(\'rir\')}')<0)
          return _echec('l’en-tête de colonne ne pose pas le ⓘ');
        const th=_r07Th();
        const b=th&&th.querySelector('.rc-i');
        if(!b) return _echec('le ⓘ n’est pas rendu dans l’en-tête');
        if((b.getAttribute('onclick')||'').indexOf('rcInfoOuvrir(\'rir\')')<0)
          return _echec('l’en-tête n’ouvre pas « rir »');
        // SUR LA BANDE ROUGE le gris de base disparaîtrait : la pastille y
        // vire au blanc voilé, sans changer de taille.
        const co=getComputedStyle(b).color;
        if(!/255,\s*255,\s*255/.test(co)) return _echec('couleur sur la bande rouge : '+co);
        if(Math.round(b.getBoundingClientRect().width)!==32)
          return _echec('le ⓘ de l’en-tête fait '+Math.round(b.getBoundingClientRect().width)+'px');
        return true;})));

    // ══ LA PLACE, MESUREE A 359 px ═══════════════════════════════════════
    //
    // ⚠ CE TEST A DECIDE DU LOT. Le ⓘ avait été posé aussi dans la CELLULE,
    // à côté de « visé : 2 » : la cellule débordait alors de 2 px à 359 px, et
    // deux pixels suffisent à ouvrir un défilement latéral dans un tableau à
    // cinq colonnes. La règle du lot est explicite — on retire le ⓘ de la
    // cellule, on le garde sur l'en-tête, et on NE REDUIT PAS la police pour
    // le faire tenir. L'assertion garde la porte fermée.
    ok('À 359 px, la colonne d\'intensité ne déborde pas',(()=>
      _r07Fix(d=>{
        const sc=document.getElementById('wo-sets-scroll-0');
        const tb=sc.querySelector('table');
        const ex={name:'DEVELOPPE COUCHE',series:3,reps:'10'};
        const cas=[
          ['sans consigne',ex,[{weight:60,reps:10,rir:'',pain:''}]],
          ['avec consigne',{name:'DEVELOPPE COUCHE',series:3,reps:'10',rirCible:'2'},
            [{weight:60,reps:10,rir:'5',pain:''}]],
          ['RPE verrouillé',ex,[{weight:60,reps:10,rpeCible:8,pain:''}]]
        ];
        const trop=[];
        for(const [nom,e,sets] of cas){
          const c=_r07Cell(e,sets);
          // L'en-tête est repeint à chaque cas : on le relit après.
          const th=_r07Th();
          if(!th){ trop.push(nom+' : l’en-tête ne nomme plus le RIR'); continue; }
          if(tb.scrollWidth>sc.clientWidth+1)
            trop.push(nom+' : le tableau déborde de '+(tb.scrollWidth-sc.clientWidth)+'px');
          if(c&&c.scrollWidth>c.clientWidth+1)
            trop.push(nom+' : la cellule déborde de '+(c.scrollWidth-c.clientWidth)+'px');
          if(th.scrollWidth>th.clientWidth+1)
            trop.push(nom+' : l’en-tête déborde de '+(th.scrollWidth-th.clientWidth)+'px');
          // Le ⓘ de l'en-tête ne sort pas de sa case.
          const b=th.querySelector('.rc-i');
          if(b){ const rt=th.getBoundingClientRect(), rb=b.getBoundingClientRect();
            if(rb.right>rt.right+1) trop.push(nom+' : le ⓘ sort de l’en-tête'); }
        }
        // ⚠ ET LA POLICE N'A PAS BAISSE POUR FAIRE TENIR : c'est l'autre
        // moitié de la règle, et c'est la triche la plus facile.
        const c2=_r07Cell(cas[1][1],cas[1][2]);
        const sp=c2&&[...c2.querySelectorAll('span')].find(x=>/visé/.test(x.textContent));
        if(sp&&parseFloat(getComputedStyle(sp).fontSize)<10)
          return _echec('la mention est passée sous 10px : '+getComputedStyle(sp).fontSize);
        return trop.length?_echec(trop.join(' | ')):true;})));

    // ══ CE QUE R07 NE TOUCHE PAS ═════════════════════════════════════════
    ok('R07 ne renverse aucune des décisions documentées de la colonne',(()=>
      _r07Fix(()=>{
        // ⚠ `rir` RESTE VIDE SUR UN EXERCICE PROGRAMME. « Recopier le RPE
        // prescrit dans rir ferait passer une consigne pour une mesure, et le
        // coach lirait sa propre prescription en croyant lire son athlète. »
        const data={sets:[{weight:60,reps:10,rpeCible:8,pain:''},
                          {weight:60,reps:10,rpeCible:8,pain:''}]};
        renderSets({name:'DEVELOPPE COUCHE',series:3,reps:'10'},data,0);
        for(const s of data.sets)
          if(s.rir!==undefined&&s.rir!=='')
            return _echec('le RPE prescrit a été recopié dans rir : '+s.rir);
        // ET LA CHARGE NE DERIVE PAS non plus sur un exercice programmé.
        if(data.sets[1].weight!==60) return _echec('la charge a dérivé : '+data.sets[1].weight);
        // _rirPrescrit et consigneProgEx n'ont pas changé de réponse.
        if(_rirPrescrit({name:'X',rirCible:'2'})!=='2')
          return _echec('_rirPrescrit ne rend plus la consigne');
        if(_rirPrescrit({name:'X'})!=='')
          return _echec('_rirPrescrit invente une consigne quand il n’y en a pas');
        return true;})));

    // ══ 16/09/2026 — R06 : LE LEXIQUE, UNE SOURCE ET UN COMPOSANT ════════
    //
    // L'application employait « RIR », « e1RM », « NEAT », « macros » sans les
    // définir nulle part. Le risque, en corrigeant ça, n'est pas d'oublier un
    // mot : c'est d'en définir un DEUX FOIS. Deux explications de la même
    // notion divergent toujours, et c'est celle qu'on ne relit pas qui reste
    // fausse. Ces assertions tiennent l'unicité autant que le contenu.

    ok('Le catalogue du lexique est gelé, et chaque entrée est complète',(()=>{
      if(typeof RC_LEXIQUE!=='object'||!RC_LEXIQUE) return _echec('RC_LEXIQUE n’existe pas');
      if(!Object.isFrozen(RC_LEXIQUE)) return _echec('le catalogue n’est pas gelé');
      const cles=Object.keys(RC_LEXIQUE);
      if(cles.length<10) return _echec(cles.length+' entrées : '+cles.join(','));
      for(const k of cles){
        const e=RC_LEXIQUE[k];
        if(!Object.isFrozen(e)) return _echec(k+' : l’entrée n’est pas gelée');
        // LE MINIMUM DEMANDE : un titre et une définition, non vides.
        if(!e.t||!String(e.t).trim()) return _echec(k+' : titre vide');
        if(!e.d||!String(e.d).trim()) return _echec(k+' : définition vide');
        // ⚠ VINGT MOTS AU PLUS. Au-delà on écrit un article, et un article ne
        // se lit pas au milieu d'une série.
        const m=String(e.d).trim().split(/\s+/).length;
        if(m>20) return _echec(k+' : '+m+' mots dans la définition');
        // AU TUTOIEMENT, comme tout le reste de l'application côté athlète.
        if(/\b(vous|votre|vos)\b/i.test(e.d+' '+(e.p||'')))
          return _echec(k+' : vouvoiement dans « '+e.d+' »');
        if(e.p!==undefined&&!String(e.p).trim()) return _echec(k+' : ligne « en pratique » vide');
        if(e.e!==undefined){
          if(!Array.isArray(e.e)||e.e.length<2||e.e.length>4)
            return _echec(k+' : une échelle fait 2 à 4 lignes, pas '+(e.e||[]).length);
          for(const l of e.e)
            if(!Array.isArray(l)||l.length!==2||!l[0]||!l[1])
              return _echec(k+' : une ligne d’échelle n’est pas [libellé, explication]');
        }
      }
      return true;})());

    // ⚠ LES TEXTES SONT VALIDES, ILS NE SE RETOUCHENT PAS AU FIL DE L'EAU.
    // Une définition qui dérive d'une version à l'autre est exactement ce que
    // ce catalogue existe pour empêcher — on la fige donc ici aussi.
    ok('Les définitions du lexique sont celles qui ont été validées',(()=>{
      const att={
        // R11 — plus aucun tiret dans les fiches (Kevin, 17/09/2026) : les
        // titres passent a la parenthese, les plages a « à ».
        rir:['RIR (répétitions en réserve)',
          'Le nombre de répétitions que tu aurais encore pu faire après ta dernière.',
          'Vise RIR 2 sur tes premières séries, RIR 0 à 1 sur la dernière.'],
        rpe:['RPE (intensité demandée par ton coach)',
          'Une note sur 10 fixée par ton coach pour cette série.',
          'Tu ne la règles pas : note ta charge, c\'est tout.'],
        // R11 — la precision des repetitions prevues, retiree de l'onglet Perfs.
        e1rm:['Force max estimée (e1RM)',
          'La charge que tu pourrais sans doute soulever une seule fois, calculée depuis tes séries.',
          'Fiable jusqu\'à 12 répétitions, approximative au-delà. Jamais testée en vrai. Calculée sur les répétitions prévues au programme, ou sur celles que tu as notées quand l\'exercice a une fourchette.'],
        douleur:['Échelle de gêne',
          'Note ce que tu as ressenti pendant la série, pas après.',undefined],
        neat:['Activité hors sport (NEAT)',
          'Ce que tu dépenses en dehors de tes séances : marche, travail, gestes du quotidien.',undefined],
        macros:['Macros',
          'Protéines, glucides et lipides : les trois familles qui composent tes calories.',undefined],
        volume:['Volume',
          'La quantité de travail accumulée sur une période, muscle par muscle.',undefined],
        surcharge:['Surcharge progressive',
          'Augmenter un peu la charge dès que tu gardes des répétitions en réserve.',
          'RepCore le fait pour toi : la charge proposée monte toute seule.'],
        // R11 — la note de methode de l'onglet Masse grasse est venue ici.
        masse_grasse:['Masse grasse estimée',
          'Estimée depuis ton tour de taille, ton cou et ta taille (jamais mesurée).',
          'Formule US Navy : marge de 3 à 4 points, davantage aux extrêmes (très maigre ou très corpulent). Regarde la tendance entre deux bilans, pas le chiffre exact.'],
        '1rm':['1RM','La charge maximale que tu pourrais soulever une seule fois.',undefined],
        // R10 — les quatre entrees du lot. assiduite et score_diete sont
        // ecrites sur ce que le CODE compte (updateStreak, jourDieteTenu).
        assiduite:['Semaines d\'assiduité',
          'Le nombre de semaines d\'affilée où tu as fait toutes les séances prévues à ton programme.',undefined],
        score_diete:['Diète respectée',
          'La part des jours tenus : selon ta réponse du jour, ou ton journal comparé à tes cibles.',
          'Les jours non renseignés ne comptent ni en bien ni en mal.'],
        reds:['RED-S (déficit énergétique relatif)',
          'Des signes que l\'apport alimentaire ne couvre plus la dépense : sommeil, cycle, blessures, humeur.',undefined],
        plateau:['Plateau','Aucun nouveau maximum sur cet exercice depuis plusieurs semaines.',undefined],
        // LES QUATRE ZONES DE VOLUME (23/09/2026). Elles se lisent sous la
        // silhouette « Évolution », chez le coach comme chez l'élève : une
        // définition qui dériverait d'une version à l'autre se contredirait
        // d'un écran à l'autre.
        zone_sous_mev:['sous-MEV (minimum efficace)',
          'Moins de séries que le minimum efficace : le muscle garde ce qu\'il a, sans de quoi progresser.',
          'Les trois seuils changent d\'un muscle à l\'autre, et peuvent être ajustés sur les retours de séance ou fixés par le coach.'],
        zone_mev_mav:['MEV-MAV (minimum à adapté)',
          'Au-dessus du minimum efficace, sous le volume adapté : de quoi entretenir, et progresser lentement.',
          'Les trois seuils changent d\'un muscle à l\'autre, et peuvent être ajustés sur les retours de séance ou fixés par le coach.'],
        zone_mav_mrv:['MAV-MRV (adapté à maximum récupérable)',
          'Du volume adapté jusqu\'au maximum récupérable : la zone où le muscle progresse le mieux.',
          'Les trois seuils changent d\'un muscle à l\'autre, et peuvent être ajustés sur les retours de séance ou fixés par le coach.'],
        zone_sur_mrv:['sur-MRV (au-delà du maximum récupérable)',
          'Plus de séries que ce que la récupération suit : le travail s\'accumule sans se transformer.',
          'Les trois seuils changent d\'un muscle à l\'autre, et peuvent être ajustés sur les retours de séance ou fixés par le coach.']
      };
      for(const [k,[t,d,pr]] of Object.entries(att)){
        const e=RC_LEXIQUE[k];
        if(!e) return _echec(k+' a disparu du catalogue');
        if(e.t!==t) return _echec(k+' titre : « '+e.t+' »');
        if(e.d!==d) return _echec(k+' définition : « '+e.d+' »');
        if((e.p||undefined)!==pr) return _echec(k+' pratique : « '+e.p+' »');
      }
      // Les deux échelles, en entier : ce sont les repères qu'on lit en
      // choisissant un chiffre, et un repère faux vaut mieux absent.
      if(RC_LEXIQUE.rir.e.map(l=>l.join('=')).join('|')
         !=='RIR 0=Échec : pas une de plus|RIR 1=Une encore en réserve|'
           +'RIR 2=Deux encore : intense mais contrôlé|RIR 3+=Encore loin de l\'échec')
        return _echec('échelle RIR : '+JSON.stringify(RC_LEXIQUE.rir.e));
      if(RC_LEXIQUE.douleur.e.map(l=>l.join('=')).join('|')
         !=='1 à 2=À peine perceptible|3=Gênant mais supportable|'
           +'4 à 5=Ça fait mal, ta technique se dégrade|6=Je dois arrêter')
        return _echec('échelle gêne : '+JSON.stringify(RC_LEXIQUE.douleur.e));
      return true;})());

    // ⚠ UNE SOURCE DE VERITE, ET UNE SEULE. Si une définition se retrouvait
    // recopiée ailleurs dans le fichier — dans un title=, un placeholder, une
    // aide en ligne — le catalogue cesserait d'être la source : il n'en serait
    // plus qu'une copie parmi d'autres, et la divergence ne serait qu'une
    // question de temps.
    ok('Aucune définition du lexique n\'est recopiée ailleurs',(()=>{
      const src=_prodSrc();
      const doubles=[];
      for(const [k,e] of Object.entries(RC_LEXIQUE)){
        // On cherche le texte tel qu'il est ECRIT dans la source : l'apostrophe
        // y est échappée par le backslash du littéral JavaScript.
        const lit=e.d.replace(/'/g,'\\\'');
        const n=src.split(lit).length-1;
        if(n>1) doubles.push(k+' ×'+n);
      }
      return doubles.length?_echec('définitions recopiées : '+doubles.join(', ')):true;})());

    // ⚠ rcInfo EST PURE, ET SURTOUT INCASSABLE. Elle sera appelée depuis des
    // dizaines de gabarits en R07 à R10 : `${rcInfo(cle)}` ne doit jamais
    // pouvoir casser la ligne qui l'accueille, même si la clé se trompe ou
    // disparaît du catalogue.
    ok('rcInfo rend une pastille, ou rien du tout',(()=>{
      if(rcInfo('inconnu')!=='') return _echec('une clé inconnue rend « '+rcInfo('inconnu')+' »');
      if(rcInfo()!=='') return _echec('sans clé, rcInfo rend du balisage');
      if(rcInfo(null)!==''||rcInfo('')!=='') return _echec('null ou vide rend du balisage');
      // ⚠ ET PAS D'HERITAGE D'Object.prototype : rcInfo('toString') lirait une
      // fonction et rendrait un bouton mort si la lecture n'était pas gardée.
      if(rcInfo('toString')!=='') return _echec('une clé héritée rend un bouton mort');
      const h=rcInfo('rir');
      if(h.indexOf('rir')<0) return _echec('la pastille ne porte pas sa clé : '+h);
      const d=document.createElement('div');
      d.style.cssText='position:fixed;left:-9999px;top:0'; d.innerHTML=h;
      document.body.appendChild(d);
      try{
        const b=d.querySelector('button');
        if(!b) return _echec('la pastille ne rend aucun bouton');
        // Le type est explicite : dans un <form>, un bouton sans type SOUMET.
        if(b.getAttribute('type')!=='button')
          return _echec('pas de type="button" : la pastille soumettrait un formulaire');
        if(!b.classList.contains('rc-i')||!b.classList.contains('hit44'))
          return _echec('classes : '+b.className);
        if((b.getAttribute('onclick')||'').indexOf('rcInfoOuvrir(\'rir\')')<0)
          return _echec('onclick : '+b.getAttribute('onclick'));
        const al=b.getAttribute('aria-label')||'';
        if(al!=='Qu\'est-ce que '+RC_LEXIQUE.rir.t+' ?') return _echec('aria-label : « '+al+' »');
        if(b.textContent.trim()!=='ⓘ') return _echec('glyphe : « '+b.textContent.trim()+' »');
        return true;
      } finally { d.remove(); }})());

    // LA MISE EN FORME DEMANDEE, mesurée sur le rendu et non relue dans la
    // feuille : 32 px de zone, 13 px de glyphe, aucun fond, aucune bordure.
    ok('La pastille tient la mise en forme demandée, et ne bouge pas',(()=>{
      const d=document.createElement('div');
      d.style.cssText='position:fixed;left:-9999px;top:0'; d.innerHTML=rcInfo('rir');
      document.body.appendChild(d);
      try{
        const b=d.querySelector('.rc-i'), cs=getComputedStyle(b);
        const r=b.getBoundingClientRect();
        if(Math.round(r.width)!==32||Math.round(r.height)!==32)
          return _echec('zone dessinée '+Math.round(r.width)+'×'+Math.round(r.height)+' au lieu de 32×32');
        if(parseFloat(cs.fontSize)!==13) return _echec('glyphe à '+cs.fontSize);
        if(cs.borderTopWidth!=='0px') return _echec('bordure : '+cs.borderTopWidth);
        if(cs.backgroundImage!=='none'||!/rgba\(0, 0, 0, 0\)|transparent/.test(cs.backgroundColor))
          return _echec('fond : '+cs.backgroundColor+' / '+cs.backgroundImage);
        if(cs.verticalAlign!=='middle') return _echec('vertical-align : '+cs.verticalAlign);
        if(parseFloat(cs.marginLeft)!==4) return _echec('margin-left : '+cs.marginLeft);
        if(cs.flexShrink!=='0') return _echec('flex-shrink : '+cs.flexShrink);
        // ⚠ PAS D'ANIMATION. Un élément d'aide qui bouge attire l'œil qu'il
        // devrait laisser au contenu — et c'est demandé sans.
        if(cs.animationName!=='none') return _echec('animation : '+cs.animationName);
        if(!/^(none|all 0s|.*\b0s\b)/.test(cs.transition||'none')&&cs.transitionDuration!=='0s')
          return _echec('transition : '+cs.transition);
        // .hit44 porte la zone tactile SANS agrandir le dessin.
        const av=getComputedStyle(b,'::before');
        if(parseFloat(av.width)<44||parseFloat(av.height)<44)
          return _echec('zone tactile '+av.width+'×'+av.height);
        return true;
      } finally { d.remove(); }})());

    // ⚠ LA PASTILLE NE DOIT JAMAIS CASSER L'ALIGNEMENT DE LA LIGNE QUI LA
    // PORTE, et c'est demandé dans trois contextes précis. Chacun casse d'une
    // façon différente : un <th> par la ligne de base, un titre de carte en
    // flex par l'écrasement (sans flex-shrink:0 elle tombe à zéro quand le
    // texte est long), un libellé par la hauteur de ligne.
    ok('La pastille s\'aligne dans un <th>, un titre de carte et un libellé',(()=>{
      const d=document.createElement('div');
      d.style.cssText='position:fixed;left:0;top:0;width:359px;background:#000;z-index:-1';
      d.innerHTML=
        '<table class="series-table" style="width:100%"><thead><tr>'
        +'<th id="rci-c1">RIR'+rcInfo('rir')+'</th><th>Charge</th></tr></thead>'
        +'<tbody><tr><td>10</td><td>60</td></tr></tbody></table>'
        +'<div class="card"><div class="card-title" id="rci-c2" style="display:flex;align-items:center">'
        +'Masse grasse estimée sur un titre vraiment très long'+rcInfo('masse_grasse')+'</div></div>'
        +'<div style="padding:8px"><label id="rci-c3" style="font-size:var(--fs-sm)">'
        +'Activité hors sport'+rcInfo('neat')+'</label></div>';
      document.body.appendChild(d);
      try{
        for(const [id,quoi] of [['rci-c1','<th> de tableau'],
            ['rci-c2','titre de carte'],['rci-c3','libellé de champ']]){
          const p=document.getElementById(id), b=p&&p.querySelector('.rc-i');
          if(!b) return _echec(quoi+' : la pastille a disparu');
          const rp=p.getBoundingClientRect(), rb=b.getBoundingClientRect();
          // ÉCRASÉE : c'est ce qui arrive dans un conteneur flex sans
          // flex-shrink:0, et le bouton devient intouchable.
          if(Math.round(rb.width)<30)
            return _echec(quoi+' : pastille écrasée à '+Math.round(rb.width)+'px');
          // SORTIE DE SA LIGNE : le symptôme d'un vertical-align perdu.
          if(rb.top<rp.top-2||rb.bottom>rp.bottom+2)
            return _echec(quoi+' : la pastille déborde sa ligne');
          // Et le texte reste centré sur elle.
          const ec=Math.abs((rb.top+rb.bottom)/2-(rp.top+rp.bottom)/2);
          if(ec>3) return _echec(quoi+' : centres décalés de '+ec.toFixed(1)+'px');
        }
        return true;
      } finally { d.remove(); }})());

    ok('La feuille rend le titre, la définition, et rien de plus',(()=>{
      const z=document.getElementById('rc-lexique');
      const c=document.getElementById('rc-lexique-corps');
      if(!z||!c) return _echec('la feuille du lexique n’existe pas');
      try{
        // Une entrée COMPLETE : les quatre parties.
        if(rcInfoOuvrir('rir')===null) return _echec('rcInfoOuvrir n’ouvre pas');
        if(z.style.display!=='flex') return _echec('la feuille reste fermée');
        if((c.querySelector('.rci-t')||{}).textContent!==RC_LEXIQUE.rir.t)
          return _echec('titre rendu : « '+(c.querySelector('.rci-t')||{}).textContent+' »');
        if((c.querySelector('.rci-d')||{}).textContent!==RC_LEXIQUE.rir.d)
          return _echec('définition non rendue');
        const pr=(c.querySelector('.rci-p')||{}).textContent||'';
        if(pr.indexOf('En pratique')!==0||pr.indexOf(RC_LEXIQUE.rir.p)<0)
          return _echec('« En pratique » : « '+pr+' »');
        // DEUX COLONNES, SANS EN-TETE.
        const tb=c.querySelector('table.rci-e');
        if(!tb) return _echec('l’échelle n’est pas un tableau');
        if(tb.querySelector('thead')) return _echec('le tableau porte un en-tête');
        const lignes=tb.querySelectorAll('tr');
        if(lignes.length!==4) return _echec(lignes.length+' lignes au lieu de 4');
        for(const tr of lignes)
          if(tr.children.length!==2) return _echec('une ligne a '+tr.children.length+' colonnes');
        // ⚠ ET UNE ENTREE NUE N'INVENTE RIEN. Un bloc « en pratique » vide ou
        // un tableau à zéro ligne meubleraient — la règle du produit est de
        // ne pas meubler.
        rcInfoOuvrir('neat');
        if(c.querySelector('.rci-p')) return _echec('neat rend un bloc « en pratique » vide');
        if(c.querySelector('.rci-e')) return _echec('neat rend un tableau vide');
        if((c.querySelector('.rci-d')||{}).textContent!==RC_LEXIQUE.neat.d)
          return _echec('neat ne rend pas sa définition');
        // UNE CLE INCONNUE N'OUVRE RIEN, et surtout n'efface pas ce qui est là.
        const av=c.innerHTML;
        if(rcInfoOuvrir('inconnu')!==null) return _echec('une clé inconnue ouvre la feuille');
        // ⚠ ET PAS PLUS PAR LE PROTOTYPE. rcInfoOuvrir('toString') aurait
        // ouvert une feuille sur « undefined » tant que la lecture n'était
        // pas gardée par hasOwnProperty.
        if(rcInfoOuvrir('toString')!==null) return _echec('une clé héritée ouvre la feuille');
        if(c.innerHTML!==av) return _echec('une clé inconnue a vidé le corps');
        // ⚠ TOUT PASSE PAR escapeHtml. Les textes viennent d'une constante
        // gelée aujourd'hui ; R10 en ajoutera, et le composant n'aura pas à
        // être relu pour rester sûr.
        const f=String(rcInfoOuvrir);
        for(const ch of ['e.t','e.d','e.p'])
          if(f.indexOf('escapeHtml('+ch+')')<0) return _echec(ch+' n’est pas échappé');
        if(!/escapeHtml\(l\[0\]\)/.test(f)||!/escapeHtml\(l\[1\]\)/.test(f))
          return _echec('les lignes d’échelle ne sont pas échappées');
        return true;
      } finally { try{ rcInfoFermer(true); }catch(e){} }})());

    // ══ LES REGLES UX, MESUREES ET NON RELUES ════════════════════════════
    //
    // ⚠ LA FEUILLE NE DEFILE PAS. C'est une règle, pas un réglage : une
    // explication qui demande de faire défiler n'est plus une explication,
    // c'est un article — et on est venu chercher un mot au milieu d'une série.
    // Si une entrée n'y tient pas, c'est L'ENTREE qu'il faut raccourcir ;
    // cette assertion est là pour que ce soit constaté au lieu d'être découvert
    // sur le téléphone de quelqu'un.
    ok('Aucune entrée du lexique ne fait défiler la feuille',(()=>{
      const z=document.getElementById('rc-lexique');
      const boite=z&&[...z.children].find(c=>c.tagName==='DIV');
      if(!boite) return _echec('la feuille n’a pas de panneau');
      try{
        const cs=getComputedStyle(boite);
        if(/auto|scroll/.test(cs.overflowY)) return _echec('overflow-y:'+cs.overflowY);
        if(cs.maxHeight!=='none') return _echec('max-height:'+cs.maxHeight+' : la feuille pourra défiler');
        const trop=[];
        for(const k of Object.keys(RC_LEXIQUE)){
          rcInfoOuvrir(k);
          if(boite.scrollHeight>boite.clientHeight+1)
            trop.push(k+' ('+boite.scrollHeight+'>'+boite.clientHeight+')');
        }
        return trop.length?_echec('entrées à raccourcir : '+trop.join(', ')):true;
      } finally { try{ rcInfoFermer(true); }catch(e){} }})());

    // ⚠ AUCUNE NAVIGATION, ET UNE SEULE SORTIE. On est venu chercher un mot ;
    // on doit pouvoir revenir à sa série sans avoir rien décidé. Un lien ou un
    // « en savoir plus » transformerait une réponse de trois lignes en
    // embranchement.
    ok('On ne va nulle part depuis la feuille, et on en sort par un seul bouton',(()=>{
      try{
        rcInfoOuvrir('rir');
        const z=document.getElementById('rc-lexique');
        if(z.querySelector('a')) return _echec('la feuille porte un lien');
        const btns=[...z.querySelectorAll('button')];
        if(btns.length!==1) return _echec(btns.length+' boutons : '+btns.map(b=>b.textContent.trim()).join(' | '));
        if(btns[0].textContent.trim()!=='J\'ai compris')
          return _echec('le bouton dit « '+btns[0].textContent.trim()+' »');
        if((btns[0].getAttribute('onclick')||'').indexOf('rcInfoFermer')<0)
          return _echec('le bouton ne ferme pas');
        // LE FOCUS ARRIVE DESSUS : au clavier, le seul geste possible est
        // d'en sortir.
        if(document.activeElement!==btns[0])
          return _echec('le focus est sur '+(document.activeElement&&document.activeElement.id||'?'));
        // Il ferme vraiment.
        btns[0].onclick(); rcInfoFermer(true);
        return z.style.display==='none'?true:_echec('display='+z.style.display);
      } finally { try{ rcInfoFermer(true); }catch(e){} }})());

    // TROIS SORTIES : le bouton ci-dessus, le voile, et Échap.
    ok('Le voile et la touche Échap ferment aussi la feuille',(()=>{
      const z=document.getElementById('rc-lexique');
      const src=_prodSrc();
      // LE VOILE : le clic sur le fond, et LUI SEUL — event.target===this.
      const oc=z.getAttribute('onclick')||'';
      if(oc.indexOf('event.target===this')<0||oc.indexOf('rcInfoFermer')<0)
        return _echec('le voile ne ferme pas : '+oc);
      // ÉCHAP : le gestionnaire global doit connaître la feuille, et la
      // traiter AVANT la modale — le lexique peut s'ouvrir par-dessus, et
      // Échap défait le dernier geste, pas l'avant-dernier.
      const m=src.match(/if\(e\.key!=='Escape'\) return;[\s\S]{0,1200}/);
      if(!m) return _echec('le gestionnaire d’Échap est introuvable');
      const iL=m[0].indexOf('rc-lexique'), iO=m[0].indexOf('modal-overlay');
      if(iL<0) return _echec('Échap ignore le lexique');
      if(iO>=0&&iL>iO) return _echec('Échap ferme la modale avant le lexique');
      // Et on le joue pour de vrai.
      rcInfoOuvrir('rir');
      if(z.style.display!=='flex') return _echec('la feuille ne s’ouvre pas');
      document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
      const ferme=z.style.display==='none'||z.dataset.sortie==='1';
      try{ rcInfoFermer(true); }catch(e){}
      return ferme?true:_echec('Échap n’a pas fermé la feuille');})());

    // ⚠ UNE DEFINITION NE SURVIT PAS A L'ECRAN QUI L'A OUVERTE. Elle s'ouvre
    // depuis n'importe où : sans ça, elle restait posée par-dessus l'écran
    // suivant, et elle n'expliquait plus rien. Même discipline que la modale
    // de pause et que la saisie, documentée dans go().
    ok('Le lexique meurt avec l\'écran qui l\'a ouvert',(()=>{
      const src=_prodSrc().replace(/\/\/[^\r\n]*/g,'');
      // go() la ferme, et INSTANTANEMENT : une feuille qui sortirait en fondu
      // par-dessus le nouvel écran serait pire que le clignotement d'avant.
      if(!/rcInfoFermer\(true\)/.test(src))
        return _echec('go() ne ferme pas le lexique, ou pas instantanément');
      // ET LE RETOUR MATERIEL LA DEFAIT EN PREMIER, pour la même raison
      // qu'Échap.
      const f=String(_histFermerCalque);
      const iL=f.indexOf('rc-lexique'), iP=f.indexOf('wo-pause-modal');
      if(iL<0) return _echec('le retour matériel ignore le lexique');
      if(iP>=0&&iL>iP) return _echec('le retour ferme la pause avant le lexique');
      return true;})());

    // ══ CE QUE CE LOT NE FAIT PAS ════════════════════════════════════════
    // Il crée le composant, il ne le déploie pas : R07 à R10 poseront les ⓘ.
    // Deux choses devaient rester intactes, et on le constate.
    // R11 — toggleRirExplain A ETE RETIRE, et c'est voulu : Kevin, 17/09/2026,
    // « laisse le RIR, que dans le tableau, la def ». Le panneau « ? » de la
    // séance redisait la fiche RIR. Cette assertion garde donc le seul point
    // qui reste d'actualité : les title= existants.
    ok('R06 ne touche pas aux title= existants',(()=>{
      const src=_prodSrc();
      // Le title= de la consigne RPE en séance : celui que le lexique
      // remplacera un jour, et qui n'est pas retiré aujourd'hui.
      if(src.indexOf('title="Intensité demandée par ton coach')<0)
        return _echec('un title= existant a été retiré');
      return true;})());

    // ══ 16/09/2026 — LES TROIS TUILES RECOIVENT UN REFERENTIEL ═══════════
    //
    // « 2 » séances cette semaine : conforme ou en retard ? « 71 % » de diète
    // respectée : mieux ou moins bien ? Les trois chiffres de l'accueil
    // étaient donnés sans repère. Chaque sous-titre répond à cette
    // question-là, et à rien d'autre.
    //
    // ⚠ ET IL RESTE VIDE QUAND LA DONNEE MANQUE. C'est la règle d'honnêteté
    // tenue partout ailleurs — « RIR non noté », « Première séance ». Un
    // athlète sans données voit exactement ce qu'il voyait avant ce lot.

    // Un décor commun : on peuple, on rend, on lit les trois sous-titres.
    const _subFix=(u,f)=>{
      const _cu=currentUser,_db=DB.get('users');
      const z=document.getElementById('s-client-home');
      const etait=z&&z.classList.contains('active');
      try{
        if(z) z.classList.add('active');
        currentUser=u; DB.set('users',{'sub@t.fr':u});
        _majMetriquesAccueil(u);
        const lis=k=>{ const v=document.getElementById('clh-m'+k),
          b=document.getElementById('clh-m'+k+'-sub');
          return {val:v?v.textContent:null, sub:b?b.textContent:null,
            vert:b?/34,\s*197,\s*94/.test(getComputedStyle(b).color):false,
            n:b}; };
        return f({m1:lis(1),m2:lis(2),m3:lis(3)});
      } finally { currentUser=_cu; if(_db) DB.set('users',_db);
        if(z&&!etait) z.classList.remove('active'); }
    };
    const _subU=o=>Object.assign({email:'sub@t.fr',id:'s1',role:'athlete',
      fname:'Sub',sessions:[],sessions_config:[],bilans:[]},o||{});
    // n jours de diète stricte à partir de `depuis` jours en arrière, dont
    // `bons` respectés. Les autres sont répondus ET ratés — jamais absents :
    // un jour absent ne doit PAS compter, et c'est un autre test.
    const _subJrs=(n,depuis,bons)=>{ const o={};
      for(let i=0;i<n;i++){
        const d=new Date(Date.now()-(depuis+i)*864e5);
        o[localISODate(d)]={respected:i<bons};
      } return o; };

    // ⚠ LA VERIFICATION DEMANDEE, mot pour mot : un nouvel utilisateur doit
    // voir exactement ce qu'il voyait, sans sous-texte parasite.
    ok('Un athlète sans données ne reçoit aucun chiffre inventé',(()=>
      _subFix(_subU({}),r=>{
        // ⚠ LES QUALIFICATIFS SONT FIXES depuis le 16/09/2026 : ils vivent
        // dans le gabarit et ne dependent plus des donnees. Ce qui doit rester
        // vrai, c'est que le CHIFFRE n'invente rien.
        // Sans creneau actif, il n'y a pas de denominateur a annoncer : le
        // tiret, comme avant.
        if(r.m1.val!=='—'||r.m3.val!=='—')
          return _echec('les valeurs ont changé : '+r.m1.val+' / '+r.m3.val);
        // La tuile vide reste effacée, comme avant.
        const box=r.m1.n.closest('.metric-box');
        if(box&&!box.hasAttribute('data-vide'))
          return _echec('la tuile vide a perdu son effacement');
        return true;})));

    // ⚠ « / 0 PREVUES » N'EST PAS UN REFERENTIEL, C'EST UN ZERO AFFICHE.
    // Et le compte NE PASSE PAS par seancesPrevuesParSemaine : elle porte un
    // Math.max(1,…) parce que ecartNormalJours divise par elle, si bien
    // qu'elle aurait annoncé « / 1 prévue » à quelqu'un qui n'a aucun créneau.
    // ⚠ LE QUOTA A DEMENAGE DANS LE CHIFFRE le 16/09/2026 : « 5/6 » au lieu
    // de « 5 » surmonte de « / 6 prévues ». La regle de comptage, elle, n'a
    // pas bouge d'une virgule — et c'est elle que ce test tient.
    ok('Le quota affiché est le vrai nombre de créneaux actifs, ou rien',(()=>{
      if(_creneauxPrevus({sessions_config:[]})!==0)
        return _echec('le compte des créneaux porte un plancher');
      if(seancesPrevuesParSemaine({sessions_config:[]})!==1)
        return _echec('le plancher de seancesPrevuesParSemaine a disparu : ecartNormalJours diviserait par zéro');
      // Aucun créneau : pas de dénominateur à annoncer, donc le tiret seul.
      const a=_subFix(_subU({sessions_config:[{active:false},{active:false}]}),r=>r.m1.val);
      if(a!=='—') return _echec('sans créneau actif, le chiffre dit « '+a+' »');
      // Un seul créneau, aucune séance faite.
      const b=_subFix(_subU({sessions_config:[{active:true},{active:false}]}),r=>r.m1.val);
      if(b!=='0/1') return _echec('un créneau : « '+b+' »');
      // Plusieurs : le compte des ACTIFS, pas la longueur du tableau.
      const c=_subFix(_subU({sessions_config:[{active:true},{active:true},
        {active:false},{active:true}]}),r=>r.m1.val);
      if(c!=='0/3') return _echec('trois créneaux actifs sur quatre : « '+c+' »');
      // ⚠⚠ ET LE CHIFFRE COMPOSE NE S'ANIME PAS. Le nettoyage du compteur rend
      // « 03 » pour « 0/3 » : anime, il se serait emballe — le fichier raconte
      // comment le score hebdomadaire est monte jusqu'a 7777777/7 pour cette
      // raison exacte. met() refuse desormais d'animer ce qui porte un
      // separateur, et data-valeur ne doit donc PAS avoir ete pose.
      const n=_subFix(_subU({sessions_config:[{active:true},{active:true},{active:true}]}),
        r=>document.getElementById('clh-m1').dataset.valeur);
      return n===undefined?true:_echec('le chiffre composé a été animé : data-valeur='+n);})());

    // ⚠ LE MOIS A CEDE LA PLACE A « depuis le début » le 16/09/2026. _moisAnnee
    // reste — elle est juste et eprouvee, et c'est exactement le genre de chose
    // qu'on remet ailleurs — mais elle n'est plus affichee ici. Ce qui compte
    // desormais : le CUMUL, et le qualificatif fixe.
    ok('Le total des séances compte bien toutes les séances',(()=>{
      const T=Date.now(), J=864e5;
      const attendu=new Date(T-400*J).toLocaleDateString('fr-FR',{month:'short',year:'numeric'});
      if(_moisAnnee(T-400*J)!==attendu) return _echec('_moisAnnee a change de forme');
      const r=_subFix(_subU({sessions:[{date:T-2*J},{date:T-400*J},{date:T-90*J}]}),x=>x.m2);
      if(r.sub!=='depuis le début') return _echec('qualificatif : « '+r.sub+' »');
      // ⚠ PAS textContent POUR LE CHIFFRE : arcCompteur l'ANIME, et une
      // lecture synchrone juste apres rend une valeur intermediaire. La
      // valeur qui fait foi est data-valeur, ecrite AVANT l'animation — le
      // piege est documente trente ecrans plus haut dans ce fichier.
      const vv=r.n&&document.getElementById('clh-m2');
      const val=(vv&&vv.dataset&&vv.dataset.valeur!==undefined)?vv.dataset.valeur:r.val;
      if(val!=='3') return _echec('le total a changé : '+val);
      return true;})());

    // LA TENDANCE. Trente jours contre les trente précédents, sur les jours
    // RÉPONDUS des deux côtés.
    // ⚠ LA TENDANCE N'EST PLUS AFFICHEE depuis le 16/09/2026 : le sous-titre
    // de la diète porte le qualificatif fixe « de la diète ». La REGLE, elle,
    // reste juste et éprouvée — c'est exactement le genre de chose qu'on remet
    // ailleurs, sur l'écran Nutrition par exemple. On la teste donc SUR LA
    // FONCTION PURE, sans passer par un rendu qui ne l'affiche plus.
    ok('La tendance de diète compare bien deux fenêtres de trente jours',(()=>{
      const mk=d=>_subU({sessions:[{date:Date.now()-2*864e5}],
        nutrition:{mode:'strict',days:d}});
      const t=u=>_sousTitreTendanceDiete(u,_tauxDieteRespectee(u));
      // 20 jours à 85 % récents, 20 jours à 60 % le mois d'avant : +25.
      const h=t(mk(Object.assign(_subJrs(20,0,17),_subJrs(20,30,12))));
      if(!h||h.t!=='+25 pts') return _echec('hausse : « '+(h&&h.t)+' »');
      if(!h.vert) return _echec('une amélioration n’est pas signalée comme telle');
      // L'inverse : −40, et SURTOUT jamais comme une progression.
      const b=t(mk(Object.assign(_subJrs(20,0,10),_subJrs(20,30,18))));
      if(!b||b.t!=='−40 pts') return _echec('baisse : « '+(b&&b.t)+' »');
      if(b.vert) return _echec('une baisse est donnée pour une progression');
      // ⚠ LE SIGNE MOINS (U+2212), pas le trait d'union.
      if(b.t.charCodeAt(0)!==0x2212)
        return _echec('le signe moins est un trait d’union : U+'+b.t.charCodeAt(0).toString(16));
      // Égalité : « stable », et rien de plus.
      const e=t(mk(Object.assign(_subJrs(20,0,15),_subJrs(20,30,15))));
      if(!e||e.t!=='stable') return _echec('égalité : « '+(e&&e.t)+' »');
      if(e.vert) return _echec('« stable » n’est pas une progression');
      return true;})());

    // ⚠ ON N'INVENTE PAS UNE TENDANCE QU'ON N'A PAS MESUREE. Moins de sept
    // jours notés, ou aucun jour répondu le mois d'avant : on dit combien de
    // jours on a, ce qui est vrai, au lieu d'appeler « stable » un écart
    // qu'on n'a pas pu calculer.
    ok('Sans matière à comparer, la diète compte les jours au lieu de conclure',(()=>{
      const mk=d=>_subU({sessions:[{date:Date.now()-2*864e5}],
        nutrition:{mode:'strict',days:d}});
      const t=u=>_sousTitreTendanceDiete(u,_tauxDieteRespectee(u));
      const a=t(mk(_subJrs(3,0,2)));
      if(!a||a.t!=='3 jours notés') return _echec('trois jours : « '+(a&&a.t)+' »');
      const un=t(mk(_subJrs(1,0,1)));
      if(!un||un.t!=='1 jour noté') return _echec('un seul jour, au singulier : « '+(un&&un.t)+' »');
      // Douze jours, mais rien le mois d'avant : pas de comparaison possible.
      const b=t(mk(_subJrs(12,0,9)));
      if(!b||b.t!=='12 jours notés') return _echec('sans mois précédent : « '+(b&&b.t)+' »');
      // Aucun jour répondu du tout : rien à dire, et « — » sur la tuile.
      if(t(mk({}))!==null) return _echec('sans diète, une tendance est inventée');
      const v=_subFix(mk({}),r=>r.m3.val);
      if(v!=='—') return _echec('sans diète, la tuile affiche : '+v);
      return true;})());

    // ⚠ UN JOUR NON REPONDU N'EST PAS UN JOUR RATE. Le compter ferait tomber
    // le taux de quelqu'un qui n'a rien fait de mal — c'est la règle de
    // jourDieteTenu, et le sous-titre doit la suivre, pas la contredire.
    ok('Les jours non répondus ne pèsent sur aucune des deux fenêtres',(()=>{
      const J=864e5, T=Date.now();
      const d=Object.assign(_subJrs(20,0,17),_subJrs(20,30,12));
      const t=u=>{ const r=_sousTitreTendanceDiete(u,_tauxDieteRespectee(u)); return r&&r.t; };
      const temoin=t(_subU({sessions:[{date:T-2*J}],
        nutrition:{mode:'strict',days:d}}));
      // On ajoute dix jours SANS réponse dans chaque fenêtre.
      // ⚠ SUR DES JOURS LIBRES, ET C'EST TOUT LE SOIN DU TEST. La premiere
      // version posait le bruit sur 20→34, qui MORD sur les jours 30→34 de
      // la fenetre precedente : elle effaçait cinq jours repondus au lieu
      // d'en ajouter d'ignores, et le test tombait sur son propre decor. Les
      // reponses occupent 0→19 et 30→49 ; le bruit va donc en 20→29 (dans la
      // fenetre recente) et 50→59 (dans la precedente), sans rien recouvrir.
      const bruit=Object.assign({},d);
      for(const dep of [20,50]) for(let i=0;i<10;i++)
        bruit[localISODate(new Date(T-(dep+i)*J))]={note:'rien'};
      const avec=t(_subU({sessions:[{date:T-2*J}],
        nutrition:{mode:'strict',days:bruit}}));
      return temoin===avec?true
        :_echec('le bruit a changé la tendance : « '+temoin+' » → « '+avec+' »');})());

    // ══ LE SOUS-TITRE TIENT DANS LA TUILE ════════════════════════════════
    //
    // ⚠ CE TEST A TROUVE LE DEFAUT, et il reste pour ça. Les libellés
    // d'origine — « depuis septembre 2026 », « +25 pts vs mois dernier »,
    // « sur 12 jours notés » — demandaient 130, 126 et 94 px dans une tuile
    // qui en offre 78 à 320 px et 85 à 390. Ils étaient tronqués à TOUTES les
    // largeurs de téléphone, donc pour tout le monde et tout le temps.
    // Un référentiel tronqué n'est plus un référentiel.
    //
    // La mesure se fait sur une SONDE à la police du sous-titre, contre le
    // budget de la tuile la plus étroite : elle ne dépend donc pas de la
    // largeur de la fenêtre où tourne la suite.
    ok('Aucun sous-titre de tuile ne dépasse la largeur d\'une tuile',(()=>{
      const b=document.getElementById('clh-m1-sub');
      if(!b) return _echec('le sous-titre n’existe plus');
      const cs=getComputedStyle(b);
      // ⚠ LE QUALIFICATIF S'ENVELOPPE DESORMAIS, et c'est voulu : « depuis le
      // début » demande 100 px pour 70 disponibles a 320 px. Deux lignes de
      // 11 px valent mieux qu'une ligne coupee — et rien ici n'oblige a tenir
      // sur une seule, contrairement au LIBELLE juste au-dessus, qui doit se
      // lire d'un coup d'oeil et que son assertion tient a une ligne.
      if(parseFloat(cs.fontSize)<11)
        return _echec('le qualificatif est passé sous le plancher : '+cs.fontSize);
      const sonde=document.createElement('span');
      sonde.style.cssText='position:fixed;left:-9999px;top:0;white-space:nowrap';
      sonde.style.font=cs.font||(cs.fontWeight+' '+cs.fontSize+' '+cs.fontFamily);
      sonde.style.fontSize=cs.fontSize; sonde.style.fontFamily=cs.fontFamily;
      sonde.style.fontWeight=cs.fontWeight; sonde.style.letterSpacing=cs.letterSpacing;
      document.body.appendChild(sonde);
      try{
        // 78 px : la largeur utile de la tuile sur un écran de 320 px, le plus
        // étroit que le produit vise. Mesurée au navigateur.
        const BUDGET=78;
        const large=t=>{ sonde.textContent=t; return sonde.getBoundingClientRect().width; };
        // LES PIRES CAS DE CHAQUE LIBELLE, pas des exemples commodes.
        // LES TROIS QUALIFICATIFS, tels qu'ils sont ecrits dans le gabarit.
        // Ils peuvent s'envelopper : ce qu'on verifie ici, c'est qu'aucun MOT
        // pris seul ne deborde — un mot plus large que la tuile serait coupe
        // quoi qu'il arrive, et l'enveloppement n'y pourrait rien.
        const mots=[];
        document.querySelectorAll('#clh-stats .clh-m-sub').forEach(e=>{
          String(e.textContent||'').split(/\s+/).forEach(m=>{ if(m) mots.push(m); }); });
        if(!mots.length) return _echec('les qualificatifs sont vides');
        const trop=mots.filter(t=>large(t)>BUDGET)
          .map(t=>'« '+t+' » '+Math.ceil(large(t))+'px');
        if(trop.length) return _echec(trop.length+' mot(s) au-delà de '+BUDGET+'px : '+trop.join(' | '));
        // TEMOIN : la sonde mesure bien quelque chose. Sans lui, une police
        // qui ne charge pas rendrait zéro partout et le test passerait à vide.
        if(!(large('/ 12 prévues')>20))
          return _echec('la sonde ne mesure rien : police absente ?');
        return true;
      } finally { sonde.remove(); }
    })());

    // ⚠ LE VERT S'EFFACE. _majMetriquesAccueil pose la couleur EN LIGNE et la
    // retire avec style.color='' — qui SUPPRIME la déclaration au lieu de la
    // restaurer. C'est pour cela que le gris de base vit dans .clh-m-sub :
    // une base posée en ligne aurait disparu au premier rendu non-vert, et le
    // sous-titre serait resté sans couleur. Même piège que #clh-stats.
    // ⚠ LE VERT N'EST PLUS POSE SUR CET ECRAN : le qualificatif est fixe. Ce
    // que cette assertion garde reste vrai et vaut pour le jour ou la tendance
    // reviendra : la couleur de base vit dans la FEUILLE, pas en ligne, parce
    // que style.color='' SUPPRIME la declaration au lieu de la restaurer.
    ok('La couleur du qualificatif vit dans la feuille, pas en ligne',(()=>{
      const b=document.getElementById('clh-m3-sub');
      if(!b) return _echec('le sous-titre de la diète n’existe plus');
      // La mise en forme n'est PAS en ligne dans le gabarit.
      const src=_prodSrc();
      if(/id="clh-m[123]-sub"[^>]*style=/.test(src)||/style=[^>]*id="clh-m[123]-sub"/.test(src))
        return _echec('un sous-titre porte encore une mise en forme en ligne');
      const css=_stylesProd().map(x=>x.textContent)
        .join('\n').replace(/\/\*[\s\S]*?\*\//g,' ');
      if(!/\.clh-m-sub\{[^}]*color:/.test(css))
        return _echec('la couleur de base n’est pas dans la feuille : elle sera effacée');
      // ON PEINT A LA MAIN, puis on efface comme le fait met() : c'est
      // l'effacement qu'on eprouve, pas le calcul qui le declenche.
      b.style.color='var(--green)';
      if(!/34,\s*197,\s*94/.test(getComputedStyle(b).color))
        return _echec('le vert ne s’applique pas : le test ne prouve rien');
      b.style.color='';
      const ap=getComputedStyle(b).color;
      if(/34,\s*197,\s*94/.test(ap)) return _echec('le vert a survécu : '+ap);
      // ⚠ ET UNE COULEUR REPREND LA MAIN — pas « aucune couleur ». Une base
      // posée en ligne aurait disparu avec l'effacement.
      if(!/^rgb/.test(ap)||/rgba\(0,\s*0,\s*0,\s*0\)/.test(ap))
        return _echec('le qualificatif n’a plus de couleur : '+ap);
      return true;})());

    // ══ 15/09/2026 — LE BIFRÖST : DES COLONNES, ET PLUS AUCUNE COUPE ═════
    //
    // « remets les lignes type Bifröst de Thor derrière comme ça, mais joue
    // sur l'opacité en haut pour qu'elles se fondent sans avoir de
    // démarcation nette. » — Kevin, 15/09/2026.
    //
    // ⚠ LE BORD N'ETAIT PAS DANS CE QUI PORTAIT LA LUMIERE, IL ETAIT DANS CE
    // QUI LA COUPAIT. On a cherche trois tours dans le faisceau — masques,
    // degrades, opacites — alors que le trait horizontal sous la date etait
    // le halo du hero, tranche net par son propre overflow:hidden 25 px
    // au-dessus du centre de son disque, la ou il est le plus dense.
    //
    // D'ou la regle que ces assertions tiennent, et qui vaut pour tout ce
    // bloc : UNE COUCHE QUI EST COUPEE DOIT ETRE DEJA ETEINTE A L'ENDROIT DE
    // LA COUPE. Soit on retire la coupe, soit on eteint avant elle. Il n'y a
    // pas de troisieme reponse, et « c'est a peine visible » n'en est pas
    // une : 15 % de rouge plein sur 388 px de large se voit.
    ok('Aucune couche n\'est coupée là où elle porte encore de la lumière',(()=>{
      // Un decor hors champ : les styles calculES demandent un element rendu.
      const b=document.createElement('div');
      b.style.cssText='position:fixed;left:-9999px;top:0;width:390px;height:300px';
      b.innerHTML='<div class="rcf-hero"><div class="rcf-trait"></div></div>'
        +'<section class="rcf-rec"><div class="rcf-faisceau"></div>'
        +'<div class="rcf-rec-g n3"></div></section>';
      document.body.appendChild(b);
      try{
        // ⚠ LE HALO DU HERO N'EST PLUS COUPE. C'est LE correctif de ce lot :
        // son disque de 300 px vivait dans une boite de 129, et la coupe
        // tombait sur sa partie la plus dense.
        const hero=b.querySelector('.rcf-hero');
        const co=getComputedStyle(hero);
        if(co.overflowY==='hidden'||co.overflowX==='hidden')
          return _echec('.rcf-hero coupe de nouveau son halo : '+co.overflow);
        const f=b.querySelector('.rcf-faisceau');
        const cf=getComputedStyle(f);
        // Le faisceau, LUI, garde sa coupe : l'encre de son flou de 40 px
        // peint hors de la boite et ouvrait 20 px de defilement lateral.
        // Elle est sans danger parce que le masque eteint avant elle — c'est
        // tout l'objet des deux verifications qui suivent.
        if(cf.overflowX!=='hidden')
          return _echec('le faisceau ne borne plus l’encre de son flou');
        // ⚠ UN AXE PAR ELEMENT. Deux masques sur le MEME element ont deja
        // coute un rectangle : mask-composite:intersect et
        // -webkit-mask-composite:source-in ne sont pas equivalents, et la ou
        // la composition ne s’applique pas le masque degenere — la couche
        // reparait entiere, bords compris. Cette porte reste fermee.
        // ⚠ ON RETIRE LES COMMENTAIRES AVANT DE CHERCHER. C'est la septieme
        // fois que le depot l'apprend : la sonde trouvait le mot dans le
        // commentaire qui explique pourquoi il ne faut PAS l'ecrire. Une
        // regle porte sur les declarations, jamais sur la prose.
        const css=_stylesProd().map(x=>x.textContent)
          .join('\n').replace(/\/\*[\s\S]*?\*\//g,' ');
        if(/mask-composite/.test(css))
          return _echec('mask-composite est revenu : le masque peut degenerer');
        const M=(el,ps)=>{ const c=getComputedStyle(el,ps||null);
          const v=c.maskImage&&c.maskImage!=='none'?c.maskImage:c.webkitMaskImage;
          return (v&&v!=='none')?v:''; };
        const hz=M(f), vt=M(f,'::before'), vt2=M(f,'::after');
        if(!/linear-gradient\(\s*90deg/.test(hz))
          return _echec('le cadre ne porte plus l’extinction horizontale : '+hz.slice(0,60));
        // ⚠ LE STYLE CALCULE EFFACE « 180deg ». C'est la direction par
        // defaut d'un degrade lineaire, et le navigateur la rend en
        // l'omettant : chercher le mot faisait tomber l'assertion sur un
        // masque parfaitement correct. On verifie donc ce qui compte — que
        // la couche descend, et surtout qu'elle ne porte PAS l'axe du cadre.
        const versLeBas=v=>/^linear-gradient\(\s*(?:(?:180deg|to\s+bottom)\s*,)?\s*rgba?\(/.test(v)
          &&!/\b(?:90deg|270deg|to\s+(?:left|right))\b/.test(v);
        for(const v of [vt,vt2])
          if(!versLeBas(v))
            return _echec('une couche ne porte plus l’extinction verticale : '+v.slice(0,70));
        // Les arrets, lus dans le style CALCULE : c’est le masque REEL, pas
        // celui qu’on croit avoir ecrit.
        // ⚠ ET LE CALCUL REND « 0px » LA OU ON A ECRIT « 0 ». Un lecteur qui
        // n'accepte que les pourcentages perd le premier arret, donc la
        // valeur au bord — exactement celle qu'on vient verifier. On accepte
        // les deux unites et on ramene tout en pourcentage.
        const arrets=(g,L)=>{ const o=[]; const re=/rgba?\(([^)]*)\)\s+(-?[\d.]+)(%|px)/g; let m;
          while((m=re.exec(g))){ const p=m[1].split(',').map(x=>parseFloat(x));
            const v=parseFloat(m[2]);
            o.push([m[3]==='%'?v:(L>0?v/L*100:0), p.length>3?p[3]:1]); }
          return o; };
        // Alpha du masque a une position donnee, interpolation lineaire :
        // exactement ce que le navigateur peint.
        const a=(st,x)=>{ if(!st.length) return 1;
          if(x<=st[0][0]) return st[0][1];
          for(let i=1;i<st.length;i++){ if(x<=st[i][0]){
            const [p0,a0]=st[i-1],[p1,a1]=st[i];
            return p1===p0?a1:a0+(a1-a0)*(x-p0)/(p1-p0); } }
          return st[st.length-1][1]; };
        // ⚠ L'AXE VERTICAL SE LIT DANS LES POURCENTAGES DE LA COUCHE, PAS DU
        // CADRE, et les deux ne coincident pas : inset:-10% 0 donne a la
        // couche 120 % de la hauteur du cadre. On calcule donc ou tombe la
        // coupe AU LIEU de recopier 8,33 % — si l'inset change un jour,
        // l'assertion suit.
        // ⚠ PAS getBoundingClientRect ICI. Le faisceau porte une animation
        // d'entree qui passe par scaleY(.88) : le rectangle rendu vaut 88 %
        // de la hauteur de MISE EN PAGE tant qu'elle joue, et le rapport
        // couche/cadre sortait a 1,36 au lieu de 1,20 — l'assertion accusait
        // un masque parfaitement correct. Les pourcentages d'un inset se
        // resolvent sur la boite de mise en page, jamais sur la transformee.
        const cf2=getComputedStyle(f);
        const hc=parseFloat(cf2.height)||0, lc=parseFloat(cf2.width)||0;
        const hp=parseFloat(getComputedStyle(f,'::before').height)||0;
        if(!(hc>0&&hp>hc))
          return _echec('la couche ne deborde plus du cadre : '+hc+' / '+hp);
        const deb=(hp-hc)/2;
        const coupeHaut=deb/hp*100, coupeBas=(deb+hc)/hp*100;
        // L'AXE HORIZONTAL : nul aux deux bords, la ou overflow:hidden coupe.
        const sh=arrets(hz,lc);
        if(!sh.length) return _echec('le masque horizontal n’a aucun arret');
        for(const x of [0,100])
          if(a(sh,x)>0.001)
            return _echec('le masque horizontal porte '+a(sh,x).toFixed(3)+' a '+x+' % : la coupe se verra');
        for(const v of [vt,vt2]){
          const sv=arrets(v,hp);
          if(!sv.length) return _echec('un masque vertical n’a aucun arret');
          for(const y of [0,coupeHaut,coupeBas,100])
            if(a(sv,y)>0.001)
              return _echec('le masque vertical porte '+a(sv,y).toFixed(3)
                +' a '+y.toFixed(2)+' % : c’est la demarcation que Kevin voit');
          // ET IL EST BIEN ALLUME AU MILIEU : un masque nul partout ne
          // laisserait plus rien a voir, et passerait la verification du haut.
          if(a(sv,52)<0.98)
            return _echec('le masque vertical eteint aussi le milieu : '+a(sv,52).toFixed(2));
        }
        // ⚠ ET LA MONTEE EST LONGUE. C’est elle qui remplace le trait : un
        // masque qui passe de 0 a 1 en cinq pour cent redonne un bord, meme
        // sans coupe. On exige que la lumiere mette au moins un quart de la
        // hauteur a naitre.
        const sv=arrets(vt,hp);
        let d=coupeHaut, ff=100;
        for(let y=coupeHaut;y<=100;y+=0.5){ if(a(sv,y)>0.02){ d=y; break; } }
        for(let y=d;y<=100;y+=0.5){ if(a(sv,y)>=0.99){ ff=y; break; } }
        if(ff-d<25)
          return _echec('la lumiere naît en '+(ff-d).toFixed(1)+' % de la hauteur : trop vite, ça refait un bord');
        return true;
      } finally { b.remove(); }
    })());

    // LES COLONNES. « Remets les lignes type Bifröst » : elles avaient
    // disparu — pas retirees, NOYEES. Le lavis de fond etait a .72 sur 34 px
    // de flou, les colonnes a .78 sur 9 px : capture faite, le bloc rendait
    // une nappe rouge uniforme ou pas une seule raie ne se lisait.
    //
    // ⚠ CE N'EST PAS UN REGLAGE, C'EST UN ORDRE. Le lavis doit rester plus
    // FAIBLE et plus FLOU que les colonnes, sinon il repasse devant elles.
    // Les deux couches peuvent etre retouchees tant que cet ordre tient.
    ok('Les colonnes du Bifröst passent devant le lavis, et non l\'inverse',(()=>{
      const b=document.createElement('div');
      b.style.cssText='position:fixed;left:-9999px;top:0;width:390px;height:300px';
      b.innerHTML='<section class="rcf-rec"><div class="rcf-faisceau"></div>'
        +'<div class="rcf-rec-g n3"></div></section>';
      document.body.appendChild(b);
      try{
        const f=b.querySelector('.rcf-faisceau');
        const av=getComputedStyle(f,'::before'), ap=getComputedStyle(f,'::after');
        const flou=c=>{ const m=String(c.filter).match(/blur\(([\d.]+)px\)/); return m?parseFloat(m[1]):-1; };
        const oAv=parseFloat(av.opacity), oAp=parseFloat(ap.opacity);
        const fAv=flou(av), fAp=flou(ap);
        if(!(fAv>0&&fAp>0)) return _echec('une couche n’est plus floue : '+fAv+' / '+fAp);
        if(!(oAp>oAv))
          return _echec('le lavis ('+oAv+') est aussi dense que les colonnes ('+oAp+') : il les noie');
        if(!(fAp<fAv))
          return _echec('les colonnes ('+fAp+'px) sont aussi floues que le lavis ('+fAv+'px) : ce ne sont plus des colonnes');
        // Assez net pour se lire comme des colonnes, assez flou pour n’avoir
        // aucun contour. Entre les deux, il n’y a pas de bord a voir.
        if(fAp<3||fAp>7.5)
          return _echec('le flou des colonnes est hors plage : '+fAp+'px');
        // ET LE DEGRADE EST TOUJOURS IRREGULIER : un pas constant se lit
        // comme une texture, un pas irregulier comme de la lumiere.
        const g=String(ap.backgroundImage);
        const pos=(g.match(/([\d.]+)%/g)||[]).map(parseFloat);
        if(pos.length<20) return _echec('les colonnes ont disparu du degrade : '+pos.length+' arrets');
        const ec=[]; for(let i=1;i<pos.length;i++) if(pos[i]>pos[i-1]) ec.push(pos[i]-pos[i-1]);
        const moy=ec.reduce((a,c)=>a+c,0)/ec.length;
        const va=Math.sqrt(ec.reduce((a,c)=>a+(c-moy)*(c-moy),0)/ec.length);
        if(va<0.25) return _echec('les ecarts sont devenus reguliers : c’est un code-barres, pas de la lumiere');
        return true;
      } finally { b.remove(); }
    })());

    // ══ 15/09/2026 — LE GRIMPEUR ESCALADE, IL NE SAUTE PLUS ══════════════
    //
    // « il faut qu'on le voie progresser de marche en marche comme s'il
    // escaladait, l'animation doit être plus complexe qu'un simple saut, il
    // doit adopter des comportements selon les marches, même avoir l'air de
    // galérer à la fin et symboliser l'obsession. » — Kevin, 15/09/2026.
    //
    // Cinq exigences, et chacune a son assertion : il part du bas, il PASSE
    // par chaque marche, l'effort CHANGE avec la hauteur, la derniere le fait
    // GLISSER, et il ne se repose jamais ensuite.

    // ⚠ SA PLACE DE REPOS VIENT DU GABARIT, PAS DU JAVASCRIPT. Sans cela,
    // « animations reduites », un echec de mesure ou un ecran jamais affiche
    // le laissaient en bas a gauche de la volee.
    ok('Le grimpeur est pose sur sa marche sans JavaScript',(()=>{
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.rcf-grimpeur\{([^}]*)\}/);
      if(!m) return _echec('la regle .rcf-grimpeur n’existe plus');
      // Un `left` fixe dans la feuille contredirait le `left` en ligne du
      // gabarit, qui est calcule marche par marche.
      if(/(^|;)\s*left\s*:/.test(m[1]))
        return _echec('la feuille repose un left fixe : il ecraserait celui du gabarit');
      // Et plus aucune animation CSS : le chemin depend de hauteurs mesurees,
      // il ne peut pas etre ecrit dans une feuille.
      if(/animation\s*:/.test(m[1]))
        return _echec('une animation CSS est revenue sur le grimpeur');
      if(/@keyframes\s+rcfGrimpe\b/.test(css))
        return _echec('@keyframes rcfGrimpe est du code mort');
      // Le gabarit, lui, DOIT poser les deux coordonnees et le rang.
      const src=String(_htmlProchainObjectif);
      for(const t of ['data-ici=','left:','bottom:'])
        if(src.indexOf(t)<0) return _echec('le gabarit ne pose plus '+t);
      return true;})());

    // LE CHEMIN EST PUR : des ecarts en pixels, aucune mesure dedans. C'est ce
    // qui permet de le verifier ici sans monter l'ecran.
    const _ecMarches=n=>{ const e=[]; for(let i=0;i<n;i++) e.push({x:(i-(n-1))*34,y:((n-1)-i)*14.5}); return e; };
    const _xy=k=>{ const m=String(k.transform).match(/translate\((-?[\d.]+)px,\s*(-?[\d.]+)px\)/);
      return m?{x:parseFloat(m[1]),y:parseFloat(m[2])}:null; };
    const _rot=k=>{ const m=String(k.transform).match(/rotate\((-?[\d.]+)deg\)/);
      return m?parseFloat(m[1]):null; };

    ok('Le grimpeur passe par CHAQUE marche, il ne saute pas a la derniere',(()=>{
      const ec=_ecMarches(5), c=_grimpeurChemin(ec,4);
      if(!c||!c.images||c.images.length<12)
        return _echec('le chemin tient en '+((c&&c.images)?c.images.length:0)+' images : c’est un saut');
      // ⚠ PUR : deux appels, deux resultats identiques.
      if(JSON.stringify(_grimpeurChemin(_ecMarches(5),4))!==JSON.stringify(c))
        return _echec('le chemin n’est pas pur');
      // Il part du BAS : la premiere image est a hauteur de la marche 0.
      const p0=_xy(c.images[0]);
      if(!p0||Math.abs(p0.y-ec[0].y)>14)
        return _echec('il n’entre pas par le bas de la volee : y='+(p0&&p0.y));
      if(c.images[0].opacity!==0) return _echec('il apparait au lieu d’arriver');
      // ET IL SE TIENT DEBOUT SUR CHACUNE : une image par marche, exactement a
      // sa place, sans rotation ni deformation. C'est la difference entre
      // « il monte » et « il passe devant ».
      const arr=[];
      for(let i=0;i<ec.length;i++){
        const j=c.images.findIndex(k=>{ const q=_xy(k);
          return q&&Math.abs(q.x-ec[i].x)<0.02&&Math.abs(q.y-ec[i].y)<0.02
            &&_rot(k)===0&&/scale\(1\.000,1\.000\)/.test(k.transform); });
        if(j<0) return _echec('il ne se pose jamais sur la marche '+i);
        if(arr.length&&j<=arr[arr.length-1]) return _echec('les marches ne sont pas prises dans l’ordre');
        arr.push(j);
      }
      // ⚠ LA DERNIERE IMAGE EST L'IDENTITE, sinon l’animation devrait etre
      // defaite a la fin — et une animation qui doit etre defaite finit par ne
      // pas l’etre.
      const f=c.images[c.images.length-1];
      if(f.offset!==1||f.opacity!==1) return _echec('la derniere image n’est pas posee');
      if(f.transform!=='translateX(-50%) translate(0.00px,0.00px) rotate(0.00deg) scale(1.000,1.000)')
        return _echec('la derniere image n’est pas la place de repos : '+f.transform);
      if(f.transform.indexOf('translateX(-50%)')!==0)
        return _echec('le centrage de la feuille est perdu en cours de route');
      // Les images-cles sont ordonnees, et bornees.
      let prec=-1;
      for(const k of c.images){
        if(!(k.offset>=prec)) return _echec('les images-cles reculent');
        prec=k.offset;
        if(k.offset<0||k.offset>1) return _echec('une image-cle sort de l’intervalle');
        if(k.transform.indexOf('translateX(-50%)')!==0)
          return _echec('une image-cle perd le centrage');
      }
      // IL NE SORT PAS DE LA VOLEE : sans cette borne, un ecart de calcul le
      // ferait deborder du bloc et ouvrirait un defilement lateral.
      const bx=Math.max.apply(null,ec.map(e=>Math.abs(e.x)));
      for(const k of c.images){ const q=_xy(k);
        if(!q||Math.abs(q.x)>bx+22) return _echec('il sort de la volee : x='+(q&&q.x)); }
      return true;})());

    // ⚠ « DES COMPORTEMENTS SELON LES MARCHES » EST UNE EXIGENCE MESURABLE :
    // le temps passe a monter doit CROITRE avec la hauteur. Une cadence
    // constante redonnerait le saut repete cinq fois.
    ok('L\'effort du grimpeur croit avec la hauteur',(()=>{
      const ec=_ecMarches(5), c=_grimpeurChemin(ec,4);
      const t=[];
      for(let i=0;i<ec.length;i++){
        const k=c.images.find(k=>{ const q=_xy(k);
          return q&&Math.abs(q.x-ec[i].x)<0.02&&Math.abs(q.y-ec[i].y)<0.02
            &&_rot(k)===0&&/scale\(1\.000,1\.000\)/.test(k.transform); });
        if(!k) return _echec('marche '+i+' jamais atteinte');
        t.push(k.offset*c.duree);
      }
      const cout=[]; for(let i=1;i<t.length;i++) cout.push(t[i]-t[i-1]);
      for(let i=1;i<cout.length;i++)
        if(!(cout[i]>cout[i-1]))
          return _echec('la marche '+(i+1)+' ne coute pas plus que la precedente : '+cout.join(' / '));
      // ET LA DERNIERE COUTE LE PLUS, de loin : c'est elle qu'il reste a
      // prendre, et c'est tout le propos du bloc.
      const d=cout[cout.length-1];
      if(!(d>=2*cout[0]))
        return _echec('la derniere marche ne coute pas le double de la premiere : '+cout.join(' / '));
      return true;})());

    // « MEME AVOIR L'AIR DE GALERER A LA FIN » : il ne suffit pas que ce soit
    // plus lent. Il doit RATER — approcher le rebord, puis redescendre.
    ok('Le grimpeur galere sur la derniere marche : il glisse et recommence',(()=>{
      const ec=_ecMarches(5), c=_grimpeurChemin(ec,4);
      // Le dernier segment : tout ce qui suit la pose sur l'avant-derniere.
      const j=c.images.map(_xy).findIndex((q,i)=>q&&Math.abs(q.x-ec[3].x)<0.02
        &&Math.abs(q.y-ec[3].y)<0.02&&_rot(c.images[i])===0);
      if(j<0) return _echec('l’avant-derniere marche n’est pas atteinte');
      const seg=c.images.slice(j+1).map(_xy);
      if(seg.length<8) return _echec('la fin tient en '+seg.length+' temps : c’est un saut de plus');
      // Il approche du rebord (y proche de 0, la place de repos)…
      let a=-1; for(let i=0;i<seg.length;i++) if(seg[i].y<=8){ a=i; break; }
      if(a<0) return _echec('il n’approche jamais du rebord');
      // …puis il REDESCEND franchement : la glissade.
      const bas=seg.slice(a+1).reduce((m,q)=>Math.max(m,q.y),-1e9);
      if(!(bas>=seg[a].y+5))
        return _echec('il ne glisse pas : il touche a '+seg[a].y+' et ne redescend qu’a '+bas);
      // …et il finit par passer, une fois, pour de bon.
      const fin=seg[seg.length-1];
      if(Math.abs(fin.x)>0.02||Math.abs(fin.y)>0.02) return _echec('il ne se retablit pas');
      // Le depassement du retablissement : il monte au-dessus de sa marche
      // avant de s’y poser. Sans lui, le geste est mecanique.
      if(!seg.some(q=>q.y<-1)) return _echec('aucun depassement : le retablissement est mou');
      return true;})());

    // « SYMBOLISER L'OBSESSION » : il est arrive, et il ne se repose pas. La
    // boucle est INFINIE — la seule du bloc — et minuscule : au-dela, on
    // regarde un jouet au lieu de lire une tension.
    ok('L\'obsession est une boucle infinie, et elle ne saute pas',(()=>{
      const src=String(_grimpeurObsession);
      if(src.indexOf('iterations:Infinity')<0) return _echec('la boucle s’arrete');
      // ⚠ ELLE PASSE PAR _animer, le seul chemin sanctionne : lui seul
      // respecte « animations reduites ».
      if(src.indexOf('_animer(')<0) return _echec('la boucle court-circuite _animer');
      if(/\.animate\(/.test(src)) return _echec('la boucle appelle animate directement');
      // Premiere et derniere image identiques : autrement, chaque tour
      // commence par un a-coup.
      const m=src.match(/\{offset:0,\s*transform:([^,]+),/);
      if(!m) return _echec('la premiere image de la boucle est introuvable');
      if(!/\{offset:1,\s*transform:i\(0,0,0,1,1\)\}/.test(src.replace(/\s+/g,' ')))
        return _echec('la boucle ne revient pas a son point de depart');
      // Et l'amplitude reste une tension : cinq pixels, pas trente.
      const ec=(src.match(/i\((-?[\d.]+),(-?[\d.]+),/g)||[]).map(x=>x.match(/i\((-?[\d.]+),(-?[\d.]+),/));
      if(!ec.length) return _echec('la boucle ne bouge pas');
      for(const e of ec)
        if(Math.abs(parseFloat(e[1]))>6||Math.abs(parseFloat(e[2]))>6)
          return _echec('la boucle gigote : '+e[0]);
      return true;})());

    // LE BRANCHEMENT. Une animation parfaite que personne ne lance ne vaut
    // rien : les DEUX ecrans qui dessinent l'ascension doivent l'appeler.
    ok('L\'ascension est lancee par les deux ecrans qui la dessinent',(()=>{
      const src=_prodSrc();
      for(const id of ['wd-objectif','sd-objectif'])
        if(src.indexOf('_animerGrimpeur(document.getElementById(\''+id+'\'))')<0)
          return _echec(id+' dessine l’ascension sans la lancer');
      const f=String(_animerGrimpeur);
      // ⚠ LE SEUL CHEMIN SANCTIONNE, ici aussi.
      if(f.indexOf('_animer(')<0||/el\.animate\(|g\.animate\(/.test(f))
        return _echec('l’ascension court-circuite _animer');
      // ⚠ SOUS « ANIMATIONS REDUITES », _animer rend null : on n’arme alors
      // RIEN, surtout pas une boucle infinie.
      if(!/if\(!a\)\s*return;/.test(f))
        return _echec('rien ne garde le cas ou _animer ne joue pas');
      if(f.indexOf('_grimpeurObsession')<0)
        return _echec('l’obsession n’est jamais armee');
      if(f.indexOf('onfinish')>=f.indexOf('_grimpeurObsession'))
        return _echec('l’obsession ne suit pas l’ascension');
      // ⚠ UN SEUL GRIMPEUR VIVANT : l'ecran de fin et l'historique dessinent
      // le meme bloc, et l'obsession est infinie. Sans annulation, relire une
      // seance laissait tourner l'animation du bloc precedent.
      if(f.indexOf('cancel()')<0)
        return _echec('rien n’annule l’animation precedente');
      // ⚠ ET ON MESURE APRES AFFICHAGE : au moment de l'appel, l'ecran qui
      // porte le bloc n'est pas encore monte — tout vaudrait zero.
      if(f.indexOf('requestAnimationFrame')<0)
        return _echec('la mesure est prise avant que l’ecran soit affiche');
      if(!/width>0/.test(f))
        return _echec('rien ne verifie que la volee a une largeur mesurable');
      return true;})());

    // « — Continue ! » — meme tiret, meme lecture, dans la notification
    // d'assiduite. Et l'encouragement doit garder le bord droit du cadre :
    // c'est le tiret qui portait le margin-left:auto.
    ok('L\'encouragement d\'assiduite ne porte plus de tiret',(()=>{
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      if(/\.nb-tiret\s*\{/.test(css)) return _echec('la regle .nb-tiret est encore ecrite');
      const s=String(_htmlNotifAssiduite);
      if(s.indexOf('nb-tiret')>=0) return _echec('la balise du tiret est encore posee');
      if(s.indexOf('Continue')<0) return _echec('l\'encouragement a disparu');
      // LE BORD DROIT EST TENU PAR LA PASTILLE ELLE-MEME, desormais.
      return /\.nb-cta\{[^}]*margin-left:auto/.test(css)
        ?true:_echec('rien ne pousse l\'encouragement vers le bord droit');})());

    // « Prise de masse · 1re semaine » se lisait comme une seule chaine, et le
    // rang de semaine n'est pas ce qu'on vient chercher sur l'accueil.
    ok('Le bandeau de phase nomme l\'objectif, sans rang de semaine',(()=>{
      const u={phase:{type:'masse',debut:Date.now()-20*864e5}};
      const h=_htmlBandeauPhase(u);
      if(!h) return _echec('le bandeau ne sort rien');
      const txt=h.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
      if(txt.indexOf('Objectif actuel :')<0) return _echec('libelle : '+txt);
      if(txt.indexOf('Prise de masse')<0) return _echec('la phase n\'est plus nommee : '+txt);
      if(/semaine/i.test(txt)) return _echec('le rang de semaine est encore la : '+txt);
      // IL RESTE AILLEURS, et c'est tout ce qui compte : ordinalSemaine n'est
      // pas devenue du code mort.
      // ⚠ LE SEUIL ETAIT DE TROIS, calibre sur les appels d'alors. La ligne du
      //   tableau a perdu le sien le 19/09/2026 avec la colonne Phase. On
      //   compte donc les APPELS, definition deduite : un seul suffit a dire
      //   que la fonction sert encore, et le compte ne se perimera plus a
      //   chaque site d'appel qui bouge.
      const prod=_prodSrc();
      const tous=(prod.match(/ordinalSemaine\(/g)||[]).length;
      const defs=(prod.match(/function ordinalSemaine\(/g)||[]).length;
      return (tous-defs)>=1
        ?true:_echec('ordinalSemaine n\'est plus appelee nulle part');})());

    // « Encore 4 pesees cette semaine avant une moyenne fiable » passait a la
    // ligne et faisait grandir la carte d'un rang pour trois mots.
    ok('La ligne sous la pesee du jour tient sur un seul rang',(()=>{
      const css=_stylesProd().map(x=>x.textContent).join('\n');
      const m=css.match(/\.pes-sous\{([^}]*)\}/);
      if(!m) return _echec('la regle .pes-sous n\'existe pas');
      if(m[1].indexOf('white-space:nowrap')<0) return _echec('rien n\'empeche le retour a la ligne');
      // ⚠ LE CORPS RESTE A 11 px. Descendre a 10 faisait tomber « aucun texte
      // de l'accueil athlete ne descend sous le plancher », et cette
      // assertion-la a raison : c'est la PHRASE qui a ete raccourcie.
      if(m[1].indexOf('font-size:var(--fs-xs)')<0)
        return _echec('le corps n\'est plus au cran xs : '+m[1].slice(0,60));
      if(String(renderCartePesee).indexOf('class="pes-sous"')<0)
        return _echec('la carte n\'utilise pas la regle');
      // LA PHRASE A ETE RACCOURCIE, et c'est ce qui la fait tenir : 244 px a
      // 11 px, contre 326 pour l'ancienne. « Cette semaine » ne disait rien de
      // plus — le compte est deja celui de la fenetre de sept jours.
      const s=String(renderCartePesee);
      // LE MOTIF VISE LE CODE, PAS LE COMMENTAIRE. `String(fn)` rend le corps
      // entier, commentaires compris, et celui qui explique ce lot cite
      // justement l'ancienne phrase : sans l'apostrophe fermante et le
      // point-virgule, ce test tombait sur sa propre explication.
      if(s.indexOf(" cette semaine avant une moyenne fiable';")>=0)
        return _echec('la phrase longue est revenue');
      if(s.indexOf(" avant une moyenne fiable'")<0)
        return _echec('la phrase courte a disparu');
      // ET UN REPLI SOUS 340 px : mieux vaut deux rangs qu'une phrase coupee.
      return /@media \(max-width:340px\)\{\.pes-sous\{white-space:normal\}\}/.test(css)
        ?true:_echec('aucun repli sous 340 px');})());
    ok('Le corps du compteur est PLAFONNE par l\'echelle, pas par le cadran',(()=>{
      // 29 × 0,76 fait 22,04 px — deux points au-dessus du dernier cran. Le
      // compteur n'avait pas GRANDI par decision : il l'avait pris en heritant
      // du diametre du cadran, que rien ne relie a l'echelle typographique.
      //
      // ON PLAFONNE PLUTOT QUE DE RETRECIR --sk-d : le ramener a 26 ferait bien
      // tomber le chiffre a 19,76, mais emporterait aussi le cadran, la flambee
      // et le cadre neon — trois pieces dessinees a 29 qu'aucun constat ne
      // remet en cause.
      const css=_stylesProd()
        .map(x=>x.textContent).join('\n').replace(/\/\*[\s\S]*?\*\//g,'');
      if(!/--sk-f:min\(/.test(css))
        return _echec('le corps du chiffre n’est plus plafonné');
      if(!/--sk-d:29px/.test(css))
        return _echec('le cadran a été rétréci au lieu de plafonner le chiffre');
      // ET LE PLAFOND EST LE CRAN, pas un nombre ecrit une seconde fois.
      return /min\(calc\(var\(--sk-d\)\*\.76\),var\(--fs-xl\)\)/.test(css)
        ?true:_echec('le plafond n’est plus le cran --fs-xl');})());
    ok('Un graphique sans donnee ne consomme pas de traversee',(()=>{
      // Le drapeau arcPret et la programmation de la traversee etaient poses en
      // TETE de drawLineChart, donc aussi quand il n'y a rien a tracer : un
      // athlete sans pesee faisait jouer une animation sur un canevas vide.
      // Le drapeau promet « celui-ci sera peint » ; le poser sur un canevas qui
      // sort une ligne plus bas en fait une promesse fausse.
      const src=String(drawLineChart);
      const iGarde=src.indexOf('if(!allVals.length)return;');
      const iPret=src.indexOf("dataset.arcPret='1'");
      const iTrace=src.indexOf('arcTracerCourbes(canvas)');
      if(iGarde<0) return _echec('le garde de liste vide a disparu');
      if(iPret<0||iTrace<0) return _echec('le tracé a disparu du graphique');
      if(!(iPret>iGarde)) return _echec('le drapeau est encore posé avant le test');
      return iTrace>iGarde
        ?true:_echec('la traversée est encore programmée avant le test');})());
    // Test qui manquait : appeler loadClientHome EN ENTIER. Les tests ne
    // sollicitaient que _majMetriquesAccueil, si bien qu'une ecriture vers une
    // case supprimee interrompait toute la fonction sans qu'aucun test tombe.
    ok("loadClientHome va jusqu'au bout après le remaniement",(()=>{
      const sauve=currentUser;
      let err=null;
      try{
        currentUser={id:'a',email:'a@t.fr',fname:'M',role:'athlete',exAlias:{},exMuscles:{},
          bilans:[],sessions:[],sessions_config:[{active:true}],programs:{}};
        loadClientHome();
      }catch(e){ err=e.message; }
      const g=(document.getElementById('clh-greeting')||{}).textContent||'';
      currentUser=sauve;
      return !err&&g.length>0;})(),'');
    ok('Aucune ecriture vers une case supprimee ne subsiste',
       !/clh-sessions|clh-streak-nb|clh-weight/.test(String(loadClientHome)));

    // ══════ DEUX BANDEAUX D'ÉCHÉANCE, DEUX NŒUDS ══════
    //
    // ⚠ ILS ONT PORTÉ LE MÊME IDENTIFIANT, et getElementById ne rend que le
    // PREMIER. Le bloc de préparation s'exécutait AVANT _rendreEcheanceAcces
    // et posait display:none sur le nœud d'accès dès que ligneEcheance rendait
    // '' — le cas de presque tous les athlètes. L'avertissement de fin d'accès
    // était donc écrit dans un nœud invisible, et le second nœud ne recevait
    // jamais rien. Aucune erreur, aucune trace : le bandeau ne s'affichait
    // simplement plus.
    (()=>{
      const J=n=>Date.now()+n*864e5;
      // Un dossier minimal que loadClientHome sait traverser en entier.
      const U=(sup)=>Object.assign({id:'a',email:'ech@t.fr',fname:'M',role:'athlete',
        exAlias:{},exMuscles:{},bilans:[],sessions:[],sessions_config:[{active:true}],
        programs:{}},sup||{});
      const ACCES=()=>({status:'COACHING_SUIVI',accessExpiry:J(3)});
      const PREPA=()=>({echeance:{date:J(5),type:'COMPETITION',fiches:{},journal:[],vueLe:0}});
      const jouer=(sup)=>{
        const sauve=currentUser, sv=window.saveUser;
        window.saveUser=()=>{};
        try{
          currentUser=U(sup);
          try{ loadClientHome(); }catch(e){}
          const acc=document.getElementById('clh-echeance');
          const pre=document.getElementById('clh-echeance-prepa');
          const lire=el=>el?{rempli:(el.innerHTML||'').trim().length>0,
                             display:getComputedStyle(el).display}:null;
          return {acc:lire(acc),pre:lire(pre)};
        } finally { currentUser=sauve; window.saveUser=sv; }
      };

      ok('L\'avertissement de fin d\'accès est VISIBLE après un loadClientHome complet',(()=>{
        // C'est l'assertion qui aurait attrapé le défaut. Elle ne regarde pas
        // le contenu écrit — il l'était déjà — mais ce que l'utilisateur VOIT.
        if(accesJoursRestants(U(ACCES()))!==3)
          return _echec('la prémisse est fausse : '+accesJoursRestants(U(ACCES()))+' jours au lieu de 3');
        const r=jouer(ACCES());
        if(!r.acc) return _echec('le nœud d’accès a disparu');
        if(!r.acc.rempli) return _echec('le bandeau n’est pas écrit');
        return r.acc.display!=='none'
          ?true:_echec('le bandeau est écrit dans un nœud masqué : display « '+r.acc.display+' »');})());

      ok('Sans préparation, le nœud de préparation est masqué et celui d\'accès intact',(()=>{
        const r=jouer(ACCES());
        if(!r.pre) return _echec('le nœud de préparation n’existe pas');
        if(r.pre.rempli) return _echec('une ligne de préparation sort de nulle part');
        if(r.pre.display!=='none') return _echec('le nœud vide reste affiché');
        // ET CELUI D'ACCÈS N'A PAS ÉTÉ TOUCHÉ par le voisin.
        return (r.acc&&r.acc.rempli&&r.acc.display!=='none')
          ?true:_echec('le nœud d’accès a été affecté par la préparation');})());

      ok('Les deux bandeaux actifs : chacun visible, chacun à sa place',(()=>{
        const r=jouer(Object.assign(ACCES(),PREPA()));
        if(!r.acc||!r.acc.rempli||r.acc.display==='none')
          return _echec('le bandeau d’accès n’est pas visible');
        if(!r.pre||!r.pre.rempli||r.pre.display==='none')
          return _echec('la ligne de préparation n’est pas visible');
        // CHACUN SON CONTENU : aucun des deux n'écrit dans l'autre.
        const a=document.getElementById('clh-echeance').innerHTML;
        const p=document.getElementById('clh-echeance-prepa').innerHTML;
        if(a.indexOf('ouvrirEcheanceEcran')>=0)
          return _echec('la préparation a écrit dans le nœud d’accès');
        return p.indexOf('accès se termine')<0
          ?true:_echec('l’accès a écrit dans le nœud de préparation');})());

      ok('Un seul nœud porte l\'identifiant clh-echeance',(()=>{
        const n=document.querySelectorAll('#clh-echeance').length;
        if(n!==1) return _echec(n+' nœuds portent #clh-echeance');
        return document.querySelectorAll('#clh-echeance-prepa').length===1
          ?true:_echec('le nœud de préparation n’est pas unique');})());
    })();

    // ── Message de fin de séance : la chaîne générique a disparu ──
    ok('« Excellent travail » n\'existe plus dans le produit',
       !/Excellent travail/.test(String(finishWorkout))
       &&!/Excellent travail/.test(document.getElementById('s-workout-done').innerHTML));
    ok('buildSessionComparison rend un objet exploitable',(()=>{
      // On ne l'exécute pas (elle dépend de woState) : on vérifie sa signature
      // de sortie, qui est ce dont finishWorkout a besoin.
      const src=String(buildSessionComparison);
      return /return\s*\{html,records,delta/.test(src);})());
    ok('finishWorkout appelle bien le message spécifique',
       /_messageFinSeance\(/.test(String(finishWorkout)));

    // ── Sélecteur de créneau ──
    (function(){
      const sauveU=currentUser, sauveC=_perfCreneau;
      const J=n=>Date.now()-n*864e5;
      currentUser={id:'a',email:'a@t.fr',exAlias:{},exMuscles:{},bilans:[],
        sessions_config:[{active:true,name:'Push'},{active:true,name:'Pull'},{active:false,name:'Off'}],
        sessions:[{id:'s1',date:J(9),slot:0,name:'Push',volume:5000,data:{}},
                  {id:'s2',date:J(6),slot:1,name:'Pull',volume:4000,data:{}},
                  {id:'s3',date:J(2),slot:0,name:'Push',volume:5500,data:{}}]};
      _perfCreneau=null;
      ok('Seuls les créneaux actifs sont proposés',_creneauxActifs(currentUser).length===2);
      ok('Le filtrage ne garde que le créneau choisi',
         _seancesDuCreneau(currentUser,{slot:0,nom:'Push'}).length===2
         &&_seancesDuCreneau(currentUser,{slot:1,nom:'Pull'}).length===1);
      ok('Le titre nomme le créneau',/Volume de tes séances du Push/.test(_htmlVolumeCreneau(currentUser)));
      ok('Un créneau sans séance le dit, sans erreur',(()=>{
        currentUser.sessions_config.push({active:true,name:'Legs'});
        _perfCreneau=3;
        const h=_htmlVolumeCreneau(currentUser);
        return /Aucune séance enregistrée sur ce créneau/.test(h)&&!/canvas/.test(h);})());
      // Séances anciennes sans slot : repli sur le nom, via _memeCreneau.
      ok('Séances anciennes sans slot : appariées par le nom',(()=>{
        currentUser.sessions=[{id:'v1',date:J(20),name:'Push',volume:3000,data:{}},
                              {id:'v2',date:J(10),name:'Push',volume:3200,data:{}}];
        return _seancesDuCreneau(currentUser,{slot:9,nom:'Push'}).length===2;})());
      ok('Un seul créneau actif : aucun sélecteur inutile',(()=>{
        currentUser.sessions_config=[{active:true,name:'Full body'}];
        _perfCreneau=null;
        return _htmlSelecteurCreneau(currentUser)==='';})());
      ok('Aucun créneau actif : aucune exception',(()=>{
        currentUser.sessions_config=[];
        return _htmlVolumeCreneau(currentUser)===''&&_perfCreneauCourant(currentUser)===null;})());
      currentUser=sauveU; _perfCreneau=sauveC;
    })();
    // ══════════════ CONTRE-INDICATION CROISÉE : LA PARTIE DÉBLOQUÉE ══════════════
    // Elle attendait les notes de charge articulaire. On les pose ici pour
    // vérifier la chaîne complète, sans dépendre de la grille réelle du coach.
    (function(){
      const sauveU=currentUser, sauveP=(typeof progEx!=='undefined')?progEx.slice():null;
      const sauveW=(typeof woState!=='undefined')?woState:null;
      const sauveCE=(typeof _coachEditClient!=='undefined')?_coachEditClient:null;
      currentUser={id:'c',email:'c@t.fr',role:'coach',exAlias:{},exMuscles:{},sessions:[],bilans:[],
        chargesSchema:{'charniere-hanche':{'rachis-lombaire':3},
                       'isolation-genou':{'rachis-lombaire':0},
                       'poussee-horizontale':{'rachis-lombaire':1},
                       'tirage-vertical':{'rachis-lombaire':1}}};
      const athlete={id:'a1',email:'a1@t.fr',fname:'Marc',exAlias:{},exMuscles:{},sessions:[],
        bilans:[{type:'depart','deb-health':'hernie L5-S1'}],
        contraintesSante:[{id:'x',zone:'rachis-lombaire',cote:'les-deux',niveau:'douleur',
          libelle:'depuis 2023',source:'coach',date:Date.now(),actif:true}]};
      _coachEditClient=athlete;

      // Critère 1 : avertissement + au moins deux substituts de charge plus basse.
      ok('Critère 1 : le soulevé de terre déclenche l\'avertissement',(()=>{
        return contraintesPourExercice({name:'SOULEVE DE TERRE ROUMAIN HALTERES'},athlete).length===1;})());
      progEx.length=0;
      progEx.push({name:'SOULEVE DE TERRE ROUMAIN HALTERES',series:3,reps:'10',repos:'2 min'});
      const hEd=_blocAvertissementContrainte(progEx[0],0);
      ok('Critère 1 : la contrainte déclarée est rappelée',
         /bas du dos/.test(hEd)&&/ça me fait mal quand je force/.test(hEd.replace(/&#39;/g,"'"))
         &&/depuis 2023/.test(hEd));
      ok('Critère 1 : la phrase « sollicite fortement » est présente',
         /sollicite fortement bas du dos/.test(hEd));
      ok('Critère 1 : au moins deux substituts sont proposés',(()=>{
        const l=substitutsDe({name:'SOULEVE DE TERRE ROUMAIN HALTERES'},{zone:'rachis-lombaire'});
        return l.length>=2&&l.every(x=>x.charge<3);})());
      ok('Critère 8 : le disclaimer accompagne l\'avertissement',hEd.includes(DISCLAIMER_SANTE));
      ok('Critère 8 : aucun libellé n\'autorise ni ne rassure',
         !/sans risque|sûr pour|adapté à ta blessure|soigne|guérit/i.test(hEd));
      ok('L\'exercice n\'est JAMAIS supprimé automatiquement',
         progEx.length===1&&progEx[0].name==='SOULEVE DE TERRE ROUMAIN HALTERES');

      // Critère 2 : « Garder » demande et stocke une justification.
      ok('Critère 2 : la justification est stockée et rappelée',(()=>{
        progEx[0].justificationContrainte='charge légère, technique validée';
        const h=_blocAvertissementContrainte(progEx[0],0);
        return /charge légère, technique validée/.test(h)&&!/sollicite fortement/.test(h);})());

      // Critère 3 : côté athlète, la justification prime sur l'avertissement.
      currentUser=Object.assign({},athlete,{
        chargesSchema:{'charniere-hanche':{'rachis-lombaire':3},'isolation-genou':{'rachis-lombaire':0}}});
      ok('Critère 3 : l\'athlète voit la justification, pas l\'avertissement générique',(()=>{
        const h=_blocContrainteSeance({name:'SOULEVE DE TERRE',justificationContrainte:'on garde, charge légère'},0);
        return /Ton coach a maintenu cet exercice/.test(h)&&/on garde, charge légère/.test(h)
          &&!/Tu as signalé une gêne/.test(h);})());
      // Critère 4 : athlète autonome, contrainte épaule niveau eviter.
      ok('Critère 4 : avertissement et bouton « Je remplace »',(()=>{
        currentUser.contraintesSante=[{id:'y',zone:'epaule',niveau:'eviter',actif:true}];
        currentUser.chargesSchema={'poussee-verticale':{'epaule':3},'isolation-genou':{'epaule':0}};
        const h=_blocContrainteSeance({name:'DEVELOPPE MILITAIRE BARRE'},0);
        return /Tu as signalé une gêne au épaule|Tu as signalé une gêne/.test(h)
          &&/arrête si ça pince/.test(h)&&/Je remplace/.test(h);})());
      ok('Sans substitut disponible, aucun bouton « Je remplace »',(()=>{
        currentUser.chargesSchema={'poussee-verticale':{'epaule':3}};
        const h=_blocContrainteSeance({name:'DEVELOPPE MILITAIRE BARRE'},0);
        return /Tu as signalé une gêne/.test(h)&&!/Je remplace/.test(h);})());
      ok('Critère 8 : le disclaimer accompagne l\'avertissement en séance',
         _blocContrainteSeance({name:'DEVELOPPE MILITAIRE BARRE'},0).includes(DISCLAIMER_SANTE));

      // Critère 5 : la substitution ne touche PAS sessions_config.
      ok('Critère 5 : substitution de séance, programme intact',(()=>{
        currentUser.chargesSchema={'poussee-verticale':{'epaule':3},'isolation-genou':{'epaule':0}};
        currentUser.sessions_config=[{active:true,name:'Push',exercises:[{name:'DEVELOPPE MILITAIRE BARRE'}]}];
        const avant=JSON.stringify(currentUser.sessions_config);
        woState={exercises:[{name:'DEVELOPPE MILITAIRE BARRE',series:3,reps:'10'}],
          sessionData:{0:{sets:[{weight:'40',reps:'10',done:true}]}},startTime:Date.now(),progName:'Push',substitutions:[]};
        _appliquerSubstitut(0,'LEG EXTENSION');
        const apres=JSON.stringify(currentUser.sessions_config);
        return avant===apres&&woState.exercises[0].name==='LEG EXTENSION'
          &&woState.substitutions.length===1
          &&woState.substitutions[0].de==='DEVELOPPE MILITAIRE BARRE'
          &&woState.substitutions[0].vers==='LEG EXTENSION';})());
      ok('Les séries de l\'exercice remplacé sont remises à zéro',
         woState.sessionData[0].sets.every(x=>!x.done&&!x.weight));
      ok('Critère 5 : les substitutions sont sérialisées dans la séance',
         /substitutions:\(woState\.substitutions\|\|\[\]\)\.slice\(\)/.test(String(finishWorkout)));
      ok('Les substitutions survivent à une pause',
         /substitutions:/.test(String(woPersist)));

      // Critère 6 : sous drapeau rouge, RIEN n'est proposé.
      ok('Critère 6 : drapeau rouge, aucun substitut où que ce soit',(()=>{
        poserDrapeauRouge(currentUser,'epaule',['irradiation']);
        const enSeance=_blocContrainteSeance({name:'DEVELOPPE MILITAIRE BARRE'},0);
        const l=substitutsDe({name:'DEVELOPPE MILITAIRE BARRE'},{zone:'epaule'});
        leverDrapeauRouge(currentUser);
        return l.length===0&&!/Je remplace/.test(enSeance);})());

      // Critère 7 : exercice sans fiche — aucune supposition.
      ok('Critère 7 : exercice inconnu du guide, aucun avertissement',(()=>{
        return contraintesPourExercice({name:'MOUVEMENT INVENTE'},currentUser).length===0
          &&_blocContrainteSeance({name:'MOUVEMENT INVENTE'},0)==='';})());
      ok('Schéma non noté : aucun avertissement',(()=>{
        currentUser.chargesSchema={};
        return _blocContrainteSeance({name:'DEVELOPPE MILITAIRE BARRE'},0)==='';})());

      // Modèle de programme sans athlète : rien à croiser.
      ok('Modèle sans athlète rattaché : aucun avertissement',(()=>{
        const sv=_coachEditClient; _coachEditClient=null;
        currentUser={id:'c',email:'c@t.fr',role:'coach',exAlias:{},exMuscles:{},sessions:[],bilans:[]};
        const h=_blocAvertissementContrainte({name:'SOULEVE DE TERRE'},0);
        _coachEditClient=sv;
        return h==='';})());

      if(sauveP){ progEx.length=0; sauveP.forEach(x=>progEx.push(x)); }
      currentUser=sauveU; woState=sauveW; _coachEditClient=sauveCE;
    })();

    // ── Garde de visibilité des rappels ──
    // L'app au premier plan a déjà sa bannière : la notification système par
    // dessus ferait le même message deux fois dans la même seconde.
    ok("App visible : on considère qu'elle est au premier plan",(()=>{
      const d=Object.getOwnPropertyDescriptor(Document.prototype,'visibilityState');
      Object.defineProperty(document,'visibilityState',{value:'visible',configurable:true});
      const r=_appAuPremierPlan();
      delete document.visibilityState; if(d) Object.defineProperty(Document.prototype,'visibilityState',d);
      return r===true;})());
    ok('App cachée : la notification doit partir',(()=>{
      Object.defineProperty(document,'visibilityState',{value:'hidden',configurable:true});
      const r=_appAuPremierPlan();
      delete document.visibilityState;
      return r===false;})());
    ok('visibilityState indisponible : repli sûr, la notification part',(()=>{
      Object.defineProperty(document,'visibilityState',{get(){throw new Error('indisponible');},configurable:true});
      let r; try{ r=_appAuPremierPlan(); }catch(e){ r='EXCEPTION'; }
      delete document.visibilityState;
      return r===false;})());
    ok('Les deux rappels passent par le même garde',
       /_appAuPremierPlan()/.test(String(checkBilanNotifToday))
       &&/_appAuPremierPlan()/.test(String(checkWoReminderToday)));
