        ok('Chaque entrée est un identifiant Ciqual ou une source nommée',(()=>{
          const faux=[];
          for(const [nom,cat,macro] of [['prot',PLAN_CAT_PROTEINES,'p'],['gluc',PLAN_CAT_GLUCIDES,'c']])
            cat.forEach((s,i)=>{
              if(typeof s==='number'){ if(!(s>0)||s!==Math.floor(s)) faux.push(nom+'['+i+'] '+s); return; }
              if(typeof s!=='object'||!s.lib) { faux.push(nom+'['+i+'] sans libellé'); return; }
              if(!(_planNb(s[macro])>0)) faux.push(nom+'['+i+'] '+s.lib+' sans valeur');
            });
          return faux.length?_echec(faux.join(', ')):true;})());
        ok('Les 48 sources Ciqual se rattachent TOUTES à une entrée réelle',(()=>{
          // Cette assertion a besoin de la table en mémoire. Si elle manque,
          // on le DIT plutôt que de passer : c'est le seul test du lot qui
          // vérifie que les identifiants relevés à la main sont les bons.
          if(!Array.isArray(_ciqualDB)||!_ciqualDB.length)
            return _echec('table Ciqual non chargée — lance « await _loadCiqual() » avant testExercices()');
          const faux=[];
          for(const [nom,cat,macro] of [['prot',PLAN_CAT_PROTEINES,'p'],['gluc',PLAN_CAT_GLUCIDES,'c']])
            for(const s of cat){
              if(typeof s!=='number') continue;
              const f=_planCiqual(s);
              if(!f){ faux.push(nom+' #'+s+' introuvable'); continue; }
              if(!(_planNb(f[macro])>0)) faux.push(nom+' '+f.n+' n\'apporte pas cette macro');
            }
          return faux.length?_echec(faux.join(', ')):true;})());
        ok('Les quatre sources hors Ciqual gardent la valeur du coach',(()=>{
          // Quatre et non trois : aux deux absentes de la table (farine
          // d'amande déshuilée, spaghetti de pois chiches) et aux chips de
          // légumes maison s'ajoutent les frites de patate douce, que Ciqual
          // ne porte que sous forme de purée ou de pulpe cuite.
          const hors=[].concat(PLAN_CAT_PROTEINES.slice(),PLAN_CAT_GLUCIDES.slice())
            .filter(s=>typeof s==='object');
          if(hors.length!==4) return _echec(hors.length+' sources hors Ciqual');
          if(hors.some(s=>!s.lib)) return _echec('une source hors Ciqual sans libellé');
          const fa=PLAN_CAT_PROTEINES.find(s=>typeof s==='object');
          return (fa&&fa.p===52)?true:_echec(JSON.stringify(fa));})());
